 ('Q54','AMBIGUITY',NULL,'What is our on-time delivery?',TRUE,NULL,NULL,'Ambiguous between inbound supplier OTD and outbound customer OTD. Must ask which, not silently pick one.'),
 ('Q55','AMBIGUITY',NULL,'What are our freight costs?',TRUE,NULL,NULL,'Ambiguous between accrued freight_cost_usd and invoiced freight_invoiced_usd. Must ask which.'),
 ('Q56','AMBIGUITY',NULL,'How is our inventory doing?',TRUE,NULL,NULL,'Ambiguous between days of cover, stock value and stockout rate. Must ask, or answer all three and say so.'),

 -- ---------------- TRAP (4) ----------------
 ('Q57','TRAP','SC_PLANNER','What was our total inventory value over the last twelve months?',TRUE,'inventory_value_usd','SC_INVENTORY','THE SNAPSHOT TRAP. Summing twelve month-end balances counts the same stock twelve times. Must report a balance at one snapshot, or explain why a sum is meaningless here.'),
 ('Q58','TRAP','SC_PROCUREMENT','What is the average of our monthly supplier on-time delivery rates?',TRUE,'supplier_otd_pct','SC_SUPPLIER','THE AVERAGE-OF-AVERAGES TRAP. Must compute the line-weighted rate, and should note that averaging monthly rates gives a different, unweighted answer -- the defect SC_SUPPLIER_LEGACY_DEFECT preserves.'),
 ('Q59','TRAP',NULL,'Our suppliers deliver late, so why is our customer OTD high?',TRUE,'supplier_otd_pct|otd_pct','SC_ONTOLOGY_360','THE INBOUND/OUTBOUND TRAP. Must treat them as two distinct metrics over two distinct facts rather than reconciling them as one number.'),
 ('Q60','TRAP','SC_ONTOLOGY_STEWARD','What was our on-time delivery last month, including orders due next week?',TRUE,'otd_pct','SC_FULFILLMENT','THE AS-OF TRAP. Future-dated rows are promised activity, not performance. Must exclude them and say that it did.')
AS v(question_id, category, persona_role, question, should_answer, expected_metric_ids, expected_tool, expected_behaviour);

-- ---------------------------------------------------------------------------
-- Integrity: no expected metric id may be absent from the registry.
--
-- A typo here is silent and corrosive: the question can never pass, and the
-- evaluation looks like a model failure rather than a fixture bug.
-- ---------------------------------------------------------------------------

SELECT
  'eval questions referencing an unknown metric id' AS check_name,
  COUNT(*)                                          AS found,
  0                                                 AS expected,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM AGENT_EVAL_QUESTION q,
     LATERAL SPLIT_TO_TABLE(COALESCE(q.expected_metric_ids, ''), '|') v
WHERE TRIM(v.value) <> ''
  AND TRIM(v.value) NOT IN (SELECT metric_id FROM METRIC_DEFINITION);

SELECT
  'eval set shape' AS check_name,
  COUNT(*)                                     AS questions,
  COUNT(DISTINCT category)                     AS categories,
  COUNT_IF(NOT should_answer)                  AS must_refuse,
  COUNT_IF(category = 'AMBIGUITY')             AS ambiguous,
  COUNT_IF(category = 'TRAP')                  AS traps,
  IFF(COUNT(*) = 60 AND COUNT(DISTINCT category) = 15
      AND COUNT_IF(NOT should_answer) = 8
      AND COUNT_IF(category = 'AMBIGUITY') = 3
      AND COUNT_IF(category = 'TRAP') = 4, 'PASS', 'FAIL') AS verdict
FROM AGENT_EVAL_QUESTION;

-- Every governed metric must be exercised by at least one question, or the set
-- has a blind spot exactly where the registry says something matters.
SELECT
  'governed metrics not covered by any question' AS check_name,
  COUNT(*)                                      AS found,
  0                                             AS expected,
  LISTAGG(metric_id, ', ')                      AS uncovered,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM METRIC_DEFINITION d
WHERE NOT EXISTS (
  SELECT 1
    FROM AGENT_EVAL_QUESTION q,
         LATERAL SPLIT_TO_TABLE(COALESCE(q.expected_metric_ids, ''), '|') v
   WHERE TRIM(v.value) = d.metric_id
);

GRANT SELECT ON TABLE AGENT_EVAL_QUESTION TO ROLE SC_ONTOLOGY_STEWARD;


-- ============================================================================
-- FILE: 13_divergence_impact.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 13 — What the divergence actually costs.
--
-- The negative control records a spread of 0.006807 on supplier on-time
-- delivery. On its own that is a number, not a consequence: two thirds of a
-- percentage point sounds like rounding, and a judge or a steward is entitled to
-- ask why anyone should care.
--
-- This file answers that question by MEASUREMENT rather than by assertion. It
-- replays both definitions at supplier grain and asks the only question the
-- business actually acts on: does this supplier meet the governed target?
--
-- THE FINDING, AND WHY IT IS WORSE THAN THE HEADLINE SPREAD SUGGESTS
--
--   * 54 of 300 suppliers genuinely meet the 0.90 target under the governed,
--     line-weighted definition.
--   * The legacy average-of-averages definition reports 66 of them as meeting it.
--   * So 12 suppliers -- 22% of the compliant list -- are handed a pass they did
--     not earn.
--   * The error is ENTIRELY ONE-DIRECTIONAL: 12 false passes, 0 false fails.
--
-- That last line is the point. A defect that wrongly escalated a supplier would
-- be found within a week, because the supplier would dispute it and someone
-- would recheck the arithmetic. A defect that wrongly clears a supplier
-- generates no complaint from anyone, so it survives indefinitely. The cost of
-- an ungoverned metric is not a wrong dashboard; it is a review that never
-- happens.
--
-- SCOPE AND FRAMING. The target is ILLUSTRATIVE, the same convention as
-- sql/03_targets.sql, and the data is synthetic. What is NOT illustrative is the
-- arithmetic: these counts are computed from the same 420,000 receipt lines the
-- governed metric is defined over, against whatever target the registry
-- currently holds. Change the target and the counts recompute; they are not
-- stored.
--
-- WHY A VIEW AND NOT A FIGURE IN THE README. A number written in prose is a
-- number that stops being true the day the data changes. This reads the target
-- from METRIC_DEFINITION and the rates from the canonical fact, so the page can
-- only ever show what is currently the case.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

-- One row per supplier: the same population, scored by both definitions.
--
-- The legacy side reads V_SUPPLIER_OTD_BY_MONTH -- the very view the negative
-- control is built on -- rather than re-deriving the defect here. Re-deriving it
-- would be a second implementation of the bug, free to drift from the one that
-- is actually bound in METRIC_BINDING, and the whole subject of this project is
-- what happens when one definition is expressed twice.
CREATE OR REPLACE VIEW V_SUPPLIER_OTD_VERDICT
  COMMENT = 'Every supplier scored twice: once by the governed line-weighted definition, once by the legacy average-of-averages defect, against the registry target. MISCLASSIFIED marks suppliers the two definitions disagree about.'
AS
WITH tgt AS (
  SELECT target_value
    FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
   WHERE metric_id = 'supplier_otd_pct'
),
scored AS (
  SELECT
    m.supplier_id,
    m.supplier_name,
    m.supplier_region,
    COUNT(*)                                          AS months_observed,
    SUM(m.line_count)                                 AS receipt_lines,
    -- Governed: every receipt line counts once. Reconstituted from the monthly
    -- pre-aggregate by re-applying the weight the defect discards.
    SUM(m.otd_rate * m.line_count) / NULLIF(SUM(m.line_count), 0) AS governed_otd,
    -- Defective: every supplier-month counts once, whatever its size.
    AVG(m.otd_rate)                                   AS legacy_otd
  FROM SUPPLY_CHAIN.CANONICAL.V_SUPPLIER_OTD_BY_MONTH m
  GROUP BY m.supplier_id, m.supplier_name, m.supplier_region
)
SELECT
  s.supplier_id,
  s.supplier_name,
  s.supplier_region,
  s.months_observed,
  s.receipt_lines,
  s.governed_otd,
  s.legacy_otd,
  s.legacy_otd - s.governed_otd                   AS overstatement,
  t.target_value                                  AS target,
  s.governed_otd >= t.target_value                AS meets_target_governed,
  s.legacy_otd   >= t.target_value                AS meets_target_legacy,
  (s.governed_otd >= t.target_value) <> (s.legacy_otd >= t.target_value) AS misclassified,
  CASE
    WHEN s.legacy_otd >= t.target_value AND s.governed_otd < t.target_value THEN 'FALSE_PASS'
    WHEN s.legacy_otd <  t.target_value AND s.governed_otd >= t.target_value THEN 'FALSE_FAIL'
    ELSE 'AGREE'
  END                                             AS verdict_class
FROM scored s
CROSS JOIN tgt t;

-- The one-row summary the application renders. Kept separate from the per-supplier
-- view so a page showing the headline does not have to aggregate it itself --
-- app-layer arithmetic over a governed number is the failure mode this repository
-- exists to remove.
CREATE OR REPLACE VIEW V_DIVERGENCE_IMPACT
  COMMENT = 'Consequence of the supplier-OTD divergence, in decisions rather than decimal places. Recomputed from the registry target and the canonical fact on every read.'
AS
SELECT
  COUNT(*)                                          AS suppliers,
  MAX(target)                                       AS target,
  SUM(receipt_lines)                                AS receipt_lines,
  COUNT_IF(meets_target_governed)                   AS at_target_governed,
  COUNT_IF(meets_target_legacy)                     AS at_target_legacy,
  COUNT_IF(verdict_class = 'FALSE_PASS')            AS false_passes,
  COUNT_IF(verdict_class = 'FALSE_FAIL')            AS false_fails,
  COUNT_IF(misclassified)                           AS misclassified,
  ROUND(COUNT_IF(misclassified) / NULLIF(COUNT(*), 0), 6)                          AS misclassified_share,
  -- How badly the compliant list is inflated. This, not the raw spread, is the
  -- figure a procurement lead would act on.
  ROUND((COUNT_IF(meets_target_legacy) - COUNT_IF(meets_target_governed))
        / NULLIF(COUNT_IF(meets_target_governed), 0), 6)                            AS compliant_list_inflation,
  ROUND(AVG(overstatement), 6)                      AS mean_overstatement,
  ROUND(MAX(overstatement), 6)                      AS max_overstatement
FROM SUPPLY_CHAIN.GOVERNANCE.V_SUPPLIER_OTD_VERDICT;

-- Assertions. Repeated in 90_verify_base.sql.
--
-- The one-directional claim is asserted rather than described: if a future data
-- change ever produces a false FAIL, the narrative above stops being true and
-- the build should say so instead of leaving a stale sentence on the page.
SELECT 'divergence impact is one-directional (no false fails)' AS check_name,
       false_fails,
       IFF(false_fails = 0, 'PASS', 'FAIL') AS status
  FROM V_DIVERGENCE_IMPACT;

SELECT 'the defect misclassifies at least one supplier' AS check_name,
       misclassified,
       IFF(misclassified > 0, 'PASS', 'FAIL') AS status
  FROM V_DIVERGENCE_IMPACT;


-- ============================================================================
-- FILE: 16_supplier_contracts.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 16 - Supplier contracts: the unstructured source, and what it is worth.
--
-- Every other source in this ontology is a table. The brief names supplier
-- systems, and in practice the most consequential supplier data is not in a
-- table at all: it is the contract. The on-time commitment a supplier signed,
-- how that commitment is measured, and what a miss costs them are written in
-- prose, in slightly different words in every agreement, and read by a person
-- when -- and only when -- somebody thinks to look.
--
-- This file makes the contract a first-class ontology entity:
--
--   RAW.SUPPLIER_CONTRACT_DOC          one free-text agreement per supplier
--   CANONICAL.DIM_SUPPLIER_CONTRACT    the terms, extracted by AI_EXTRACT
--   GOVERNANCE.V_CONTRACT_EXTRACTION_ACCURACY
--                                      extraction scored against ground truth
--   GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE
--                                      governed OTD vs. the signed commitment
--   GOVERNANCE.V_CONTRACT_IMPACT       the one-row headline the app renders
--   SEMANTIC.SUPPLIER_CONTRACT_SEARCH  Cortex Search over the clause text
--   SEMANTIC.SC_CONTRACT               the semantic view the agent queries
--
-- WHY THE DOCUMENTS ARE GENERATED, AND WHY THAT IS STILL A REAL TEST
-- The contracts are synthetic, like every other row here, and are written from
-- three differently-worded templates so the extraction has to read rather than
-- pattern-match: "95%", "ninety-five per cent (95%)" and "0.95 of all lines" all
-- mean the same commitment. The generator keeps its own answers in
-- RAW.SUPPLIER_CONTRACT_TERMS_TRUTH, which nothing downstream reads except the
-- accuracy view. So the extraction is SCORED, not asserted -- the same standard
-- the drift test applies to metrics and the eval applies to the chat layer.
--
-- THE FINDING THIS FILE EXISTS TO PRODUCE
-- 13_divergence_impact.sql counts the suppliers the legacy definition wrongly
-- clears. That is a count. Joined to the contract, it becomes money: every one
-- of those suppliers that also breached its signed commitment carries a penalty
-- that the legacy dashboard would never have prompted anyone to claim.
--
-- A SECOND FINDING, WHICH IS A GOVERNANCE FINDING RATHER THAN A NUMBER
-- Roughly a quarter of the agreements define on-time delivery as a monthly
-- average -- the average-of-averages definition this project exists to retire.
-- For those suppliers the contract itself encodes the non-governed metric, so
-- the enforceable number and the governed number differ by construction. They
-- are flagged DEFINITION_CONFLICT for procurement to renegotiate, not silently
-- rescored.
--
-- SCOPE. Penalty rates, caps and commitments are ILLUSTRATIVE, the same
-- convention as sql/03_targets.sql. What is not illustrative is the arithmetic:
-- late-line value is summed from the same 420,000 receipt lines the governed
-- metric is defined over, and both OTD figures are the ones 13 already publishes.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE WAREHOUSE COMPUTE_WH;

-- ---------------------------------------------------------------------------
-- 1. Ground truth. The generator's answers, kept apart from the documents.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE TABLE RAW.SUPPLIER_CONTRACT_TERMS_TRUTH
  COMMENT = 'Generator ground truth for the synthetic supplier contracts. Read ONLY by GOVERNANCE.V_CONTRACT_EXTRACTION_ACCURACY to score AI_EXTRACT. Never a source for any business metric.'
AS
SELECT
  s.supplier_id,
  s.supplier_name,
  s.supplier_region,
  'SCA-' || RIGHT(s.supplier_id, 4) || '-' || (2024 + ABS(HASH(s.supplier_id, 'yr')) % 2)  AS contract_number,
  ABS(HASH(s.supplier_id, 'tpl')) % 3                                                    AS template_id,
  [0.80, 0.82, 0.85, 0.86, 0.88][ABS(HASH(s.supplier_id, 'otd')) % 5]::NUMBER(4,2)       AS otd_commitment,
  IFF(ABS(HASH(s.supplier_id, 'basis')) % 100 < 25, 'MONTHLY_AVERAGE', 'PER_LINE')       AS otd_basis,
  [1, 2, 3, 5][ABS(HASH(s.supplier_id, 'pen')) % 4]::NUMBER(4,1)                         AS penalty_pct,
  [25000, 50000, 100000, 250000][ABS(HASH(s.supplier_id, 'cap')) % 4]::NUMBER(12,0)      AS penalty_cap_usd,
  (14 + ABS(HASH(s.supplier_id, 'lt')) % 47)::NUMBER(4,0)                                AS lead_time_days,
  ['Net 30', 'Net 45', 'Net 60', 'Net 90'][ABS(HASH(s.supplier_id, 'pay')) % 4]::STRING   AS payment_terms,
  ['FCA', 'DAP', 'DDP', 'EXW', 'CIF'][ABS(HASH(s.supplier_id, 'inc')) % 5]::STRING        AS incoterm,
  DATE '2024-10-01'                                                                      AS effective_date,
  DATEADD('year', 2 + ABS(HASH(s.supplier_id, 'exp')) % 2, DATE '2024-09-30')            AS expiry_date
FROM RAW.SUPPLIER s;

-- ---------------------------------------------------------------------------
-- 2. The documents. Free text, three wordings, nothing structured about them.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE TABLE RAW.SUPPLIER_CONTRACT_DOC
  COMMENT = 'Unstructured source: one supply agreement per supplier as free text. The only structured fields are the document id and the supplier it was filed under; every commercial term lives in the prose and reaches the ontology through AI_EXTRACT.'
AS
WITH t AS (
  SELECT *,
    CASE otd_commitment WHEN 0.80 THEN 'eighty' WHEN 0.82 THEN 'eighty-two'
      WHEN 0.85 THEN 'eighty-five' WHEN 0.86 THEN 'eighty-six' ELSE 'eighty-eight' END AS otd_words,
    TO_VARCHAR(otd_commitment * 100, '99')                                     AS otd_pct_txt,
    TO_VARCHAR(penalty_cap_usd, '999,999')                                      AS cap_txt
  FROM RAW.SUPPLIER_CONTRACT_TERMS_TRUTH
)
SELECT
  'DOC-' || supplier_id                                   AS doc_id,
  supplier_id,
  contract_number || '.txt'                               AS file_name,
  CASE template_id
  WHEN 0 THEN
    'SUPPLY AGREEMENT No. ' || contract_number || '\n\n'
    || 'This Supply Agreement is entered into between Buyer and ' || supplier_name
    || ' ("Supplier"), with its principal place of business in the ' || supplier_region || ' region, effective '
    || TO_VARCHAR(effective_date, 'MMMM DD, YYYY') || ' and expiring ' || TO_VARCHAR(expiry_date, 'MMMM DD, YYYY') || '.\n\n'
    || '4. DELIVERY PERFORMANCE. 4.1 Supplier shall deliver no fewer than ' || TRIM(otd_pct_txt)
    || '% of purchase order lines on or before the confirmed delivery date. '
    || IFF(otd_basis = 'PER_LINE',
         '4.2 Performance is measured across all purchase order lines received in the quarter, each line counting equally.',
         '4.2 Performance is measured as the simple average of the monthly on-time percentages reported in the quarter.')
    || ' 4.3 Standard lead time is ' || lead_time_days || ' calendar days from order acknowledgement.\n\n'
    || '5. SERVICE CREDITS. Where Supplier fails to meet clause 4.1, Supplier shall credit Buyer '
    || penalty_pct || '% of the invoiced value of each late line, not to exceed USD ' || TRIM(cap_txt) || ' per contract year.\n\n'
    || '7. COMMERCIAL TERMS. Payment terms are ' || payment_terms || ' from receipt of a valid invoice. Goods are delivered '
    || incoterm || ' (Incoterms 2020).'
  WHEN 1 THEN
    'MASTER PURCHASE AGREEMENT - Ref ' || contract_number || '\n'
    || 'Counterparty: ' || supplier_name || ' (' || supplier_region || ')\n'
    || 'Term: commencing ' || TO_VARCHAR(effective_date, 'YYYY-MM-DD') || ', ending ' || TO_VARCHAR(expiry_date, 'YYYY-MM-DD') || '\n\n'
    || 'Schedule B - Service Levels\n'
    || 'The Vendor commits that ' || otd_words || ' per cent (' || TRIM(otd_pct_txt) || '%) of order lines will arrive by the promised date. '
    || IFF(otd_basis = 'PER_LINE',
         'Compliance is calculated line by line over every receipt in the review period.',
         'Compliance is calculated by averaging each month''s on-time rate over the review period.')
    || ' Quoted replenishment lead time: ' || lead_time_days || ' days.\n'
    || 'Schedule C - Remedies\n'
    || 'For any review period below the service level, the Vendor will issue a rebate equal to ' || penalty_pct
    || ' percent of the value of late lines. Aggregate rebates are capped at $' || TRIM(cap_txt) || ' annually.\n'
    || 'Schedule D - Commercial\n'
    || 'Settlement ' || payment_terms || '. Delivery basis ' || incoterm || '.'
  ELSE
    'Contract ' || contract_number || ' - summary of agreed terms with ' || supplier_name || '.\n'
    || 'We (the purchaser) and ' || supplier_name || ' agree the following from ' || TO_VARCHAR(effective_date, 'DD Mon YYYY')
    || ' until ' || TO_VARCHAR(expiry_date, 'DD Mon YYYY') || '. '
    || 'Lead time is ' || lead_time_days || ' days. '
    || 'The supplier must achieve on-time delivery on at least ' || TO_VARCHAR(otd_commitment, '0.00') || ' of all lines'
    || IFF(otd_basis = 'PER_LINE', ', counted per receipt line', ', counted as the mean of monthly rates')
    || '. If it does not, it owes a penalty of ' || penalty_pct || '% on the value of the late lines, with a yearly ceiling of USD '
    || TRIM(cap_txt) || '. Invoices are paid ' || payment_terms || '; shipping terms ' || incoterm || '.'
  END                                                     AS contract_text,
  -- GENERATED rows have ground truth and are scored; INGESTED rows arrive later
  -- through INGEST_SUPPLIER_CONTRACT and have none, so they are not.
  'GENERATED'                                             AS source,
  CURRENT_TIMESTAMP()                                     AS loaded_at
FROM t;

-- ---------------------------------------------------------------------------
-- 3. Extraction. AI_EXTRACT reads each document. This account rejects the
--    scores argument on text input, so certainty is judged by validation
--    instead: a term that fails to parse or is out of range is flagged
--    NEEDS_REVIEW and routed to a person rather than into a metric.
--
--    ONE DEFINITION OF EXTRACTION. The questions and the parsing live in this
--    procedure and nowhere else. The bulk load below calls it with NULL (every
--    document); INGEST_SUPPLIER_CONTRACT calls it with one supplier. A second
--    copy of the prompt would be free to drift from the first -- the same
--    failure, in the unstructured path, that the drift test catches for metrics.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE TABLE CANONICAL.DIM_SUPPLIER_CONTRACT (
  doc_id           STRING NOT NULL,
  supplier_id      STRING NOT NULL,
  file_name        STRING,
  contract_number  STRING,
  otd_commitment   NUMBER(6,4),
  otd_basis        STRING,
  penalty_pct      NUMBER(6,2),
  penalty_cap_usd  NUMBER(14,0),
  lead_time_days   NUMBER(6,0),
  payment_terms    STRING,
  incoterm         STRING,
  expiry_date      DATE,
  needs_review     BOOLEAN,
  extraction_raw   VARIANT,
  extracted_at     TIMESTAMP_LTZ,
  CONSTRAINT pk_dim_supplier_contract PRIMARY KEY (supplier_id)
) COMMENT = 'sco:SupplierContract - commercial terms extracted from RAW.SUPPLIER_CONTRACT_DOC by AI_EXTRACT (GOVERNANCE.EXTRACT_SUPPLIER_CONTRACTS). One row per supplier. NEEDS_REVIEW marks any extraction whose metric-bearing terms failed to parse or fell out of range.';

CREATE OR REPLACE PROCEDURE GOVERNANCE.EXTRACT_SUPPLIER_CONTRACTS(P_SUPPLIER_ID STRING)
  RETURNS NUMBER
  LANGUAGE SQL
  COMMENT = 'Runs AI_EXTRACT over supplier contract text and upserts CANONICAL.DIM_SUPPLIER_CONTRACT. NULL = every document; a supplier id = that supplier only. Returns rows merged.'
  EXECUTE AS OWNER
AS
$$
DECLARE
  -- ALL = every document, ONE = the named supplier, RETRY = documents whose last
  -- extraction came back with no response. AI_EXTRACT occasionally returns
  -- {"error": "Empty extraction input"} for a perfectly valid 469-character
  -- document and succeeds on the next call; without a retry that document
  -- sits in NEEDS_REVIEW and the accuracy figure drops for a transient reason.
  mode STRING DEFAULT IFF(:P_SUPPLIER_ID IS NULL, 'ALL', 'ONE');
  merged NUMBER DEFAULT 0;
  failed NUMBER DEFAULT 0;
BEGIN
  FOR attempt IN 1 TO 3 DO
  MERGE INTO CANONICAL.DIM_SUPPLIER_CONTRACT tgt
  USING (
    WITH x AS (
      SELECT
        d.doc_id, d.supplier_id, d.file_name,
        AI_EXTRACT(
          text => d.contract_text,
          responseFormat => {
            'contract_number': 'What is the contract or agreement reference number?',
            'otd_commitment':  'What minimum percentage of order lines must be delivered on time? Answer with the number only.',
            'otd_basis':       'Is on-time performance measured per individual line, or as an average of monthly rates? Answer PER_LINE or MONTHLY_AVERAGE.',
            'penalty_pct':     'What percentage of the value of late lines is owed as a penalty, credit or rebate? Answer with the number only.',
            'penalty_cap_usd': 'What is the annual cap on penalties, credits or rebates in US dollars? Answer with the number only.',
            'lead_time_days':  'What is the lead time in days? Answer with the number only.',
            'payment_terms':   'What are the payment terms, for example Net 30?',
            'incoterm':        'What is the Incoterm or delivery basis?',
            'expiry_date':     'On what date does the agreement end? Answer in YYYY-MM-DD format.'
          }
        ) AS r
      FROM RAW.SUPPLIER_CONTRACT_DOC d
      WHERE (:mode = 'ALL')
         OR (:mode = 'ONE' AND d.supplier_id = :P_SUPPLIER_ID)
         OR (:mode = 'RETRY' AND d.supplier_id IN (
               SELECT supplier_id FROM CANONICAL.DIM_SUPPLIER_CONTRACT
                WHERE extraction_raw:response IS NULL OR IS_NULL_VALUE(extraction_raw:response)))
    ),
    p AS (
      SELECT
        doc_id, supplier_id, file_name, r,
        TRY_TO_NUMBER(REGEXP_SUBSTR(r:response:otd_commitment::STRING, '[0-9]+(\\.[0-9]+)?'), 10, 4) AS otd_raw,
        TRY_TO_NUMBER(REGEXP_SUBSTR(r:response:penalty_pct::STRING, '[0-9]+(\\.[0-9]+)?'), 6, 2)     AS penalty_pct,
        TRY_TO_NUMBER(REGEXP_REPLACE(r:response:penalty_cap_usd::STRING, '[^0-9.]', ''), 14, 0)      AS penalty_cap_usd,
        TRY_TO_NUMBER(REGEXP_SUBSTR(r:response:lead_time_days::STRING, '[0-9]+'))                    AS lead_time_days
      FROM x
    )
    SELECT
      doc_id,
      supplier_id,
      file_name,
      r:response:contract_number::STRING                                         AS contract_number,
      -- "95", "95%" and "0.95" all normalise to 0.95.
      IFF(otd_raw > 1, otd_raw / 100, otd_raw)::NUMBER(6,4)                      AS otd_commitment,
      IFF(CONTAINS(UPPER(r:response:otd_basis::STRING), 'MONTH'), 'MONTHLY_AVERAGE', 'PER_LINE') AS otd_basis,
      penalty_pct,
      penalty_cap_usd,
      lead_time_days,
      -- Canonicalised: 'Settlement Net 90.' and 'Net 90 from receipt of invoice' are one term.
      'Net ' || REGEXP_SUBSTR(r:response:payment_terms::STRING, 'Net\\s*([0-9]+)', 1, 1, 'ie', 1) AS payment_terms,
      UPPER(REGEXP_SUBSTR(r:response:incoterm::STRING, '[A-Za-z]{3}'))           AS incoterm,
      TRY_TO_DATE(r:response:expiry_date::STRING)                                AS expiry_date,
      -- A term that would feed a metric but did not parse, or parsed out of range,
      -- goes to a person rather than into the compliance view as a silent NULL.
      (otd_raw IS NULL OR penalty_pct IS NULL OR penalty_cap_usd IS NULL
       OR IFF(otd_raw > 1, otd_raw / 100, otd_raw) NOT BETWEEN 0.5 AND 1)        AS needs_review,
      r                                                                          AS extraction_raw,
      CURRENT_TIMESTAMP()                                                        AS extracted_at
    FROM p
  ) src
  ON tgt.supplier_id = src.supplier_id
  WHEN MATCHED THEN UPDATE SET
    doc_id = src.doc_id, file_name = src.file_name, contract_number = src.contract_number,
    otd_commitment = src.otd_commitment, otd_basis = src.otd_basis, penalty_pct = src.penalty_pct,
    penalty_cap_usd = src.penalty_cap_usd, lead_time_days = src.lead_time_days,
    payment_terms = src.payment_terms, incoterm = src.incoterm, expiry_date = src.expiry_date,
    needs_review = src.needs_review, extraction_raw = src.extraction_raw, extracted_at = src.extracted_at
  WHEN NOT MATCHED THEN INSERT
    (doc_id, supplier_id, file_name, contract_number, otd_commitment, otd_basis, penalty_pct,
     penalty_cap_usd, lead_time_days, payment_terms, incoterm, expiry_date, needs_review,
     extraction_raw, extracted_at)
  VALUES
    (src.doc_id, src.supplier_id, src.file_name, src.contract_number, src.otd_commitment,
     src.otd_basis, src.penalty_pct, src.penalty_cap_usd, src.lead_time_days, src.payment_terms,
     src.incoterm, src.expiry_date, src.needs_review, src.extraction_raw, src.extracted_at);
    IF (attempt = 1) THEN merged := SQLROWCOUNT; END IF;
    SELECT COUNT(*) INTO :failed FROM CANONICAL.DIM_SUPPLIER_CONTRACT
     WHERE extraction_raw:response IS NULL OR IS_NULL_VALUE(extraction_raw:response);
    IF (failed = 0) THEN BREAK; END IF;
    mode := 'RETRY';
  END FOR;
  RETURN merged;
END;
$$;

CALL GOVERNANCE.EXTRACT_SUPPLIER_CONTRACTS(NULL);

-- ---------------------------------------------------------------------------
-- 4. Extraction accuracy, measured. Field by field against the generator.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW GOVERNANCE.V_CONTRACT_EXTRACTION_ACCURACY
  COMMENT = 'AI_EXTRACT scored against generator ground truth, per field. The unstructured path is held to the same standard as the drift test: measured, not asserted.'
AS
WITH j AS (
  SELECT t.*, c.otd_commitment AS x_otd, c.otd_basis AS x_basis, c.penalty_pct AS x_pen,
         c.penalty_cap_usd AS x_cap, c.lead_time_days AS x_lt, c.payment_terms AS x_pay,
         c.incoterm AS x_inc, c.expiry_date AS x_exp, c.contract_number AS x_num
    FROM RAW.SUPPLIER_CONTRACT_TERMS_TRUTH t
    JOIN CANONICAL.DIM_SUPPLIER_CONTRACT c USING (supplier_id)
    -- Only documents the generator wrote have ground truth. An amendment that
    -- arrived through INGEST_SUPPLIER_CONTRACT would otherwise be "wrong" for
    -- differing from the contract it replaced.
    JOIN RAW.SUPPLIER_CONTRACT_DOC d ON d.supplier_id = c.supplier_id AND d.source = 'GENERATED'
)
SELECT field, COUNT(*) AS documents, COUNT_IF(ok) AS correct, ROUND(COUNT_IF(ok) / COUNT(*), 4) AS accuracy
FROM (
  SELECT 'otd_commitment'  AS field, x_otd = otd_commitment                     AS ok FROM j UNION ALL
  SELECT 'otd_basis',                x_basis = otd_basis                               FROM j UNION ALL
  SELECT 'penalty_pct',              x_pen = penalty_pct                               FROM j UNION ALL
  SELECT 'penalty_cap_usd',          x_cap = penalty_cap_usd                           FROM j UNION ALL
  SELECT 'lead_time_days',           x_lt = lead_time_days                             FROM j UNION ALL
  SELECT 'payment_terms',            UPPER(x_pay) = UPPER(payment_terms)               FROM j UNION ALL
  SELECT 'incoterm',                 x_inc = incoterm                                  FROM j UNION ALL
  SELECT 'expiry_date',              x_exp = expiry_date                               FROM j UNION ALL
  SELECT 'contract_number',          x_num = contract_number                           FROM j
)
GROUP BY field;

-- ---------------------------------------------------------------------------
-- 5. Compliance: the governed metric against the signed commitment.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE
  COMMENT = 'Per supplier: governed and legacy supplier OTD (read from V_SUPPLIER_OTD_VERDICT), the contracted commitment extracted from the agreement, breach flags under each definition, and the penalty the contract entitles Buyer to claim.'
AS
-- Both OTD figures are READ from V_SUPPLIER_OTD_VERDICT (13), not re-derived.
-- That view already scores every supplier under the governed and the legacy
-- definition; computing them again here would be a second implementation of
-- the metric, free to drift from the first -- the exact failure this ontology
-- exists to prevent. Only the money is new: late-line value, from the same fact.
WITH late AS (
  SELECT supplier_id,
         COUNT_IF(is_on_time = 0)                                   AS late_lines,
         SUM(IFF(is_on_time = 0, received_qty * actual_price, 0))   AS late_line_value
    FROM CANONICAL.FCT_SUPPLIER_DELIVERY_LINE
   GROUP BY supplier_id
)
SELECT
  s.supplier_id, s.supplier_name, s.supplier_region, s.supplier_tier,
  c.contract_number, c.otd_commitment, c.otd_basis, c.penalty_pct, c.penalty_cap_usd,
  c.lead_time_days, c.payment_terms, c.incoterm, c.expiry_date, c.needs_review,
  v.receipt_lines, l.late_lines, l.late_line_value,
  v.governed_otd,
  v.legacy_otd,
  v.governed_otd < c.otd_commitment                             AS breach_governed,
  v.legacy_otd   < c.otd_commitment                             AS breach_legacy,
  -- Penalty is only claimable on a governed breach, and never above the cap.
  IFF(v.governed_otd < c.otd_commitment,
      LEAST(c.penalty_cap_usd, l.late_line_value * c.penalty_pct / 100), 0)::NUMBER(14,2) AS penalty_exposure_usd,
  -- The money a legacy dashboard leaves on the table: breached, but shown as compliant.
  IFF(v.governed_otd < c.otd_commitment AND v.legacy_otd >= c.otd_commitment,
      LEAST(c.penalty_cap_usd, l.late_line_value * c.penalty_pct / 100), 0)::NUMBER(14,2) AS penalty_missed_by_legacy_usd,
  c.otd_basis = 'MONTHLY_AVERAGE'                               AS definition_conflict,
  CASE
    WHEN c.needs_review THEN 'NEEDS_REVIEW'
    WHEN v.governed_otd < c.otd_commitment AND v.legacy_otd >= c.otd_commitment THEN 'HIDDEN_BREACH'
    WHEN v.governed_otd < c.otd_commitment THEN 'BREACH'
    ELSE 'COMPLIANT'
  END                                                           AS compliance_status
FROM RAW.SUPPLIER s
JOIN CANONICAL.DIM_SUPPLIER_CONTRACT     c USING (supplier_id)
JOIN GOVERNANCE.V_SUPPLIER_OTD_VERDICT   v USING (supplier_id)
JOIN late                                l USING (supplier_id);

CREATE OR REPLACE VIEW GOVERNANCE.V_CONTRACT_IMPACT
  COMMENT = 'One-row headline for the contract layer: breaches, penalty exposure, the share of it a legacy dashboard would hide, definition conflicts, and extraction accuracy.'
AS
SELECT
  COUNT(*)                                                        AS contracts,
  COUNT_IF(breach_governed)                                       AS breaches_governed,
  COUNT_IF(breach_legacy)                                         AS breaches_legacy,
  COUNT_IF(compliance_status = 'HIDDEN_BREACH')                   AS hidden_breaches,
  SUM(penalty_exposure_usd)                                       AS penalty_exposure_usd,
  SUM(penalty_missed_by_legacy_usd)                               AS penalty_missed_by_legacy_usd,
  COUNT_IF(definition_conflict)                                   AS definition_conflicts,
  COUNT_IF(needs_review)                                          AS needs_review,
  (SELECT ROUND(SUM(correct) / NULLIF(SUM(documents), 0), 4)
     FROM GOVERNANCE.V_CONTRACT_EXTRACTION_ACCURACY)              AS extraction_accuracy
FROM GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE;

-- ---------------------------------------------------------------------------
-- 6. Cortex Search over the clause text, for questions a number cannot answer
--    ("what does our agreement with X say about late deliveries?").
-- ---------------------------------------------------------------------------
CREATE OR REPLACE CORTEX SEARCH SERVICE SEMANTIC.SUPPLIER_CONTRACT_SEARCH
  ON contract_text
  ATTRIBUTES supplier_name, supplier_region
  WAREHOUSE = COMPUTE_WH
  TARGET_LAG = '1 day'
  COMMENT = 'Semantic search over supplier agreement text. Grounds clause-level answers; never a source for a metric value.'
AS
SELECT d.doc_id, d.file_name, d.contract_text, s.supplier_name, s.supplier_region
  FROM RAW.SUPPLIER_CONTRACT_DOC d
  JOIN RAW.SUPPLIER s USING (supplier_id);

-- ---------------------------------------------------------------------------
-- 7. The semantic view. Contract terms become ontology, not column names.
-- ---------------------------------------------------------------------------
-- SUPPLIER is joined as the conformed dimension rather than read off the
-- compliance view's own columns, so /ontology draws SupplierContract -> Supplier
-- as an edge of the same graph instead of an island with look-alike columns.
CREATE OR REPLACE SEMANTIC VIEW SEMANTIC.SC_CONTRACT
  TABLES (
    CONTRACT as SUPPLY_CHAIN.GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE primary key (SUPPLIER_ID)
      with synonyms=('supplier contract','supply agreement','contract compliance')
      comment='sco:SupplierContract - one agreement per supplier, terms extracted by AI_EXTRACT from the contract text, scored against the governed supplier OTD. Fact, contract grain.',
    SUPPLIER as SUPPLY_CHAIN.RAW.SUPPLIER primary key (SUPPLIER_ID)
      with synonyms=('supplier','vendor') comment='sco:Supplier - the contracting party. Conformed dimension.'
  )
  RELATIONSHIPS (
    CONTRACT_TO_SUPPLIER as CONTRACT(SUPPLIER_ID) references SUPPLIER(SUPPLIER_ID)
  )
  FACTS (
    CONTRACT.COMMITMENT as contract.otd_commitment comment='Contracted minimum on-time share.',
    CONTRACT.GOVERNED as contract.governed_otd comment='Governed line-weighted supplier OTD.',
    CONTRACT.EXPOSURE as contract.penalty_exposure_usd comment='Claimable penalty, capped.',
    CONTRACT.MISSED as contract.penalty_missed_by_legacy_usd comment='Penalty hidden by the legacy definition.',
    CONTRACT.LATE_VALUE as contract.late_line_value comment='Value of late receipt lines.',
    CONTRACT.IS_BREACH as IFF(contract.breach_governed, 1, 0) comment='1 when governed OTD is below commitment.',
    CONTRACT.IS_CONFLICT as IFF(contract.definition_conflict, 1, 0) comment='1 when the contract measures OTD as a monthly average.'
  )
  DIMENSIONS (
    SUPPLIER.SUPPLIER_NAME as supplier.supplier_name with synonyms=('supplier','vendor') comment='Supplier name.',
    SUPPLIER.SUPPLIER_REGION as supplier.supplier_region with synonyms=('sourcing region','region') comment='Sourcing region.',
    SUPPLIER.SUPPLIER_TIER as supplier.supplier_tier with synonyms=('tier') comment='Supplier tier.',
    CONTRACT.CONTRACT_NUMBER as contract.contract_number comment='Agreement reference.',
    CONTRACT.OTD_BASIS as contract.otd_basis comment='How the contract measures on-time: PER_LINE (governed) or MONTHLY_AVERAGE (conflicts with the governed definition).',
    CONTRACT.COMPLIANCE_STATUS as contract.compliance_status with synonyms=('status')
      comment='COMPLIANT, BREACH, HIDDEN_BREACH (breached but shown compliant by the legacy definition) or NEEDS_REVIEW.',
    CONTRACT.INCOTERM as contract.incoterm comment='Delivery basis.',
    CONTRACT.PAYMENT_TERMS as contract.payment_terms comment='Payment terms.'
  )
  METRICS (
    CONTRACT.CONTRACT_BREACH_RATE as AVG(contract.is_breach)
      with synonyms=('breach rate','contract breach rate') comment='Share of suppliers whose governed OTD is below their contracted commitment.',
    CONTRACT.TOTAL_PENALTY_EXPOSURE as SUM(contract.exposure)
      with synonyms=('penalty exposure','service credits owed','claimable penalties') comment='Claimable contractual penalties, each capped at its annual limit.',
    CONTRACT.HIDDEN_PENALTY_EXPOSURE as SUM(contract.missed)
      with synonyms=('hidden penalties','unclaimed penalties') comment='Penalties on breaches the legacy average-of-averages definition reports as compliant.',
    CONTRACT.AVG_OTD_COMMITMENT as AVG(contract.commitment)
      with synonyms=('contracted on-time commitment') comment='Average contracted on-time commitment.',
    CONTRACT.DEFINITION_CONFLICT_COUNT as SUM(contract.is_conflict)
      with synonyms=('definition conflicts') comment='Contracts that measure OTD with the non-governed monthly-average definition.'
  )
  COMMENT = 'Supplier contract compliance. Unstructured agreements, extracted by AI_EXTRACT, joined to the governed supplier OTD.'
  AI_VERIFIED_QUERIES (
    PENALTY_EXPOSURE_BY_REGION AS (
      QUESTION 'How much contractual penalty exposure do we have by sourcing region?'
      VERIFIED_AT 1790553600 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_CONTRACT DIMENSIONS supplier.supplier_region METRICS contract.total_penalty_exposure, contract.contract_breach_rate) ORDER BY total_penalty_exposure DESC'
    ),
    HIDDEN_BREACHES AS (
      QUESTION 'Which suppliers breached their contract but look compliant on the legacy dashboard?'
      VERIFIED_AT 1790553600 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_CONTRACT DIMENSIONS supplier.supplier_name, contract.compliance_status METRICS contract.hidden_penalty_exposure) WHERE compliance_status = ''HIDDEN_BREACH'' ORDER BY hidden_penalty_exposure DESC'
    )
  );

-- ---------------------------------------------------------------------------
-- 8. Ingest: one new or amended agreement, end to end.
--
-- Input:      a supplier id and the agreement as free text.
-- Processing: file the document, AI_EXTRACT its terms (the same procedure the
--             bulk load uses), refresh the search index, re-score compliance
--             against the governed OTD.
-- Output:     what was extracted, and the compliance verdict before and after.
--
-- The OTD in the verdict is never touched here: it is read from
-- V_SUPPLIER_OTD_VERDICT like every other consumer, so an amendment can change
-- what a supplier promised but never what the governed metric says they did.
--
-- To restore the generated corpus after a demo: node scripts/rebuild.mjs --only 16
-- ---------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE GOVERNANCE.INGEST_SUPPLIER_CONTRACT(P_SUPPLIER_ID STRING, P_CONTRACT_TEXT STRING)
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Files one supplier agreement (free text), extracts its terms with AI_EXTRACT, refreshes contract search, and returns the extracted terms with the compliance verdict before and after.'
  EXECUTE AS OWNER
AS
$$
DECLARE
  known NUMBER;
  before_row VARIANT;
  after_row VARIANT;
BEGIN
  SELECT COUNT(*) INTO :known FROM RAW.SUPPLIER WHERE supplier_id = :P_SUPPLIER_ID;
  IF (known = 0) THEN
    RETURN OBJECT_CONSTRUCT('error', 'Unknown supplier ' || :P_SUPPLIER_ID || ' - contracts attach to a conformed SUPPLIER.');
  END IF;
  IF (P_CONTRACT_TEXT IS NULL OR LENGTH(TRIM(P_CONTRACT_TEXT)) < 40) THEN
    RETURN OBJECT_CONSTRUCT('error', 'Contract text is empty or too short to extract from.');
  END IF;

  SELECT OBJECT_CONSTRUCT('otd_commitment', otd_commitment, 'otd_basis', otd_basis,
                          'compliance_status', compliance_status, 'penalty_exposure_usd', penalty_exposure_usd)
    INTO :before_row
    FROM GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE WHERE supplier_id = :P_SUPPLIER_ID;

  MERGE INTO RAW.SUPPLIER_CONTRACT_DOC tgt
  USING (SELECT :P_SUPPLIER_ID AS supplier_id, :P_CONTRACT_TEXT AS contract_text) src
  ON tgt.supplier_id = src.supplier_id
  WHEN MATCHED THEN UPDATE SET
    contract_text = src.contract_text, source = 'INGESTED', loaded_at = CURRENT_TIMESTAMP(),
    file_name = 'AMEND-' || src.supplier_id || '-' || TO_VARCHAR(CURRENT_TIMESTAMP(), 'YYYYMMDDHH24MISS') || '.txt'
  WHEN NOT MATCHED THEN INSERT (doc_id, supplier_id, file_name, contract_text, source, loaded_at)
    VALUES ('DOC-' || src.supplier_id, src.supplier_id,
            'NEW-' || src.supplier_id || '-' || TO_VARCHAR(CURRENT_TIMESTAMP(), 'YYYYMMDDHH24MISS') || '.txt',
            src.contract_text, 'INGESTED', CURRENT_TIMESTAMP());

  CALL GOVERNANCE.EXTRACT_SUPPLIER_CONTRACTS(:P_SUPPLIER_ID);
  ALTER CORTEX SEARCH SERVICE SEMANTIC.SUPPLIER_CONTRACT_SEARCH REFRESH;

  SELECT OBJECT_CONSTRUCT(
           'supplier', c.supplier_name,
           'extracted', OBJECT_CONSTRUCT('otd_commitment', d.otd_commitment, 'otd_basis', d.otd_basis,
                                         'penalty_pct', d.penalty_pct, 'penalty_cap_usd', d.penalty_cap_usd,
                                         'lead_time_days', d.lead_time_days, 'payment_terms', d.payment_terms,
                                         'incoterm', d.incoterm, 'needs_review', d.needs_review),
           'governed_otd', c.governed_otd,
           'legacy_otd', c.legacy_otd,
           'compliance_status', c.compliance_status,
           'penalty_exposure_usd', c.penalty_exposure_usd,
           'penalty_hidden_by_legacy_usd', c.penalty_missed_by_legacy_usd,
           'definition_conflict', c.definition_conflict)
    INTO :after_row
    FROM GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE c
    JOIN CANONICAL.DIM_SUPPLIER_CONTRACT d USING (supplier_id)
   WHERE c.supplier_id = :P_SUPPLIER_ID;

  RETURN OBJECT_CONSTRUCT('before', before_row, 'after', after_row);
END;
$$;

-- ---------------------------------------------------------------------------
-- Access. Procurement owns contracts; the steward audits them. Planning and
-- logistics see the governed OTD elsewhere and have no need of commercial terms.
-- ---------------------------------------------------------------------------
GRANT USAGE ON PROCEDURE GOVERNANCE.INGEST_SUPPLIER_CONTRACT(STRING, STRING) TO ROLE SC_PROCUREMENT;
GRANT USAGE ON PROCEDURE GOVERNANCE.INGEST_SUPPLIER_CONTRACT(STRING, STRING) TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON TABLE CANONICAL.DIM_SUPPLIER_CONTRACT              TO ROLE SC_PROCUREMENT;
GRANT SELECT ON TABLE CANONICAL.DIM_SUPPLIER_CONTRACT              TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON VIEW  GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE    TO ROLE SC_PROCUREMENT;
GRANT SELECT ON VIEW  GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE    TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON VIEW  GOVERNANCE.V_CONTRACT_IMPACT                 TO ROLE SC_PROCUREMENT;
GRANT SELECT ON VIEW  GOVERNANCE.V_CONTRACT_IMPACT                 TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON VIEW  GOVERNANCE.V_CONTRACT_EXTRACTION_ACCURACY    TO ROLE SC_PROCUREMENT;
GRANT SELECT ON VIEW  GOVERNANCE.V_CONTRACT_EXTRACTION_ACCURACY    TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON SEMANTIC VIEW SEMANTIC.SC_CONTRACT                 TO ROLE SC_PROCUREMENT;
GRANT SELECT ON SEMANTIC VIEW SEMANTIC.SC_CONTRACT                 TO ROLE SC_ONTOLOGY_STEWARD;
GRANT USAGE  ON CORTEX SEARCH SERVICE SEMANTIC.SUPPLIER_CONTRACT_SEARCH TO ROLE SC_PROCUREMENT;
GRANT USAGE  ON CORTEX SEARCH SERVICE SEMANTIC.SUPPLIER_CONTRACT_SEARCH TO ROLE SC_ONTOLOGY_STEWARD;

-- PERSONA_VIEW_ACCESS mirrors the two SC_CONTRACT grants above (90_verify_base.sql
-- counts them). Delete-then-insert so a re-run of this file cannot duplicate rows:
-- the table's primary key is declared, not enforced.
DELETE FROM GOVERNANCE.PERSONA_VIEW_ACCESS WHERE semantic_view = 'SC_CONTRACT';
INSERT INTO GOVERNANCE.PERSONA_VIEW_ACCESS (role_name, semantic_view)
SELECT * FROM VALUES ('SC_ONTOLOGY_STEWARD','SC_CONTRACT'), ('SC_PROCUREMENT','SC_CONTRACT');

-- Evidence.
SELECT * FROM GOVERNANCE.V_CONTRACT_IMPACT;


-- ============================================================================
-- FILE: 10_agent.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 10 — The Cortex Agent.
--
-- lib/constants.ts expects SNOWFLAKE_INTELLIGENCE.AGENTS.SC_ONTOLOGIST_AGENT, so
-- that is where it is created. Previously this object existed only in a previous
-- account, built by hand, and vanished with it; the /ask page referenced a name
-- that resolved to nothing.
--
-- ---------------------------------------------------------------------------
-- WHAT THIS AGENT IS FOR, AND WHAT IT IS NOT
--
-- It is the exploratory surface: free-form questions, Cortex Analyst writing SQL
-- against the semantic views, charts via the built-in data_to_chart tool.
--
-- The application's /ask route deliberately does NOT call it. Two reasons, both
-- structural rather than stylistic:
--
--   1. AGENTS RESOLVE PERMISSIONS FROM THE USER'S DEFAULT ROLE, NOT THE SESSION
--      ROLE. The persona guarantee in this project is USE ROLE + USE SECONDARY
--      ROLES NONE per request, so a row-scoped persona such as SC_LOGISTICS_EU
--      would silently receive all-region numbers through an agent call. That is
--      the precise class of defect the whole project exists to prevent, so the
--      persona-scoped path stays on lib/persona.ts.
--   2. An agent run (orchestration -> Analyst -> chart) routinely exceeds the 10
--      second Vercel Hobby function limit documented in lib/env.ts, which is the
--      same limit that already hides the drift-test button there.
--
-- So the agent is reachable from Snowsight, from DATA_AGENT_RUN, and from the app
-- only where the host has no such limit. It is governed by the semantic views and
-- their verified queries rather than by the registry-assembled SQL path.
--
-- ---------------------------------------------------------------------------
-- WHY VERIFIED QUERIES MATTER MORE THAN THE PROMPT
--
-- Analyst re-derives SQL for every question unless a verified query pins it. The
-- 38 verified queries declared in 00e_semantic.sql are therefore the single
-- highest-leverage part of this agent's accuracy, and several are written as
-- teaching examples: every inventory query is per snapshot, which shows Analyst
-- the non-additive pattern instead of describing it in prose and hoping.
--
-- The instructions below add only what a verified query cannot express: the
-- inbound/outbound distinction, the accrued/invoiced distinction, and the three
-- rules that keep a prediction from being reported as a measurement.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- SOURCE OF TRUTH. This spec is the agent as it is live on PJRTYEL-AZ37563 (the working copy,
-- which includes VERSION$5), captured here so a rebuild or scripts/migrate.mjs reproduces it.
-- Since the first build the live agent gained a RESPONSE FORMAT rule, a MULTI-TOOL COORDINATION
-- rule, a rule that penalty and breach numbers come from Contract_Analyst, broader routing text,
-- and a 120 s / 48,000 token budget (was 60 s / 24,000). If the agent is edited in Snowsight
-- again, copy the new spec back into this file before the next rebuild, or it is overwritten.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;

CREATE DATABASE IF NOT EXISTS SNOWFLAKE_INTELLIGENCE
  COMMENT = 'Home for Snowflake Intelligence agents. Kept separate from SUPPLY_CHAIN so that dropping and rebuilding the data does not drop the agent with it.';

CREATE SCHEMA IF NOT EXISTS SNOWFLAKE_INTELLIGENCE.AGENTS
  COMMENT = 'Cortex Agents. Referenced by lib/constants.ts AGENT_FQN.';

USE DATABASE SNOWFLAKE_INTELLIGENCE;
USE SCHEMA AGENTS;

-- NO COPY GRANTS, DELIBERATELY. The documented syntax places COPY GRANTS before
-- COMMENT, and this account's parser rejects that combination outright:
--   "syntax error line 2 at position 2 unexpected 'comment'"
-- Because MULTI_STATEMENT parsing happens before execution, that single syntax
-- error also stopped the CREATE DATABASE and CREATE SCHEMA above from running --
-- a whole-file failure from one clause. It is redundant here regardless: every
-- grant is re-issued explicitly at the bottom of this file, which is easier to
-- audit than a flag that silently preserves whatever was granted before.
CREATE OR REPLACE AGENT SC_ONTOLOGIST_AGENT
  COMMENT = 'Governed supply chain analytics agent. Answers only from the SUPPLY_CHAIN semantic views, distinguishes inbound from outbound service, refuses to invent a metric, and never reports a prediction as a measurement.'
  PROFILE = '{"display_name": "Supply Chain Ontologist", "color": "blue"}'
  FROM SPECIFICATION
  $$
models:
  orchestration: auto

orchestration:
  tool_not_accessible: accept
  budget:
    seconds: 120
    tokens: 48000

instructions:
  response: |
    You answer questions about a governed supply chain ontology. Every number you
    report must come from a tool. Never compute, estimate or infer a figure yourself.

    METRIC BOUNDARIES. If no available metric answers the question, say so plainly
    and name the closest governed metrics instead. Do not derive a metric that does
    not exist: there is no revenue, margin, customer satisfaction or emissions
    metric in this ontology, and cost data cannot be turned into any of them.

    INBOUND IS NOT OUTBOUND. Supplier On-Time Delivery measures whether suppliers
    met the dates they promised us. On-Time Delivery measures whether we met the
    dates we promised customers. They are different metrics over different facts
    and must never be merged, averaged together or reconciled as one number. If a
    question says only "on-time delivery" with no side named, ask which one before
    answering.

    ACCRUED IS NOT INVOICED. Freight Cost is what we accrued. Freight Invoiced is
    what carriers billed. Freight Bill Variance is invoiced less accrued, and a
    positive value means the carrier billed more than we accrued.

    INVENTORY IS A BALANCE, NOT A FLOW. Days of Inventory and Inventory Value are
    observed at a month-end snapshot. Never sum or average them across snapshot
    dates: twelve month-end balances summed counts the same physical stock twelve
    times and produces a plausible number that is wrong by a factor of twelve.
    Report the latest snapshot in the requested period and say which date it is.

    REALIZED PERFORMANCE EXCLUDES THE FUTURE. The data contains promised receipts
    and planned deliveries dated after today. Those are commitments, not
    performance. Exclude them from any service metric and say that you did.

    ABSOLUTE DOLLAR METRICS HAVE NO TARGET, BY DESIGN. Freight cost, freight
    invoiced, freight bill variance, total landed cost, inventory value and
    purchase price variance all scale with volume and with the length of the
    period, so do not compare them to a threshold or call them good or bad on
    level alone.

    PREDICTIONS ARE NOT MEASUREMENTS. Three rules, without exception:
      1. Never produce a forecast yourself. Predictions come only from the
         Metric_Outlook tool. If it has no row for what was asked, say the
         prediction does not exist.
      2. Always label a prediction as a prediction, and always quote the
         backtested accuracy of the method that produced it alongside the number.
      3. Never present a high accuracy score as evidence that a prediction is
         useful. These service metrics are close to stationary, so predicting the
         historical mean scores about 99.7% while demonstrating nothing. Where a
         method does not beat its own trailing-mean benchmark, say so.

    CONTRACT TEXT IS EVIDENCE, NOT A METRIC. Contract_Search returns clause text.
    Use it to quote what an agreement says; take every number about breaches or
    penalties from Contract_Analyst, never by reading figures out of a clause.

    Prefer a chart when the answer has a dimensional breakdown. Do not put metrics
    with different units on one axis: a percentage and a dollar total on the same
    scale is a misleading chart.

    RESPONSE FORMAT. Lead with the headline number and its period in the first
    sentence. Keep the full answer under 200 words. When showing tabular data,
    use a short markdown table with at most 10 rows rather than embedding raw
    JSON. Only call data_to_chart when the user explicitly asks for a chart or
    the breakdown has more than 5 rows.

    Be concise. State the number, its period, and where it came from.

  orchestration: |
    Route by domain, and prefer the narrowest view that can answer the question:
      - supplier delivery, supplier fill, purchase price variance -> Supplier_Analyst
      - customer delivery, customer OTD, OTIF, fill rate, perfect order,
        OTD by product family, OTD by region, defect reasons -> Fulfillment_Analyst
      - inventory cover, stock value, stockouts -> Inventory_Analyst
      - freight, landed cost, carrier billing -> Landed_Cost_Analyst
      - demand forecast versus actual -> Demand_Analyst
      - production output, scrap, schedule adherence -> Manufacturing_Analyst
      - anything spanning two or more of the above on a shared dimension such as
        product family -> Ontology_360_Analyst
      - anything about next month, target risk, breach probability or projected
        volume -> Metric_Outlook
      - contract commitments, contract breaches, penalty or service-credit
        exposure, definition conflicts -> Contract_Analyst
      - what an agreement actually SAYS (clause wording, remedies, terms) ->
        Contract_Search, and quote the clause

    NARROWEST VIEW RULE. If a question mentions only one domain (e.g. customer delivery
    by product family), ALWAYS use the single-domain view (Fulfillment_Analyst), NEVER
    Ontology_360_Analyst. The 360 view is reserved strictly for questions that
    compare two or more domains on a shared dimension.

    ONE QUERY PER ANSWER. Make one focused tool call per question. Do not run a
    second exploratory query unless the first returned no data. When showing
    breakdowns by defect reason, carrier, or region, use the OTD/OTIF percentage
    metric (not raw line counts) unless the user specifically asks for counts.

    Use Ontology_360_Analyst when the question compares domains, because only that
    view carries the conformed dimensions that make the comparison valid.

    Call data_to_chart after a tool returns a dimensional breakdown.

    If a tool is not accessible to the caller, say that access is the reason and
    name the metric. Do not silently substitute a different metric or view.

    MULTI-TOOL COORDINATION. When a question needs both clause text AND a metric
    (e.g. 'what does the contract say about X and how does their actual Y compare'),
    plan both tool calls before executing. Call the text tool (Contract_Search)
    first to identify the entity, then call the metric tool (Supplier_Analyst,
    Contract_Analyst, etc.) for the number. Do not stop after the first tool.

    PENALTY AND BREACH NUMBERS ALWAYS COME FROM Contract_Analyst, NEVER FROM
    Contract_Search. If someone asks 'how much penalty exposure' or 'what is the
    breach rate', that is a metric question for Contract_Analyst even if the word
    'contract' appears.

  sample_questions:
    - question: "How does supplier on-time delivery compare with the on-time delivery we give customers?"
    - question: "Which product families are we delivering late?"
    - question: "How many days of inventory are we holding?"
    - question: "Are carriers billing us more than we accrued for freight?"
    - question: "Which product families will miss their on-time delivery target next month?"
    - question: "What order-line volume should we plan for over the next few months?"
    - question: "Which sourcing regions are late most often?"
    - question: "Which suppliers breached their contract but look compliant on the legacy dashboard?"
    - question: "What does our agreement with our worst-performing supplier say about late deliveries?"

tools:
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Ontology_360_Analyst"
      description: "Cross-domain supply chain ontology: 5 conformed dimensions and 6 facts spanning inbound receipts, outbound deliveries, inventory, landed cost, manufacturing and demand. USE THIS when a question spans two or more domains on a shared dimension such as product family, supplier region or carrier. Do NOT use it when a single-domain view can answer the question, because the narrower view resolves more reliably."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Supplier_Analyst"
      description: "Inbound supplier performance at purchase-order receipt-line grain: supplier on-time delivery, supplier fill rate, purchase price variance. Dimensions include supplier name, sourcing region, supplier tier and product family. USE THIS for anything about whether SUPPLIERS met dates or quantities promised to us. Do NOT use it for deliveries to customers."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Fulfillment_Analyst"
      description: "Outbound customer fulfilment at order-line grain: on-time delivery, on time in full, fill rate, perfect order rate. Dimensions include product family, destination region, carrier and recorded defect reason. USE THIS for anything about whether WE met dates or quantities promised to customers. Do NOT use it for supplier performance."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Inventory_Analyst"
      description: "Month-end inventory positions by material and location: days of inventory, inventory value, stockout rate. Dimensions include snapshot date, product family, ABC class, node name and region. SNAPSHOT GRAIN: every query must be scoped to a single snapshot date, never aggregated across dates. USE THIS for stock on hand, cover and value."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Landed_Cost_Analyst"
      description: "Landed cost and freight billing at shipment grain: landed cost per unit, total landed cost, accrued freight, invoiced freight, freight bill variance. Dimensions include carrier, service level, destination region and product family. USE THIS for cost to serve and carrier billing disputes. Accrued and invoiced freight are different metrics."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Demand_Analyst"
      description: "Monthly demand forecast versus actual by material: forecast units, actual units, forecast accuracy. USE THIS for demand plan quality. Include only closed periods, because an open period carries a zero actual and would read as total inaccuracy."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Manufacturing_Analyst"
      description: "Production completions by plant: units completed, scrap rate, schedule adherence. Dimensions include plant name, region and product family. USE THIS for manufacturing output and quality."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Metric_Outlook"
      description: "Governed predictions already produced and scored: predicted value, governed target, breach probability, banded verdict, and the backtested accuracy of the producing method. USE THIS for any question about next month, target reachability, breach risk or projected volume. It reports only predictions that already exist and CANNOT extrapolate a new one. Always quote the method accuracy alongside the prediction."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Contract_Analyst"
      description: "Supplier contract compliance: one agreement per supplier with terms extracted from the contract text by AI_EXTRACT (on-time commitment, how it is measured, penalty rate and cap), joined to the governed supplier OTD. Metrics: contract breach rate, total penalty exposure, hidden penalty exposure (breaches the legacy definition reports as compliant), definition conflicts. USE THIS for contract breaches and penalty money."
  - tool_spec:
      type: "cortex_search"
      name: "Contract_Search"
      description: "Full text of supplier supply agreements. USE THIS to quote what a contract says - service-level clauses, remedies, payment and delivery terms. It returns text, not metrics."
  - tool_spec:
      type: "data_to_chart"
      name: "data_to_chart"
      description: "Renders a chart from data another tool returned. Use it whenever an answer has a dimensional breakdown. Never place metrics with different units on a shared axis."

tool_resources:
  Ontology_360_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Supplier_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Fulfillment_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Inventory_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Landed_Cost_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Demand_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_DEMAND"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Manufacturing_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_MANUFACTURING"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Metric_Outlook:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Contract_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_CONTRACT"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Contract_Search:
    search_service: "SUPPLY_CHAIN.SEMANTIC.SUPPLIER_CONTRACT_SEARCH"
    id_column: "DOC_ID"
    title_column: "FILE_NAME"
    max_results: 5
  $$;

-- ---------------------------------------------------------------------------
-- Access.
--
-- SC_SUPPLIER_LEGACY_DEFECT is deliberately NOT a tool. It is the negative
-- control: a knowingly wrong supplier OTD kept deployed so the drift test can be
-- shown to fail. Exposing it to a conversational surface would let a governed-
-- looking answer carry the defective number.
-- ---------------------------------------------------------------------------

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_ONTOLOGY_STEWARD;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_ONTOLOGY_STEWARD;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_ONTOLOGY_STEWARD;

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_PROCUREMENT;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_PROCUREMENT;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_PROCUREMENT;

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_LOGISTICS;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_LOGISTICS;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_LOGISTICS;

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_LOGISTICS_EU;

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_PLANNER;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_PLANNER;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_PLANNER;

-- Evidence.
SHOW AGENTS IN SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS;


-- ============================================================================
-- FILE: 10b_geospatial_reference.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 10b — Geospatial reference ingestion.
--
-- Geocodes the existing network nodes and materialises the current 96 lanes as
-- map-ready geometries. This is reference data only: future scenarios attach
-- impacts to lanes or chokepoints without changing realized facts or metrics.
-- Coordinates are representative city centres for synthetic node names, not
-- facility addresses, vehicle tracking, or navigation directions.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA RAW;

CREATE OR REPLACE TABLE GEO_NODE (
  node_id       STRING NOT NULL,
  latitude      NUMBER(9,6) NOT NULL,
  longitude     NUMBER(9,6) NOT NULL,
  point         GEOGRAPHY NOT NULL,
  precision     STRING NOT NULL,
  source        STRING NOT NULL,
  CONSTRAINT pk_geo_node PRIMARY KEY (node_id)
) COMMENT = 'Map reference for the 24 synthetic network nodes. Coordinates are representative city centres, not facility addresses.';

INSERT INTO GEO_NODE (node_id, latitude, longitude, point, precision, source)
SELECT node_id, latitude, longitude,
       TO_GEOGRAPHY('POINT(' || longitude || ' ' || latitude || ')'),
       'CITY_CENTRE',
       'Synthetic reference data curated for network visualisation'
FROM VALUES
  ('ND-01',44.953703,-93.089958), ('ND-02',34.000710,-81.034814),
  ('ND-03',30.267153,-97.743061), ('ND-04',44.159134,-94.013857),
  ('ND-05',41.878114,-87.629798), ('ND-06',43.255721,-79.871102),
  ('ND-07',51.204196,6.687952),   ('ND-08',51.367077,7.463284),
  ('ND-09',51.669313,-4.041363),  ('ND-10',51.571915,4.768323),
  ('ND-11',45.464204,9.189982),   ('ND-12',45.764043,4.835659),
  ('ND-13',1.352083,103.819836),  ('ND-14',31.298886,120.585316),
  ('ND-15',38.255440,140.339602), ('ND-16',-33.868820,151.209296),
  ('ND-17',18.520430,73.856744),  ('ND-18',37.566535,126.977969),
  ('ND-19',-23.501533,-47.452594),('ND-20',-23.588642,-48.048263),
  ('ND-21',20.588793,-100.389888),('ND-22',4.711000,-74.072092),
  ('ND-23',-33.448890,-70.669265),('ND-24',-34.603722,-58.381592)
AS v(node_id, latitude, longitude);

CREATE OR REPLACE TABLE GEO_REGION_HUB (
  region        STRING NOT NULL,
  hub_name      STRING NOT NULL,
  latitude      NUMBER(9,6) NOT NULL,
  longitude     NUMBER(9,6) NOT NULL,
  point         GEOGRAPHY NOT NULL,
  source        STRING NOT NULL,
  CONSTRAINT pk_geo_region_hub PRIMARY KEY (region)
) COMMENT = 'Representative destination hubs used to draw lanes whose source model records destination region rather than destination node.';

INSERT INTO GEO_REGION_HUB (region, hub_name, latitude, longitude, point, source)
SELECT region, hub_name, latitude, longitude,
       TO_GEOGRAPHY('POINT(' || longitude || ' ' || latitude || ')'),
       'Synthetic reference data curated for network visualisation'
FROM VALUES
  ('NA','Chicago regional hub',41.878114,-87.629798),
  ('EU','Rotterdam regional hub',51.924420,4.477733),
  ('APAC','Singapore regional hub',1.352083,103.819836),
  ('LATAM','Sao Paulo regional hub',-23.550520,-46.633308)
AS v(region, hub_name, latitude, longitude);

CREATE OR REPLACE TABLE GEO_CHOKEPOINT (
  chokepoint_id   STRING NOT NULL,
  chokepoint_name STRING NOT NULL,
  latitude        NUMBER(9,6) NOT NULL,
  longitude       NUMBER(9,6) NOT NULL,
  point           GEOGRAPHY NOT NULL,
  transport_mode  STRING NOT NULL,
  description     STRING NOT NULL,
  source          STRING NOT NULL,
  CONSTRAINT pk_geo_chokepoint PRIMARY KEY (chokepoint_id)
) COMMENT = 'Strategic logistics chokepoints for future scenario modelling. Presence is geographic reference only and does not assert a live disruption.';

INSERT INTO GEO_CHOKEPOINT
  (chokepoint_id, chokepoint_name, latitude, longitude, point, transport_mode, description, source)
SELECT chokepoint_id, chokepoint_name, latitude, longitude,
       TO_GEOGRAPHY('POINT(' || longitude || ' ' || latitude || ')'),
       transport_mode, description,
       'Public geographic reference; scenario status is maintained separately'
FROM VALUES
  ('CHOKE-01','Strait of Hormuz',26.566700,56.250000,'OCEAN','Narrow Gulf maritime passage.'),
  ('CHOKE-02','Suez Canal',30.585200,32.265400,'OCEAN','Mediterranean to Red Sea maritime passage.'),
  ('CHOKE-03','Bab el-Mandeb',12.583300,43.333300,'OCEAN','Red Sea to Gulf of Aden maritime passage.'),
  ('CHOKE-04','Panama Canal',9.080000,-79.680000,'OCEAN','Atlantic to Pacific canal passage.'),
  ('CHOKE-05','Strait of Malacca',2.500000,101.000000,'OCEAN','Indian Ocean to South China Sea passage.')
AS v(chokepoint_id, chokepoint_name, latitude, longitude, transport_mode, description);

CREATE OR REPLACE TABLE GEO_LANE (
  lane_id             STRING NOT NULL,
  origin_node         STRING NOT NULL,
  destination_region  STRING NOT NULL,
  service_level       STRING NOT NULL,
  transit_target_days NUMBER NOT NULL,
  origin_point        GEOGRAPHY NOT NULL,
  destination_point   GEOGRAPHY NOT NULL,
  route_geometry      GEOGRAPHY NOT NULL,
  geometry_method     STRING NOT NULL,
  CONSTRAINT pk_geo_lane PRIMARY KEY (lane_id)
) COMMENT = 'Map-ready lane reference. Geometry is a representative straight connection to the destination region hub because RAW.LANE does not hold a destination node or carrier-specific path.';

INSERT INTO GEO_LANE
  (lane_id, origin_node, destination_region, service_level, transit_target_days,
   origin_point, destination_point, route_geometry, geometry_method)
SELECT
  l.lane_id, l.origin_node, l.dest_region, l.service_level, l.transit_target_days,
  n.point, h.point,
  TO_GEOGRAPHY('LINESTRING(' || n.longitude || ' ' || n.latitude || ', ' || h.longitude || ' ' || h.latitude || ')'),
  'STRAIGHT_LINE_TO_REGION_HUB'
FROM LANE l
JOIN GEO_NODE n ON n.node_id = l.origin_node
JOIN GEO_REGION_HUB h ON h.region = l.dest_region;

SELECT 'GEO_NODE coverage' AS check_name, COUNT(*) AS found, 24 AS expected,
       IFF(COUNT(*) = 24, 'PASS', 'FAIL') AS verdict FROM GEO_NODE
UNION ALL
SELECT 'GEO_LANE coverage', COUNT(*), 96, IFF(COUNT(*) = 96, 'PASS', 'FAIL') FROM GEO_LANE
UNION ALL
SELECT 'GEO_CHOKEPOINT coverage', COUNT(*), 5, IFF(COUNT(*) = 5, 'PASS', 'FAIL') FROM GEO_CHOKEPOINT;


-- ============================================================================
-- FILE: 10c_network_risk_scenarios.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 10c — Simulated network-risk scenarios and lane impacts.
--
-- Scenario rows are planning assumptions, never observed events. They do not
-- update RAW.SALES_ORDER_LINE, SHIPMENT_COST, CANONICAL facts, or any realized
-- metric. A map or future SC_NETWORK_RISK semantic view must label their output
-- SIMULATED and quote the scenario's assumptions.
--
-- The synthetic network records destination REGION rather than a real route
-- corridor. The Hormuz scenario therefore affects APAC -> EU lanes by explicit
-- modelling assumption; it does not assert that any historical shipment crossed
-- the Strait of Hormuz or that a live disruption exists.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE OR REPLACE TABLE NETWORK_RISK_SCENARIO (
  scenario_id        STRING NOT NULL,
  scenario_name      STRING NOT NULL,
  scenario_type      STRING NOT NULL,
  status             STRING NOT NULL,
  chokepoint_id      STRING,
  effective_from     DATE NOT NULL,
  effective_to       DATE,
  confidence         STRING NOT NULL,
  source_type        STRING NOT NULL,
  assumption_summary STRING NOT NULL,
  created_at         TIMESTAMP_LTZ NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  CONSTRAINT pk_network_risk_scenario PRIMARY KEY (scenario_id)
) COMMENT = 'Scenario header for simulated network-risk planning. It is separate from realized facts and must never be represented as a live incident feed.';

INSERT INTO NETWORK_RISK_SCENARIO
  (scenario_id, scenario_name, scenario_type, status, chokepoint_id,
   effective_from, effective_to, confidence, source_type, assumption_summary)
VALUES
  (
    'SCN-HORMUZ-001',
    'Hormuz capacity constraint - planning scenario',
    'MARITIME_CHOKEPOINT',
    'SIMULATED',
    'CHOKE-01',
    DATE '2026-10-01',
    DATE '2026-10-31',
    'PLANNING_ASSUMPTION',
    'SYNTHETIC',
    'Models a hypothetical capacity constraint for APAC-to-EU ocean-exposed planning lanes. It is not live geopolitical or vessel-tracking data.'
  );

CREATE OR REPLACE TABLE SCENARIO_LANE_IMPACT (
  scenario_id             STRING NOT NULL,
  lane_id                 STRING NOT NULL,
  impact_status           STRING NOT NULL,
  applicability_reason    STRING NOT NULL,
  capacity_reduction_pct  NUMBER(5,4) NOT NULL,
  transit_delay_days      NUMBER(6,2) NOT NULL,
  freight_uplift_pct      NUMBER(5,4) NOT NULL,
  disruption_probability  NUMBER(5,4) NOT NULL,
  mitigation_strategy     STRING NOT NULL,
  mitigation_delay_days   NUMBER(6,2) NOT NULL,
  mitigation_cost_uplift_pct NUMBER(5,4) NOT NULL,
  notes                   STRING NOT NULL,
  CONSTRAINT pk_scenario_lane_impact PRIMARY KEY (scenario_id, lane_id)
) COMMENT = 'Simulated scenario impact at lane grain. Each row carries transparent capacity, transit, freight, probability and mitigation assumptions; none is a realized shipment measurement.';

-- Apply the planning scenario only to APAC -> EU lanes. The source lane model
-- has no maritime corridor field, so this is deliberately an auditable proxy.
INSERT INTO SCENARIO_LANE_IMPACT
  (scenario_id, lane_id, impact_status, applicability_reason,
   capacity_reduction_pct, transit_delay_days, freight_uplift_pct,
   disruption_probability, mitigation_strategy, mitigation_delay_days,
   mitigation_cost_uplift_pct, notes)
SELECT
  'SCN-HORMUZ-001',
  l.lane_id,
  'SIMULATED',
  'Synthetic APAC-to-EU proxy for Hormuz-exposed planning traffic',
  0.40,
  IFF(l.service_level = 'EXPRESS', 4.0, IFF(l.service_level = 'STANDARD', 7.0, 10.0)),
  0.25,
  0.70,
  'REROUTE_OR_EXPEDITE',
  IFF(l.service_level = 'EXPRESS', 2.0, 4.0),
  0.45,
  'Assumption only: compare baseline service with a reroute or expedited mitigation. Validate carrier capacity before execution.'
FROM SUPPLY_CHAIN.RAW.LANE l
JOIN SUPPLY_CHAIN.RAW.NODE n ON n.node_id = l.origin_node
WHERE n.node_region = 'APAC'
  AND l.dest_region = 'EU';

CREATE OR REPLACE VIEW V_NETWORK_RISK_SCENARIO AS
SELECT
  s.scenario_id,
  s.scenario_name,
  s.scenario_type,
  s.status AS scenario_status,
  s.effective_from,
  s.effective_to,
  s.confidence,
  s.source_type,
  s.assumption_summary,
  c.chokepoint_name,
  i.lane_id,
  l.origin_node,
  n.node_name AS origin_name,
  n.node_region AS origin_region,
  l.dest_region AS destination_region,
  l.service_level,
  l.transit_target_days AS baseline_transit_days,
  i.impact_status,
  i.applicability_reason,
  i.capacity_reduction_pct,
  i.transit_delay_days,
  i.freight_uplift_pct,
  i.disruption_probability,
  i.mitigation_strategy,
  i.mitigation_delay_days,
  i.mitigation_cost_uplift_pct,
  l.transit_target_days + i.transit_delay_days AS simulated_transit_days,
  l.transit_target_days + i.mitigation_delay_days AS mitigated_transit_days,
  i.notes
FROM NETWORK_RISK_SCENARIO s
JOIN SCENARIO_LANE_IMPACT i ON i.scenario_id = s.scenario_id
JOIN SUPPLY_CHAIN.RAW.LANE l ON l.lane_id = i.lane_id
JOIN SUPPLY_CHAIN.RAW.NODE n ON n.node_id = l.origin_node
LEFT JOIN SUPPLY_CHAIN.RAW.GEO_CHOKEPOINT c ON c.chokepoint_id = s.chokepoint_id;

-- Evidence. The affected lane count comes from the generated lane population,
-- so assert non-zero coverage rather than a brittle hand-maintained count.
SELECT
  'simulated scenario header' AS check_name,
  COUNT(*) AS found,
  1 AS expected_minimum,
  IFF(COUNT(*) >= 1, 'PASS', 'FAIL') AS verdict
FROM NETWORK_RISK_SCENARIO
WHERE scenario_id = 'SCN-HORMUZ-001'
UNION ALL
SELECT
  'simulated APAC-to-EU lane impacts',
  COUNT(*),
  1,
  IFF(COUNT(*) >= 1, 'PASS', 'FAIL')
FROM SCENARIO_LANE_IMPACT
WHERE scenario_id = 'SCN-HORMUZ-001'
UNION ALL
SELECT
  'non-realized scenario status',
  COUNT(*),
  1,
  IFF(COUNT(*) = 1, 'PASS', 'FAIL')
FROM NETWORK_RISK_SCENARIO
WHERE scenario_id = 'SCN-HORMUZ-001' AND status = 'SIMULATED';


-- ============================================================================
-- FILE: 11_iot_telemetry.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Phase 5 — IoT shipment telemetry: closes the "IoT" line in the brief
-- ("ERP, logistics, supplier, and IoT systems"), which had no entity until now.
--
-- Design, and why each choice was made:
--
--   * GRAIN. One summary reading per physical shipment, same grain and same
--     SHIPMENT_ID as CANONICAL.FCT_LANDED_COST_SHIPMENT. A real cold-chain sensor
--     stream emits many events per shipment; this table is deliberately the
--     summary an application would consume (peak temperature, exceeded or not),
--     not the raw event stream, to avoid a one-to-many fan-out that every metric
--     and join below would otherwise have to account for.
--
--   * JOIN PATH. SHIPMENT_TELEMETRY reaches ORDER_FULFILLMENT via (ORDER_ID,
--     ORDER_LINE) — the exact shape of the existing COST_TO_FULFILLMENT edge.
--     Reusing a join key that already works safely, rather than adding a new
--     direct edge to PART or CALENDAR, is deliberate: LANDED_COST reaches those
--     only through ORDER_FULFILLMENT for exactly the multi-path reason
--     documented in 00e_semantic.sql, and the same hazard applies here.
--
--   * TWO BINDINGS, ON PURPOSE. A metric bound to only one semantic view has
--     nothing to disagree with and is reported UNTESTED, not PASS (see
--     METRIC_DRIFT_TEST in 00f). SC_TELEMETRY is a brand-new object (a plain
--     CREATE, not a splice of a live one), so it carries no splice risk; adding
--     it is what lets temp_excursion_rate genuinely earn a PASS instead of
--     merely being registered.
--
--   * THE SC_ONTOLOGY_360 SPLICE uses the exact GET_DDL + REPLACE technique
--     documented in 01_calendar_dimension.sql: short "X as Y" structural
--     anchors with no trailing comment/synonym text, each the START of the
--     INVENTORY.* entry that immediately follows LANDED_COST's own, so new
--     content is prepended before it rather than spliced into the middle of
--     LANDED_COST's own multi-clause definition.
--
--   * ROW ACCESS. FCT_SHIPMENT_TELEMETRY carries SHIP_REGION and gets the same
--     RAP_SHIP_REGION policy already applied to FCT_LANDED_COST_SHIPMENT, so an
--     EU-scoped persona cannot see non-EU telemetry through the back door.
--
--   * RATES ARE DELIBERATE, NOT ORGANIC. Excursion is generated directly as a
--     ~4.8% Bernoulli draw (mirroring the ~2.8% future-dated rate in 00c), and
--     PEAK_TEMP_C is then generated conditioned on that draw so the flag and the
--     reading can never disagree — a two-branch generator, not an independent
--     coin flip per column. The target below (3%) is deliberately set below the
--     ~4.8% actual rate so the metric renders a genuine amber/red state instead
--     of a trivially green one, consistent with how the OTD target in this
--     project is deliberately unreachable rather than decorative.
--
-- VERIFICATION NOT YET RUN AGAINST SNOWFLAKE. This file was authored against the
-- established patterns in 00b-00f and 01, but has not been executed here — no
-- live Snowflake connection was available in the authoring environment. Run
-- `node scripts/rebuild.mjs --dry-run` to confirm ordering, then
-- `node scripts/rebuild.mjs --from 10c_network_risk_scenarios.sql` (or a full
-- rebuild) and `sql/90_verify_base.sql` / `sql/93_verify_verified_queries.sql`
-- before treating this as live.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE WAREHOUSE COMPUTE_WH;

-- ---------------------------------------------------------------------------
-- 1. RAW source.
-- ---------------------------------------------------------------------------

USE SCHEMA RAW;

CREATE OR REPLACE TABLE SHIPMENT_TELEMETRY (
  SHIPMENT_ID       STRING      NOT NULL COMMENT 'Shipment number. One IoT summary reading per physical shipment, same grain as SHIPMENT_COST.',
  PEAK_TEMP_C       NUMBER(5,1) NOT NULL COMMENT 'Peak in-transit temperature reading, degrees Celsius. Generated consistently with IS_TEMP_EXCURSION: never disagrees with it.',
  IS_TEMP_EXCURSION BOOLEAN     NOT NULL COMMENT 'TRUE when PEAK_TEMP_C breached the 10C cold-chain threshold. ~4.8% of shipments, by construction.',
  IS_TRANSIT_DELAY  BOOLEAN     NOT NULL COMMENT 'TRUE when the sensor-reported transit time exceeded the lane commitment. ~12% of shipments, by construction.',
  EVENT_DATE        DATE        NOT NULL COMMENT 'Date the summary reading was recorded. Delivery date, so the reading exists once the shipment has actually arrived.',
  CONSTRAINT pk_shipment_telemetry PRIMARY KEY (SHIPMENT_ID)
) COMMENT = 'In-transit IoT sensor summary per shipment: temperature and transit-time exceptions. Source for CANONICAL.FCT_SHIPMENT_TELEMETRY.';

INSERT INTO SHIPMENT_TELEMETRY
WITH t AS (
  SELECT
    sc.shipment_id,
    sc.delivery_date,
    ABS(HASH(sc.shipment_id, 'exc')) % 1000 < 48 AS is_temp_excursion,
    ABS(HASH(sc.shipment_id, 'delay')) % 100 < 12 AS is_transit_delay
  FROM SHIPMENT_COST sc
)
SELECT
  shipment_id,
  -- Breach branch: 10.5..14.49C. Safe branch: 2.0..8.99C. The two ranges never
  -- overlap, so the boolean and the reading are consistent by construction.
  IFF(is_temp_excursion,
      ROUND(10.5 + (ABS(HASH(shipment_id, 'over')) % 400) / 100.0, 1),
      ROUND(2.0  + (ABS(HASH(shipment_id, 'temp')) % 700) / 100.0, 1))   AS peak_temp_c,
  is_temp_excursion,
  is_transit_delay,
  delivery_date AS event_date
FROM t;

-- ---------------------------------------------------------------------------
-- 2. CANONICAL fact. Joins RAW.SHIPMENT_COST and RAW.CARRIER exactly as
--    FCT_LANDED_COST_SHIPMENT does, so SHIP_REGION, LANE_ID and CARRIER agree
--    with the shipment's own landed-cost row rather than being re-derived.
-- ---------------------------------------------------------------------------

USE SCHEMA CANONICAL;

CREATE OR REPLACE TABLE FCT_SHIPMENT_TELEMETRY (
  SHIPMENT_ID       STRING        NOT NULL COMMENT 'Shipment number. Same identifier as FCT_LANDED_COST_SHIPMENT.',
  ORDER_ID          STRING        NOT NULL COMMENT 'Sales order.',
  ORDER_LINE        NUMBER        NOT NULL COMMENT 'Sales order line. Joins to ORDER_FULFILLMENT exactly as LANDED_COST does.',
  CARRIER           STRING        NOT NULL COMMENT 'Carrier name.',
  LANE_ID           STRING        NOT NULL COMMENT 'Lane used.',
  SHIP_REGION       STRING        NOT NULL COMMENT 'Destination region. Scoped by the EU row access policy, same as LANDED_COST.',
  PEAK_TEMP_C       NUMBER(5,1)   NOT NULL COMMENT 'Peak in-transit temperature reading, degrees Celsius.',
  IS_TEMP_EXCURSION NUMBER(1,0)   NOT NULL COMMENT '1 when PEAK_TEMP_C breached the cold-chain threshold.',
  IS_TRANSIT_DELAY  NUMBER(1,0)   NOT NULL COMMENT '1 when the sensor-reported transit time exceeded the lane commitment.',
  EVENT_DATE        DATE          NOT NULL COMMENT 'Date the summary reading was recorded.',
  CONSTRAINT pk_fct_shipment_telemetry PRIMARY KEY (SHIPMENT_ID)
) COMMENT = 'Atomic in-transit IoT sensor summary per shipment. Canonical source for the temperature-excursion rate metric. Same grain as FCT_LANDED_COST_SHIPMENT; joins SC_ONTOLOGY_360 through ORDER_FULFILLMENT exactly as LANDED_COST does.';

INSERT INTO FCT_SHIPMENT_TELEMETRY
SELECT
  st.shipment_id,
  sc.order_id,
  sc.order_line,
  car.carrier_name AS carrier,
  sc.lane_id,
  sc.ship_region,
  st.peak_temp_c,
  IFF(st.is_temp_excursion, 1, 0) AS is_temp_excursion,
  IFF(st.is_transit_delay, 1, 0)  AS is_transit_delay,
  st.event_date
FROM SUPPLY_CHAIN.RAW.SHIPMENT_TELEMETRY st
JOIN SUPPLY_CHAIN.RAW.SHIPMENT_COST      sc  ON sc.shipment_id = st.shipment_id
JOIN SUPPLY_CHAIN.RAW.CARRIER            car ON car.carrier_id = sc.carrier_id;

ALTER TABLE SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY
  ADD ROW ACCESS POLICY SUPPLY_CHAIN.GOVERNANCE.RAP_SHIP_REGION ON (SHIP_REGION);

GRANT SELECT ON TABLE SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY TO ROLE SC_PLANNER;
GRANT SELECT ON TABLE SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY TO ROLE SC_PROCUREMENT;
GRANT SELECT ON TABLE SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY TO ROLE SC_LOGISTICS;
GRANT SELECT ON TABLE SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY TO ROLE SC_LOGISTICS_EU;
GRANT SELECT ON TABLE SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY TO ROLE SC_ONTOLOGY_STEWARD;

-- ---------------------------------------------------------------------------
-- 3. Splice SHIPMENT_TELEMETRY into the already-live SC_ONTOLOGY_360, using the
--    exact technique documented in 01_calendar_dimension.sql. Anchors are
--    LANDED_COST strings, unaffected by the CALENDAR splice.
--
-- GET_DDL DOES NOT PRESERVE THE WHITESPACE YOU WROTE, AND THAT COST US THE VIEW.
--
-- The table anchor here used to read
--     'primary key (SNAPSHOT_DATE, MATERIAL_ID, NODE_ID)'
-- copied from 00e_semantic.sql, where it is written with spaces after the
-- commas. GET_DDL emits it WITHOUT them:
--     'primary key (SNAPSHOT_DATE,MATERIAL_ID,NODE_ID)'
--
-- So that REPLACE matched nothing and silently changed nothing, while the four
-- anchors below it matched fine. The result was a view whose RELATIONSHIPS
-- referenced SHIPMENT_TELEMETRY and whose TABLES never declared it:
--     Invalid table name 'SHIPMENT_TELEMETRY' in the RELATIONSHIPS definition
-- and because that surfaces only at EXECUTE IMMEDIATE, the failure looked like a
-- problem with the relationship rather than with the anchor three lines above it.
--
-- The whitespace is now corrected AND each anchor asserts itself first, which is
-- the rule 07_verified_queries.sql already states and this file did not follow:
--
--   ASSERT THE ANCHOR OCCURS EXACTLY ONCE BEFORE RELYING ON IT.
--   A REPLACE that matches nothing succeeds and changes nothing.
--
-- Aborting with the anchor named is strictly better than leaving an
-- uncompilable view behind, because the message points at the cause.
-- ---------------------------------------------------------------------------

USE SCHEMA SEMANTIC;

DECLARE
  ddl STRING;

  -- New logical table, inserted before the first existing table entry that
  -- follows LANDED_COST (INVENTORY) — the same "prepend before the next
  -- entry's short structural anchor" technique 01_calendar_dimension.sql uses,
  -- chosen so the insertion cannot land in the middle of LANDED_COST's own
  -- `with synonyms=(...) comment='...'` clause.
  tel_table STRING := $$SHIPMENT_TELEMETRY as SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY primary key (SHIPMENT_ID) with synonyms=('telemetry','sensor','iot','tracking','cold chain','sensor reading') comment='sco:ShipmentTelemetry - in-transit IoT sensor summary for one shipment. Fact, shipment grain. Reaches PART, CUSTOMER and CALENDAR only through ORDER_FULFILLMENT, exactly like LANDED_COST.', $$;

  tel_rel STRING := $$TELEMETRY_TO_FULFILLMENT as SHIPMENT_TELEMETRY(ORDER_ID, ORDER_LINE) references ORDER_FULFILLMENT(ORDER_ID, ORDER_LINE), $$;

  tel_facts STRING := $$SHIPMENT_TELEMETRY.EXCURSION as shipment_telemetry.is_temp_excursion comment='1 when the in-transit temperature breached the cold-chain threshold.', SHIPMENT_TELEMETRY.DELAY_FLAG as shipment_telemetry.is_transit_delay comment='1 when the sensor-reported transit time exceeded the lane commitment.', $$;

  tel_dims STRING := $$SHIPMENT_TELEMETRY.CARRIER as shipment_telemetry.carrier with synonyms=('carrier','freight carrier') comment='Carrier that moved the shipment.', SHIPMENT_TELEMETRY.LANE as shipment_telemetry.lane_id with synonyms=('lane','route') comment='Transport lane the sensor reading was recorded on.', SHIPMENT_TELEMETRY.PEAK_TEMP as shipment_telemetry.peak_temp_c with synonyms=('peak temperature','temperature reading') comment='Peak in-transit temperature, degrees Celsius.', $$;

  tel_metric STRING := $$SHIPMENT_TELEMETRY.TEMP_EXCURSION_RATE as AVG(shipment_telemetry.excursion) with synonyms=('temperature excursion rate','cold chain breach rate','iot excursion rate','sensor excursion rate') comment='Share of shipments with an in-transit temperature breach, measured from IoT sensor telemetry. Shipment-weighted, never an average of per-carrier rates.', $$;

  -- Anchors, in the exact form GET_DDL emits them. Kept in variables so each can
  -- be counted before it is used and named in the abort message if it is missing.
  a_table STRING := 'INVENTORY as SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT primary key (SNAPSHOT_DATE,MATERIAL_ID,NODE_ID)';
  a_rel   STRING := 'INVENTORY_TO_PART as INVENTORY(MATERIAL_ID)';
  a_fact  STRING := 'INVENTORY.ON_HAND as inventory.on_hand_qty';
  a_dim   STRING := 'INVENTORY.SNAPSHOT_DATE as inventory.snapshot_date';
  a_met   STRING := 'INVENTORY.DAYS_OF_INVENTORY as SUM(inventory.on_hand)';
BEGIN
  ddl := GET_DDL('SEMANTIC_VIEW', 'SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360');

  -- Already spliced? Say so rather than appending a duplicate entity.
  IF (POSITION('SHIPMENT_TELEMETRY as' IN ddl) > 0) THEN
    RETURN 'SC_ONTOLOGY_360 already carries SHIPMENT_TELEMETRY; nothing to do';
  END IF;

  -- Every anchor, or none. A partial splice is what produced an uncompilable view.
  IF (POSITION(:a_table IN ddl) = 0) THEN RETURN 'ABORT: table anchor not found: '        || :a_table; END IF;
  IF (POSITION(:a_rel   IN ddl) = 0) THEN RETURN 'ABORT: relationship anchor not found: ' || :a_rel;   END IF;
  IF (POSITION(:a_fact  IN ddl) = 0) THEN RETURN 'ABORT: fact anchor not found: '         || :a_fact;  END IF;
  IF (POSITION(:a_dim   IN ddl) = 0) THEN RETURN 'ABORT: dimension anchor not found: '    || :a_dim;   END IF;
  IF (POSITION(:a_met   IN ddl) = 0) THEN RETURN 'ABORT: metric anchor not found: '       || :a_met;   END IF;

  -- CREATE OR REPLACE drops grants; CREATE OR ALTER preserves them.
  ddl := REPLACE(ddl, 'create or replace semantic view SC_ONTOLOGY_360',
                      'create or alter semantic view SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360');

  -- Each anchor is a short structural token that STARTS the next entry after
  -- LANDED_COST's own, so new content is prepended in front of it rather than
  -- spliced into the middle of an existing multi-clause entry.
  ddl := REPLACE(ddl, :a_table, tel_table  || :a_table);
  ddl := REPLACE(ddl, :a_rel,   tel_rel    || :a_rel);
  ddl := REPLACE(ddl, :a_fact,  tel_facts  || :a_fact);
  ddl := REPLACE(ddl, :a_dim,   tel_dims   || :a_dim);
  ddl := REPLACE(ddl, :a_met,   tel_metric || :a_met);

  EXECUTE IMMEDIATE ddl;
  RETURN 'SC_ONTOLOGY_360 extended with the SHIPMENT_TELEMETRY entity';
END;

-- ---------------------------------------------------------------------------
-- 4. SC_TELEMETRY — a brand-new domain view (not a splice), so temp_excursion_rate
--    gets a genuine second binding and can PASS the drift test rather than
--    report UNTESTED. Same shape as SC_INVENTORY: one fact, its own metrics,
--    its own AI_VERIFIED_QUERIES block.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE SEMANTIC VIEW SC_TELEMETRY
  TABLES (
    SHIPMENT_TELEMETRY as SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY primary key (SHIPMENT_ID)
      with synonyms=('telemetry','sensor','iot','tracking','cold chain')
      comment='sco:ShipmentTelemetry - in-transit IoT sensor summary for one shipment. Fact, shipment grain.'
  )
  FACTS (
    SHIPMENT_TELEMETRY.EXCURSION as shipment_telemetry.is_temp_excursion comment='1 when the in-transit temperature breached the cold-chain threshold.',
    SHIPMENT_TELEMETRY.DELAY_FLAG as shipment_telemetry.is_transit_delay comment='1 when the sensor-reported transit time exceeded the lane commitment.'
  )
  DIMENSIONS (
    SHIPMENT_TELEMETRY.CARRIER as shipment_telemetry.carrier with synonyms=('carrier','freight carrier') comment='Carrier that moved the shipment.',
    SHIPMENT_TELEMETRY.LANE as shipment_telemetry.lane_id with synonyms=('lane','route') comment='Transport lane the sensor reading was recorded on.',
    SHIPMENT_TELEMETRY.PEAK_TEMP as shipment_telemetry.peak_temp_c with synonyms=('peak temperature','temperature reading') comment='Peak in-transit temperature, degrees Celsius.'
  )
  METRICS (
    SHIPMENT_TELEMETRY.TEMP_EXCURSION_RATE as AVG(shipment_telemetry.excursion)
      with synonyms=('temperature excursion rate','cold chain breach rate','iot excursion rate')
      comment='Share of shipments with an in-transit temperature breach. Identical to SHIPMENT_TELEMETRY.TEMP_EXCURSION_RATE in SC_ONTOLOGY_360.',
    SHIPMENT_TELEMETRY.TRANSIT_DELAY_RATE as AVG(shipment_telemetry.delay_flag)
      with synonyms=('transit delay rate','late shipment rate')
      comment='Share of shipments whose sensor-reported transit time exceeded the lane commitment. Not a governed metric; exploratory only.'
  )
  COMMENT = 'Shipment-level IoT telemetry. Domain-scoped subset of SC_ONTOLOGY_360; metric expressions are identical.'
  AI_VERIFIED_QUERIES (
    TEMP_EXCURSION_RATE_OVERALL AS (
      QUESTION 'What share of shipments had a temperature excursion?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_TELEMETRY METRICS shipment_telemetry.temp_excursion_rate)'
    )
  );

GRANT SELECT, REFERENCES ON SEMANTIC VIEW SC_TELEMETRY TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW SC_TELEMETRY TO ROLE SC_LOGISTICS;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW SC_TELEMETRY TO ROLE SC_LOGISTICS_EU;

-- ---------------------------------------------------------------------------
-- 5. Governance registration. Columns match what 00f, 02 and 03 already added
--    to METRIC_DEFINITION, so this metric carries the same contract as every
--    other one rather than a partial row.
-- ---------------------------------------------------------------------------

USE SCHEMA GOVERNANCE;

-- Idempotent: re-running this file used to append a second copy of every row below,
-- which doubled the drift test's binding count and listed the metric twice.
DELETE FROM METRIC_DEFINITION     WHERE metric_id = 'temp_excursion_rate';
DELETE FROM METRIC_BINDING        WHERE metric_id = 'temp_excursion_rate';
DELETE FROM METRIC_EXCEPTION_RULE WHERE metric_id = 'temp_excursion_rate';
DELETE FROM PERSONA_VIEW_ACCESS   WHERE semantic_view = 'SC_TELEMETRY';

INSERT INTO METRIC_DEFINITION
  (metric_id, business_name, domain, definition, numerator, denominator, grain,
   canonical_fact, canonical_sql, unit, direction, owner_role, version, effective_from,
   as_of_scope, as_of_rule, target_value, warn_threshold, fail_threshold, target_source)
SELECT * FROM VALUES
 ('temp_excursion_rate','Temperature Excursion Rate','LOGISTICS',
  'Share of shipments whose in-transit IoT sensor recorded a peak temperature above the cold-chain threshold. Weighted by shipment, not an average of per-carrier rates.',
  'Shipments where PEAK_TEMP_C exceeded the cold-chain threshold','All shipments in scope','shipment',
  'CANONICAL.FCT_SHIPMENT_TELEMETRY',
  'SELECT AVG(is_temp_excursion) AS VAL FROM SUPPLY_CHAIN.CANONICAL.FCT_SHIPMENT_TELEMETRY',
  'ratio','lower','SC_LOGISTICS_ANALYST',1,CURRENT_DATE()::DATE,
  'REALIZED','Exclude future-dated rows: WHERE calendar.is_future = 0. Rows dated after today are promised future activity, not measured performance.',
  0.03, 0.045, 0.06,
  'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_LOGISTICS_ANALYST.')
AS v(metric_id, business_name, domain, definition, numerator, denominator, grain,
     canonical_fact, canonical_sql, unit, direction, owner_role, version, effective_from,
     as_of_scope, as_of_rule, target_value, warn_threshold, fail_threshold, target_source);

INSERT INTO METRIC_BINDING (metric_id, semantic_view, metric_reference, persona_role)
SELECT * FROM VALUES
 ('temp_excursion_rate','SC_ONTOLOGY_360','shipment_telemetry.temp_excursion_rate',NULL),
 ('temp_excursion_rate','SC_TELEMETRY','shipment_telemetry.temp_excursion_rate','SC_LOGISTICS');

INSERT INTO METRIC_EXCEPTION_RULE
  (metric_id, canonical_fact, date_column, exception_where, display_columns, order_by, description)
SELECT * FROM VALUES
 ('temp_excursion_rate','CANONICAL.FCT_SHIPMENT_TELEMETRY','EVENT_DATE','IS_TEMP_EXCURSION = 1',
  'SHIPMENT_ID,ORDER_ID,ORDER_LINE,CARRIER,LANE_ID,SHIP_REGION,PEAK_TEMP_C,EVENT_DATE',
  'PEAK_TEMP_C DESC','Shipments whose peak in-transit temperature breached the cold-chain threshold.');

INSERT INTO PERSONA_VIEW_ACCESS (role_name, semantic_view)
SELECT * FROM VALUES
 ('SC_ONTOLOGY_STEWARD','SC_TELEMETRY'),
 ('SC_LOGISTICS','SC_TELEMETRY'),
 ('SC_LOGISTICS_EU','SC_TELEMETRY');

-- Sanity check: temp_excursion_rate now has 2 bindings, so METRIC_DRIFT_TEST can
-- compare them instead of reporting UNTESTED. See sql/90_verify_base.sql for the
-- authoritative assertion.
SELECT metric_id, COUNT(*) AS binding_count
FROM METRIC_BINDING
WHERE metric_id = 'temp_excursion_rate'
GROUP BY metric_id;


-- ============================================================================
-- FILE: 12_ontology_hierarchy.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 12 — Ontology hierarchies.
--
-- The problem statement names four things an ontology must define: entities,
-- relationships, HIERARCHIES, and canonical metrics. Three of them were already
-- derived from INFORMATION_SCHEMA and therefore incapable of drifting from the
-- deployed views. Hierarchies were not: they were a hard-coded array in
-- app/ontology/page.tsx, and three of the level names in it
-- (SUPPLIER, NODE, CUSTOMER) were not dimensions of SC_ONTOLOGY_360 at all.
-- Nothing failed. The page simply described a rollup that did not exist.
--
-- WHY THIS IS A TABLE WHEN THE REST OF THE CATALOGUE IS A VIEW
-- A Snowflake semantic view has no hierarchy construct, so unlike entities and
-- relationships there is nothing in INFORMATION_SCHEMA to read a hierarchy back
-- from. A declaration is therefore unavoidable. What IS avoidable is an
-- UNCHECKED declaration, and that is what this file removes:
--
--   1. RESOLUTION. Every declared level is joined to
--      INFORMATION_SCHEMA.SEMANTIC_DIMENSIONS, so a level naming a dimension the
--      view does not have is visibly unresolved rather than silently rendered.
--   2. ROLLUP. Every parent/child pair is MEASURED against the conformed
--      dimension it is sourced from. A hierarchy level only rolls up if each
--      child value has exactly one parent value; anything else is a
--      classification wearing a hierarchy's clothes.
--
-- Rule 2 is not theoretical either. Two plausible-looking rollups were proposed
-- and both are false in this data:
--     SUPPLIER_GROUP  -> SUPPLIER_REGION   6 groups span more than one region
--     CUSTOMER_SEGMENT-> CUSTOMER_REGION   4 segments span more than one region
-- Commodity group and go-to-market segment are cross-regional by construction.
-- Stacking them into a single chain would have produced a drill path that double
-- counts, so they are declared as their own two-level hierarchies instead.
--
-- ORDER. This must follow 01_calendar_dimension.sql: the TIME hierarchy's levels
-- only exist on SC_ONTOLOGY_360 after 01 splices CALENDAR in, and the resolution
-- check would report four MISSING levels if it ran before.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE OR REPLACE TABLE ONTOLOGY_HIERARCHY (
  hierarchy_id    STRING NOT NULL COMMENT 'Stable id of the hierarchy.',
  hierarchy_name  STRING NOT NULL COMMENT 'Display name.',
  semantic_view   STRING NOT NULL COMMENT 'Semantic view the levels must resolve against.',
  entity          STRING NOT NULL COMMENT 'Ontology entity the hierarchy belongs to.',
  level_no        NUMBER NOT NULL COMMENT 'Level, 1 = finest grain. Levels must be contiguous from 1.',
  level_dimension STRING NOT NULL COMMENT 'Dimension name within the entity, as declared in the semantic view.',
  source_table    STRING NOT NULL COMMENT 'Conformed dimension table the rollup is measured against.',
  source_column   STRING NOT NULL COMMENT 'Column in SOURCE_TABLE backing this level.',
  description     STRING COMMENT 'What this level means in business terms.',
  CONSTRAINT pk_ontology_hierarchy PRIMARY KEY (hierarchy_id, level_no)
)
COMMENT = 'Declared drill paths. A declaration alone proves nothing: VALIDATE_ONTOLOGY_HIERARCHY measures every level against the deployed view and the source data.';

INSERT INTO ONTOLOGY_HIERARCHY
  (hierarchy_id, hierarchy_name, semantic_view, entity, level_no, level_dimension, source_table, source_column, description)
SELECT * FROM VALUES
 -- Product. The only three-plus-level chain over a business dimension, and the
 -- one the application groups by most often.
 ('PRODUCT','Product','SC_ONTOLOGY_360','PART',1,'MATERIAL','SUPPLY_CHAIN.RAW.PART','MATERIAL_ID','The material itself. Finest grain of everything bought, made, stocked and sold.'),
 ('PRODUCT','Product','SC_ONTOLOGY_360','PART',2,'PRODUCT_FAMILY','SUPPLY_CHAIN.RAW.PART','PRODUCT_FAMILY','Product family. The most-used analytical grouping in the application.'),
 ('PRODUCT','Product','SC_ONTOLOGY_360','PART',3,'BUSINESS_SEGMENT','SUPPLY_CHAIN.RAW.PART','BUSINESS_SEGMENT','Reporting segment the family rolls into.'),

 -- Sourcing and commodity are SIBLINGS, not a chain. See the header note.
 ('SOURCING','Sourcing geography','SC_ONTOLOGY_360','SUPPLIER',1,'SUPPLIER_NAME','SUPPLY_CHAIN.RAW.SUPPLIER','SUPPLIER_NAME','The vendor.'),
 ('SOURCING','Sourcing geography','SC_ONTOLOGY_360','SUPPLIER',2,'SUPPLIER_REGION','SUPPLY_CHAIN.RAW.SUPPLIER','SUPPLIER_REGION','Region goods are sourced from. The inbound region.'),

 ('COMMODITY','Commodity','SC_ONTOLOGY_360','SUPPLIER',1,'SUPPLIER_NAME','SUPPLY_CHAIN.RAW.SUPPLIER','SUPPLIER_NAME','The vendor.'),
 ('COMMODITY','Commodity','SC_ONTOLOGY_360','SUPPLIER',2,'SUPPLIER_GROUP','SUPPLY_CHAIN.RAW.SUPPLIER','SUPPLIER_GROUP','Commodity group the vendor is managed under. Crosses regions by design.'),

 ('NETWORK','Network','SC_ONTOLOGY_360','NODE',1,'NODE_NAME','SUPPLY_CHAIN.RAW.NODE','NODE_NAME','Plant or distribution centre.'),
 ('NETWORK','Network','SC_ONTOLOGY_360','NODE',2,'NODE_REGION','SUPPLY_CHAIN.RAW.NODE','NODE_REGION','Region the node serves.'),

 ('ACCOUNT','Account','SC_ONTOLOGY_360','CUSTOMER',1,'CUSTOMER_NAME','SUPPLY_CHAIN.RAW.CUSTOMER','CUSTOMER_NAME','The account.'),
 ('ACCOUNT','Account','SC_ONTOLOGY_360','CUSTOMER',2,'CUSTOMER_SEGMENT','SUPPLY_CHAIN.RAW.CUSTOMER','CUSTOMER_SEGMENT','Go-to-market segment. Crosses regions by design.'),

 ('SALES_GEO','Sales geography','SC_ONTOLOGY_360','CUSTOMER',1,'CUSTOMER_NAME','SUPPLY_CHAIN.RAW.CUSTOMER','CUSTOMER_NAME','The account.'),
 ('SALES_GEO','Sales geography','SC_ONTOLOGY_360','CUSTOMER',2,'CUSTOMER_REGION','SUPPLY_CHAIN.RAW.CUSTOMER','CUSTOMER_REGION','Region the account is managed in. Where the account sits, not where goods went.'),

 -- Time. Only resolvable after 01 splices CALENDAR into SC_ONTOLOGY_360.
 ('TIME','Time','SC_ONTOLOGY_360','CALENDAR',1,'CAL_DATE','SUPPLY_CHAIN.RAW.DATE_DIM','DATE_KEY','Calendar day. The event date of every day-grain fact.'),
 ('TIME','Time','SC_ONTOLOGY_360','CALENDAR',2,'CAL_MONTH','SUPPLY_CHAIN.RAW.DATE_DIM','MONTH_START','First day of the calendar month.'),
 ('TIME','Time','SC_ONTOLOGY_360','CALENDAR',3,'CAL_QUARTER','SUPPLY_CHAIN.RAW.DATE_DIM','FISCAL_QUARTER','Fiscal quarter, calendar-aligned.'),
 ('TIME','Time','SC_ONTOLOGY_360','CALENDAR',4,'CAL_YEAR','SUPPLY_CHAIN.RAW.DATE_DIM','YEAR_NUM','Calendar year.');

CREATE OR REPLACE TABLE ONTOLOGY_HIERARCHY_VALIDATION (
  run_id            STRING NOT NULL COMMENT 'One id per validation run.',
  run_at            TIMESTAMP_LTZ NOT NULL,
  hierarchy_id      STRING NOT NULL,
  level_no          NUMBER NOT NULL,
  level_dimension   STRING NOT NULL,
  resolves          BOOLEAN COMMENT 'TRUE when the level names a dimension the semantic view actually declares.',
  rollup_status     STRING COMMENT 'BASE for level 1, PASS when every child has exactly one parent, FAIL when it does not, ERROR when the test could not run.',
  distinct_children NUMBER COMMENT 'Distinct values at the level below.',
  distinct_parents  NUMBER COMMENT 'Distinct values at this level.',
  violation_count   NUMBER COMMENT 'Child values mapping to more than one parent. Must be 0.',
  detail            STRING
)
COMMENT = 'Per-level evidence that a declared hierarchy is real. Written by VALIDATE_ONTOLOGY_HIERARCHY.';

-- ---------------------------------------------------------------------------
-- VALIDATE_ONTOLOGY_HIERARCHY — the control.
--
-- Same shape as METRIC_DRIFT_TEST and for the same reason: a per-level failure is
-- recorded and the loop continues, because a run that stops at the first broken
-- level reports nothing about the other sixteen.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE PROCEDURE VALIDATE_ONTOLOGY_HIERARCHY()
RETURNS TABLE()
LANGUAGE SQL
COMMENT = 'Checks every declared hierarchy level resolves to a dimension of its semantic view, and measures each parent/child pair against the source dimension to confirm it is a true rollup. Writes ONTOLOGY_HIERARCHY_VALIDATION.'
AS $$
DECLARE
  v_run_id   STRING;
  v_run_at   TIMESTAMP_LTZ;
  v_hid      STRING;
  v_lvl      NUMBER;
  v_dim      STRING;
  v_entity   STRING;
  v_view     STRING;
  v_src      STRING;
  v_col      STRING;
  v_psrc     STRING;
  v_pcol     STRING;
  v_resolves BOOLEAN;
  v_status   STRING;
  v_kids     NUMBER;
  v_parents  NUMBER;
  v_viol     NUMBER;
  v_detail   STRING;
  v_sql      STRING;
  res        RESULTSET;
  -- The level below is carried alongside each level so the rollup can be tested
  -- without a second lookup. LAG over the same hierarchy gives the child.
  levels CURSOR FOR
    SELECT hierarchy_id, level_no, level_dimension, entity, semantic_view,
           source_table, source_column,
           LAG(source_table)  OVER (PARTITION BY hierarchy_id ORDER BY level_no) AS child_table,
           LAG(source_column) OVER (PARTITION BY hierarchy_id ORDER BY level_no) AS child_column
      FROM SUPPLY_CHAIN.GOVERNANCE.ONTOLOGY_HIERARCHY
     ORDER BY hierarchy_id, level_no;
BEGIN
  v_run_id := UUID_STRING();
  v_run_at := CURRENT_TIMESTAMP();

  FOR l IN levels DO
    v_hid    := l.hierarchy_id;
    v_lvl    := l.level_no;
    v_dim    := l.level_dimension;
    v_entity := l.entity;
    v_view   := l.semantic_view;
    v_src    := l.source_table;
    v_col    := l.source_column;
    v_psrc   := l.child_table;
    v_pcol   := l.child_column;
    v_kids   := NULL;
    v_parents:= NULL;
    v_viol   := NULL;

    -- 1. Does the semantic view actually declare this dimension?
    SELECT COUNT(*) > 0 INTO v_resolves
      FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_DIMENSIONS
     WHERE semantic_view_name = :v_view AND table_name = :v_entity AND name = :v_dim;

    -- 2. Is it a true rollup from the level below?
    IF (v_pcol IS NULL) THEN
      v_status := 'BASE';
      v_detail := 'finest grain; nothing below it to roll up';
    ELSEIF (v_psrc <> v_src) THEN
      -- Two levels sourced from different tables cannot be tested with one GROUP BY,
      -- and a hierarchy that spans dimensions is a join, not a rollup.
      v_status := 'ERROR';
      v_detail := 'level is sourced from ' || v_src || ' but the level below is from ' || v_psrc;
    ELSE
      BEGIN
        -- Counted in one pass, but the populations are counted OUTSIDE the
        -- violation filter: a WHERE n > 1 wrapped around the whole thing would
        -- report the size of the broken part rather than of the level.
        v_sql := 'WITH g AS (SELECT ' || v_pcol || ' AS child, COUNT(DISTINCT ' || v_col
              || ') AS parents FROM ' || v_src || ' GROUP BY 1) '
              || 'SELECT COUNT(*), (SELECT COUNT(DISTINCT ' || v_col || ') FROM ' || v_src
              || '), COUNT_IF(parents > 1) FROM g';
        LET rres RESULTSET := (EXECUTE IMMEDIATE :v_sql);
        LET rcur CURSOR FOR rres;
        OPEN rcur;
        FETCH rcur INTO v_kids, v_parents, v_viol;
        CLOSE rcur;
        v_status := IFF(COALESCE(v_viol, 1) = 0, 'PASS', 'FAIL');
        v_detail := v_kids || ' ' || v_pcol || ' values roll into ' || v_parents || ' '
                 || v_col || ' values; ' || v_viol || ' map to more than one';
      EXCEPTION
        WHEN OTHER THEN
          v_status := 'ERROR';
          v_detail := 'rollup test failed: ' || SQLERRM;
      END;
    END IF;

    IF (NOT v_resolves) THEN
      v_detail := v_entity || '.' || v_dim || ' is not a dimension of ' || v_view || '. ' || v_detail;
    END IF;

    INSERT INTO SUPPLY_CHAIN.GOVERNANCE.ONTOLOGY_HIERARCHY_VALIDATION
      (run_id, run_at, hierarchy_id, level_no, level_dimension, resolves,
       rollup_status, distinct_children, distinct_parents, violation_count, detail)
    SELECT :v_run_id, :v_run_at, :v_hid, :v_lvl, :v_dim, :v_resolves,
           :v_status, :v_kids, :v_parents, :v_viol, :v_detail;
  END FOR;

  res := (
    SELECT hierarchy_id, level_no, level_dimension, resolves, rollup_status,
           distinct_children, distinct_parents, violation_count, detail
      FROM SUPPLY_CHAIN.GOVERNANCE.ONTOLOGY_HIERARCHY_VALIDATION
     WHERE run_id = :v_run_id
     ORDER BY hierarchy_id, level_no
  );
  RETURN TABLE(res);
END;
$$;

-- What /ontology renders: the declaration, its resolution against the deployed
-- view, and the latest measured rollup result, in one row per level.
CREATE OR REPLACE VIEW V_ONTOLOGY_HIERARCHY
  COMMENT = 'Declared hierarchy levels joined to the deployed semantic view and to the most recent validation run. A level that does not resolve, or does not roll up, is visible rather than silently rendered.'
AS
WITH latest AS (
  SELECT *
    FROM SUPPLY_CHAIN.GOVERNANCE.ONTOLOGY_HIERARCHY_VALIDATION
  QUALIFY ROW_NUMBER() OVER (PARTITION BY hierarchy_id, level_no ORDER BY run_at DESC) = 1
)
SELECT
  h.hierarchy_id,
  h.hierarchy_name,
  h.semantic_view,
  h.entity,
  h.level_no,
  h.level_dimension,
  h.entity || '.' || h.level_dimension AS dimension_ref,
  h.source_table,
  h.source_column,
  h.description,
  (d.name IS NOT NULL)                 AS resolves,
  MAX(h.level_no) OVER (PARTITION BY h.hierarchy_id) AS level_count,
  v.rollup_status,
  v.distinct_children,
  v.distinct_parents,
  v.violation_count,
  v.detail                             AS validation_detail,
  v.run_at                             AS validated_at
FROM SUPPLY_CHAIN.GOVERNANCE.ONTOLOGY_HIERARCHY h
LEFT JOIN SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_DIMENSIONS d
       ON d.semantic_view_name = h.semantic_view
      AND d.table_name         = h.entity
      AND d.name               = h.level_dimension
LEFT JOIN latest v
       ON v.hierarchy_id = h.hierarchy_id
      AND v.level_no     = h.level_no;

CALL VALIDATE_ONTOLOGY_HIERARCHY();

-- Assertions. 90_verify_base.sql repeats these so a later change to a semantic
-- view is caught by the verification phase, not only on the day this file runs.
SELECT 'every hierarchy level resolves to a deployed dimension' AS check_name,
       COUNT_IF(NOT resolves) AS unresolved,
       IFF(COUNT_IF(NOT resolves) = 0, 'PASS', 'FAIL') AS status
  FROM V_ONTOLOGY_HIERARCHY;

SELECT 'every declared rollup is a true functional dependency' AS check_name,
       COUNT_IF(rollup_status NOT IN ('PASS','BASE')) AS bad_levels,
       IFF(COUNT_IF(rollup_status NOT IN ('PASS','BASE')) = 0, 'PASS', 'FAIL') AS status
  FROM V_ONTOLOGY_HIERARCHY;


-- ============================================================================
-- FILE: 14_agent_eval_run.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 14 — Scoring the evaluation set.
--
-- 09_agent_eval.sql defines 60 golden questions and says, in its header, that
-- scoring "belongs to a run, not to the question". That was correct and it was
-- also incomplete: nothing ran them. The project's own standard --
--
--   "A drift test that has only ever passed is indistinguishable from a drift
--    test that is not running."
--
-- -- applied to every governed metric and to nothing in the conversational
-- layer, which was the one part of the system whose accuracy was asserted rather
-- than measured. This file closes that.
--
-- WHY A RUN IS SCORED OVER HTTP RATHER THAN IN SQL
-- The thing under test is not a prompt, it is the whole governed path: resolve
-- the question against the registry, validate the model's choice against
-- INFORMATION_SCHEMA, assume the persona's role, apply the row access policy,
-- execute. Scoring the resolver alone would measure the easy half and report it
-- as the whole. scripts/eval.mjs therefore signs in as each question's persona
-- and drives /api/ask exactly as a browser does, and writes the outcome here.
--
-- THE THREE SCORING RULES, AND WHY THE MIDDLE ONE EXISTS
--
--   SHOULD_ANSWER = FALSE   pass when the layer declines. Eight questions.
--                           Refusing correctly is as much a pass as resolving
--                           correctly: an invented metric looks exactly like a
--                           real one, while a refusal is visibly a refusal.
--
--   EXPECTED_METRIC_IDS     pass when the layer does NOT silently commit to one
--     IS NULL               of the competing metrics -- it either asks, or
--                           answers with more than one and says so. Three
--                           questions. "What is our on-time delivery?" with no
--                           side named is the canonical case: inbound supplier
--                           OTD and outbound customer OTD are different metrics
--                           over different facts, and picking one quietly is the
--                           exact conflation this ontology exists to prevent.
--                           A confident single answer is therefore scored as a
--                           FAILURE even though the number it returns is real.
--
--   otherwise               pass when the resolved metric ids equal
--                           EXPECTED_METRIC_IDS, order-insensitive.
--
-- WHAT IS DELIBERATELY NOT SCORED. EXPECTED_TOOL names the semantic view the
-- Cortex Agent should route to. /api/ask always resolves against SC_ONTOLOGY_360
-- by design -- it is the cross-domain view, and routing is the agent's job, not
-- the application's -- so scoring the app against EXPECTED_TOOL would fail all
-- 60 for a difference that is architectural rather than wrong. The view actually
-- used is recorded so the omission is visible instead of silent.
--
-- ---------------------------------------------------------------------------
-- ONE QUESTION IS SCORED MORE STRICTLY THAN ITS OWN TEXT REQUIRES, ON PURPOSE
--
-- Q57's EXPECTED_BEHAVIOUR reads: "Must report a balance at one snapshot, OR
-- EXPLAIN WHY A SUM IS MEANINGLESS HERE." The layer takes the second path -- it
-- declines and explains that summing twelve month-end balances counts the same
-- stock twelve times -- which is a pass by the question's own wording and a
-- FAILURE by the three rules above, because the rules are set-equality on metric
-- ids and cannot express "either of two good outcomes".
--
-- The point is left on the table rather than special-cased. A scorer that starts
-- carrying exceptions for questions it knows it fails has stopped being a scorer,
-- and the exception would be indistinguishable from the same edit made to make a
-- number look better. One understated result is much cheaper than a scoring rule
-- nobody can trust.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE TABLE IF NOT EXISTS AGENT_EVAL_RUN (
  run_id           STRING NOT NULL COMMENT 'One id per scored run.',
  run_at           TIMESTAMP_LTZ NOT NULL,
  target_base      STRING COMMENT 'Deployment the run was scored against.',
  resolver_model   STRING COMMENT 'Model the conversational layer resolved with.',
  questions        NUMBER NOT NULL,
  passed           NUMBER NOT NULL,
  failed           NUMBER NOT NULL,
  errored          NUMBER NOT NULL COMMENT 'Questions the run could not score at all: transport failure, timeout, non-JSON response.',
  accuracy         FLOAT  NOT NULL COMMENT 'passed / questions.',
  refusals_expected NUMBER COMMENT 'Questions that must be declined.',
  refusals_correct  NUMBER COMMENT 'Of those, how many were.',
  ambiguity_correct NUMBER COMMENT 'Ambiguous questions that asked rather than guessed.',
  traps_correct     NUMBER COMMENT 'Trap questions resolved to the right metric.',
  mean_latency_ms   NUMBER,
  p95_latency_ms    NUMBER,
  CONSTRAINT pk_agent_eval_run PRIMARY KEY (run_id)
)
COMMENT = 'One row per scored run of the 60-question evaluation set. A run, not a verdict on the questions: baking a result into the question set is how an evaluation set quietly becomes a record of one good day.';

CREATE TABLE IF NOT EXISTS AGENT_EVAL_RESULT (
  run_id              STRING NOT NULL,
  question_id         STRING NOT NULL,
  category            STRING,
  persona_role        STRING,
  should_answer       BOOLEAN,
  expected_metric_ids STRING,
  resolved_metric_ids STRING,
  semantic_view_used  STRING COMMENT 'Always SC_ONTOLOGY_360 on the application path. Recorded so that is visible rather than assumed.',
  answerable          BOOLEAN COMMENT 'What the layer decided.',
  reason              STRING COMMENT 'The refusal reason, or the resolution rationale.',
  passed              BOOLEAN NOT NULL,
  failure_mode        STRING COMMENT 'Why it failed. NULL on a pass.',
  latency_ms          NUMBER,
  CONSTRAINT pk_agent_eval_result PRIMARY KEY (run_id, question_id)
)
COMMENT = 'Per-question outcome of one evaluation run. FAILURE_MODE is the field to read: an accuracy figure without the failures behind it is a scoreboard, not a diagnostic.';

-- The latest run, for the application. A view rather than a MAX() in the app so
-- the page cannot disagree with the table about which run is current.
CREATE OR REPLACE VIEW V_AGENT_EVAL_LATEST
  COMMENT = 'Most recent scored run of the evaluation set.'
AS
SELECT *
  FROM SUPPLY_CHAIN.GOVERNANCE.AGENT_EVAL_RUN
QUALIFY ROW_NUMBER() OVER (ORDER BY run_at DESC) = 1;

CREATE OR REPLACE VIEW V_AGENT_EVAL_BY_CATEGORY
  COMMENT = 'Latest run broken down by question category, worst first. Where the conversational layer is weak, not merely how often it is right.'
AS
SELECT
  r.category,
  COUNT(*)                                            AS questions,
  COUNT_IF(r.passed)                                  AS passed,
  COUNT(*) - COUNT_IF(r.passed)                       AS failed,
  ROUND(COUNT_IF(r.passed) / NULLIF(COUNT(*), 0), 4)  AS accuracy,
  ROUND(AVG(r.latency_ms))                            AS mean_latency_ms
FROM SUPPLY_CHAIN.GOVERNANCE.AGENT_EVAL_RESULT r
JOIN SUPPLY_CHAIN.GOVERNANCE.V_AGENT_EVAL_LATEST l ON l.run_id = r.run_id
GROUP BY r.category;

-- The failures of the latest run, which is the half of the result worth reading.
CREATE OR REPLACE VIEW V_AGENT_EVAL_FAILURE
  COMMENT = 'Questions the latest run got wrong, with what was expected and what came back.'
AS
SELECT
  r.question_id, r.category, r.persona_role, q.question,
  r.expected_metric_ids, r.resolved_metric_ids, r.failure_mode, r.reason, r.latency_ms
FROM SUPPLY_CHAIN.GOVERNANCE.AGENT_EVAL_RESULT r
JOIN SUPPLY_CHAIN.GOVERNANCE.V_AGENT_EVAL_LATEST l ON l.run_id = r.run_id
LEFT JOIN SUPPLY_CHAIN.GOVERNANCE.AGENT_EVAL_QUESTION q ON q.question_id = r.question_id
WHERE NOT r.passed;


-- ============================================================================
-- FILE: 15_agent_parity.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 15 — Agent/application parity.
--
-- /api/ask deliberately does not route through SNOWFLAKE_INTELLIGENCE.AGENTS.
-- SC_ONTOLOGIST_AGENT, and the reasons are structural rather than stylistic:
-- an agent resolves permissions from the user's DEFAULT role rather than the
-- session role, so the per-request USE ROLE + USE SECONDARY ROLES NONE guarantee
-- would not hold and SC_LOGISTICS_EU would silently receive all-region numbers.
--
-- That is a good reason and it is also an easy thing to disbelieve. Read quickly,
-- "we built a Cortex Agent and then routed around it" looks like a gap rather
-- than a decision, and the only honest way to settle it is to run both and
-- compare.
--
-- WHAT PARITY MEANS HERE. The two paths are NOT the same mechanism and are not
-- supposed to be:
--
--   agent        chooses a domain semantic view, writes its own SQL (or reuses a
--                verified query), executes under the agent's resolved role
--   application  chooses registered metric ids, assembles SQL from the registry,
--                executes SC_ONTOLOGY_360 under the persona's role
--
-- Different engine, different view, different SQL. If the ontology is doing its
-- job the NUMBER is identical anyway, because both are evaluating the same
-- governed definition. That is the claim this table tests.
--
-- WHY RECORDED RATHER THAN RUN ON PAGE LOAD. A full agent turn routinely takes
-- longer than the serverless budget, so putting it on the request path would
-- make the page that proves the system is trustworthy the page most likely to
-- time out. Drift is handled the same way: run on a schedule, record, display
-- the recorded run with its timestamp.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE TABLE IF NOT EXISTS AGENT_PARITY_RESULT (
  run_id                 STRING NOT NULL,
  run_at                 TIMESTAMP_LTZ NOT NULL,
  question               STRING NOT NULL,
  metric_id              STRING,
  agent_value            FLOAT   COMMENT 'What the Cortex Agent returned.',
  agent_semantic_view    STRING  COMMENT 'Domain view the agent routed to.',
  agent_sql              STRING  COMMENT 'SQL the agent actually executed.',
  agent_verified_query   BOOLEAN COMMENT 'TRUE when the agent reused a stored verified query rather than deriving SQL.',
  agent_latency_ms       NUMBER,
  app_value              FLOAT   COMMENT 'What the governed application path returned.',
  app_semantic_view      STRING,
  app_persona            STRING  COMMENT 'Role the application query executed as.',
  app_latency_ms         NUMBER,
  canonical_value        FLOAT   COMMENT 'METRIC_DEFINITION.CANONICAL_SQL evaluated independently. The tie-breaker: it says which engine is faithful to the definition when the two disagree.',
  spread                 FLOAT   COMMENT 'ABS(agent - app).',
  status                 STRING  NOT NULL COMMENT 'MATCH, AS_OF_GAP (agent equals canonical; the residual is the governed as-of rule), DIVERGE, or ERROR.',
  detail                 STRING,
  CONSTRAINT pk_agent_parity PRIMARY KEY (run_id, question)
)
COMMENT = 'Two engines, one definition. Records the Cortex Agent and the governed application path answering the same question, so the decision to keep them separate is demonstrable rather than merely explained.';

CREATE OR REPLACE VIEW V_AGENT_PARITY_LATEST
  COMMENT = 'Most recent parity run, one row per question.'
AS
SELECT *
  FROM SUPPLY_CHAIN.GOVERNANCE.AGENT_PARITY_RESULT
 WHERE run_id = (
   SELECT run_id FROM SUPPLY_CHAIN.GOVERNANCE.AGENT_PARITY_RESULT ORDER BY run_at DESC LIMIT 1
 );


-- ============================================================================
-- FILE: 17_impact_scorecard.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 17 - The impact scorecard.
--
-- Every claim this project makes about its own value already exists somewhere
-- as a measured row: the drift run, the eval run, the parity run, the
-- divergence verdicts, the contract compliance view. What did not exist is one
-- place that states them together, with the source object beside each number
-- and an explicit label saying whether it was MEASURED or is an ASSUMPTION.
--
-- That label is the point. A hackathon impact slide is usually a column of
-- confident figures with no provenance. Here the only assumption is the one a
-- reader can check against their own organisation -- how long a cross-team
-- metric question takes to settle today -- and it is labelled as such, next to
-- the measured latency it is compared with.
--
-- Recomputed on read. Nothing here is stored, so it cannot go stale.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE OR REPLACE VIEW V_IMPACT_SCORECARD
  COMMENT = 'Measured outcomes of the governed ontology, one row per claim, each with its source object and a MEASURED/ASSUMPTION basis label. Recomputed on read.'
AS
WITH
drift AS (
  SELECT COUNT(*) AS bindings_tested, COUNT_IF(status = 'PASS') AS passed, MAX(value_spread) AS max_spread, MAX(run_at) AS run_at
    FROM METRIC_DRIFT_RESULT
   WHERE run_id = (SELECT run_id FROM METRIC_DRIFT_RESULT ORDER BY run_at DESC LIMIT 1)
),
-- Latest run that covered the WHOLE eval set. A partial debug run (scripts/eval.mjs --only ...)
-- previously became the headline: "50% (1 / 2)" on a two-question smoke test.
ev AS (
  SELECT * FROM AGENT_EVAL_RUN
   WHERE questions >= (SELECT COUNT(*) FROM AGENT_EVAL_QUESTION)
   ORDER BY run_at DESC LIMIT 1
),
par AS (
  SELECT COUNT(*) AS questions, COUNT_IF(status = 'MATCH') AS matched, COUNT_IF(status = 'AS_OF_GAP') AS as_of_gap, COUNT_IF(status = 'DIVERGE') AS diverged, MAX(run_at) AS run_at
    FROM AGENT_PARITY_RESULT
   WHERE run_id = (SELECT run_id FROM AGENT_PARITY_RESULT ORDER BY run_at DESC LIMIT 1)
),
dv AS (SELECT * FROM V_DIVERGENCE_IMPACT),
ct AS (SELECT * FROM V_CONTRACT_IMPACT),
-- Cortex Analyst graded over the same eval set, per persona (scripts/analyst-parity.mjs).
an AS (
  SELECT COUNT_IF(should_answer) AS questions, COUNT_IF(should_answer AND status = 'PASS') AS passed,
         COUNT_IF(NOT should_answer) AS refusals_expected, COUNT_IF(NOT should_answer AND status = 'PASS') AS refusals_correct,
         COUNT_IF(status = 'FAIL' AND detail ILIKE 'SQL not a governed%') AS ungoverned_blocked,
         ROUND(AVG(latency_ms)) AS mean_ms, MAX(run_at) AS run_at
    FROM ANALYST_PARITY_RESULT
   WHERE run_at = (SELECT MAX(run_at) FROM ANALYST_PARITY_RESULT)
),
-- The brief's problem, measured: spread of source-system answers to one question (sql/27).
src AS (
  SELECT MAX(IFF(is_governed, NULL, otd_value)) - MIN(IFF(is_governed, NULL, otd_value)) AS spread,
         COUNT_IF(NOT is_governed) AS sources
    FROM V_SOURCE_DEFINITION_SPREAD WHERE direction = 'OUTBOUND'
),
-- The one assumption. Four hours is a conservative reading of "someone
-- notices two decks disagree, two analysts reconcile, a steward rules" --
-- replace it with your own figure; every row that uses it says so.
baseline AS (SELECT 4.0 AS manual_reconciliation_hours)
SELECT * FROM (
  SELECT 1 AS ord, 'Consistency' AS pillar, 'Metric bindings resolving to the canonical value' AS measure,
         d.passed || ' / ' || d.bindings_tested AS value, 'MEASURED' AS basis,
         'METRIC_DRIFT_RESULT (run ' || TO_VARCHAR(d.run_at, 'YYYY-MM-DD') || ')' AS source_object FROM drift d
  UNION ALL
  SELECT 2, 'Consistency', 'Largest spread between personas on the same metric',
         TO_VARCHAR(d.max_spread), 'MEASURED', 'METRIC_DRIFT_RESULT' FROM drift d
  UNION ALL
  SELECT 3, 'Accuracy', 'Conversational eval pass rate (golden questions, run as each persona)',
         ROUND(e.accuracy * 100, 1) || '% (' || e.passed || ' / ' || e.questions || ')', 'MEASURED',
         'AGENT_EVAL_RUN (' || e.resolver_model || ')' FROM ev e
  UNION ALL
  SELECT 4, 'Accuracy', 'Invented-metric questions correctly refused',
         e.refusals_correct || ' / ' || e.refusals_expected, 'MEASURED', 'AGENT_EVAL_RUN' FROM ev e
  UNION ALL
  SELECT 5, 'Accuracy', 'Cortex Agent reproduces the canonical definition (agent vs. app vs. registry SQL)',
         (p.matched + p.as_of_gap) || ' / ' || p.questions || ' reconciled, ' || p.diverged || ' diverge (' || p.as_of_gap || ' differ only by the governed as-of rule)', 'MEASURED', 'AGENT_PARITY_RESULT' FROM par p
  UNION ALL
  SELECT 6, 'Accuracy', 'Contract terms extracted correctly by AI_EXTRACT',
         ROUND(c.extraction_accuracy * 100, 1) || '% of fields', 'MEASURED', 'V_CONTRACT_EXTRACTION_ACCURACY' FROM ct c
  UNION ALL
  SELECT 7, 'Decisions', 'Suppliers the legacy definition wrongly clears',
         dv.false_passes || ' of ' || dv.suppliers || ' (compliant list inflated ' || ROUND(dv.compliant_list_inflation * 100) || '%)',
         'MEASURED', 'V_DIVERGENCE_IMPACT' FROM dv
  UNION ALL
  SELECT 8, 'Money', 'Claimable contract penalties on governed breaches',
         '$' || TRIM(TO_VARCHAR(c.penalty_exposure_usd, '999,999,999')) || ' across ' || c.breaches_governed || ' suppliers',
         'MEASURED', 'V_CONTRACT_IMPACT' FROM ct c
  UNION ALL
  SELECT 9, 'Money', 'Penalties hidden by the legacy definition (breached, shown compliant)',
         '$' || TRIM(TO_VARCHAR(c.penalty_missed_by_legacy_usd, '999,999,999')) || ' across ' || c.hidden_breaches || ' suppliers',
         'MEASURED', 'V_CONTRACT_IMPACT' FROM ct c
  UNION ALL
  SELECT 10, 'Governance', 'Contracts measuring OTD with the non-governed definition',
         c.definition_conflicts || ' of ' || c.contracts, 'MEASURED', 'V_CONTRACT_IMPACT' FROM ct c
  UNION ALL
  SELECT 11, 'Time', 'Mean time to a governed, persona-scoped answer',
         ROUND(e.mean_latency_ms / 1000, 1) || ' s (p95 ' || ROUND(e.p95_latency_ms / 1000, 1) || ' s)', 'MEASURED', 'AGENT_EVAL_RUN' FROM ev e
  UNION ALL
  SELECT 12, 'Time', 'Manual reconciliation of a disputed cross-team metric (baseline)',
         b.manual_reconciliation_hours || ' h', 'ASSUMPTION', 'replace with your own figure' FROM baseline b
  UNION ALL
  SELECT 13, 'Time', 'Speed-up versus the manual baseline',
         ROUND(b.manual_reconciliation_hours * 3600000 / NULLIF(e.mean_latency_ms, 0)) || 'x faster',
         'ASSUMPTION', 'row 11 measured / row 12 assumed' FROM ev e, baseline b  UNION ALL
  SELECT 14, 'Consistency', 'Outbound OTD across source systems (TMS, CRM) vs. one governed answer',
         ROUND(s.spread * 100, 1) || ' pts spread across ' || s.sources || ' sources -> 0 pts governed', 'MEASURED',
         'V_SOURCE_DEFINITION_SPREAD' FROM src s
  UNION ALL
  SELECT 15, 'Accuracy', 'Cortex Analyst resolves answerable questions to the governed metric (run as each persona)',
         ROUND(100 * a.passed / NULLIF(a.questions, 0), 1) || '% (' || a.passed || ' / ' || a.questions || '), '
           || a.ungoverned_blocked || ' raw-table SQL blocked by the guard',
         'MEASURED', 'ANALYST_PARITY_RESULT (run ' || TO_VARCHAR(a.run_at, 'YYYY-MM-DD') || ')' FROM an a WHERE a.questions > 0
  UNION ALL
  SELECT 16, 'Accuracy', 'Invented-metric and out-of-scope questions not answered: Cortex Analyst path vs. registry engine',
         a.refusals_correct || ' / ' || a.refusals_expected || ' Analyst path (guard + persona scope) vs. ' || e.refusals_correct || ' / ' || e.refusals_expected
           || ' registry engine',
         'MEASURED', 'ANALYST_PARITY_RESULT + AGENT_EVAL_RUN' FROM an a, ev e WHERE a.refusals_expected > 0
)
ORDER BY ord;

GRANT SELECT ON VIEW V_IMPACT_SCORECARD TO ROLE SC_PLANNER;
GRANT SELECT ON VIEW V_IMPACT_SCORECARD TO ROLE SC_PROCUREMENT;
GRANT SELECT ON VIEW V_IMPACT_SCORECARD TO ROLE SC_LOGISTICS;
GRANT SELECT ON VIEW V_IMPACT_SCORECARD TO ROLE SC_LOGISTICS_EU;
GRANT SELECT ON VIEW V_IMPACT_SCORECARD TO ROLE SC_ONTOLOGY_STEWARD;

SELECT * FROM V_IMPACT_SCORECARD;


-- ============================================================================
-- FILE: 18_scor_alignment.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 18 - Industry alignment: every governed metric mapped to the SCOR model.
--
-- SCOR (Supply Chain Operations Reference, ASCM) is the vocabulary supply chain
-- practitioners already use. A governed metric that says "this is SCOR RL.2.2,
-- Delivery Performance to Customer Commit Date" is understood by a planner in any
-- company without a meeting; "otd_pct" is not.
--
-- THE ALIGNMENT GRADE IS THE POINT, NOT THE CODE.
--   EXACT        our definition computes the SCOR metric as SCOR defines it
--   VARIANT      same intent, measured differently - the note says how
--   COMPONENT    an input to a SCOR metric, not the metric itself
--   NOT_IN_SCOR  no SCOR equivalent; mapped to the attribute it serves
-- A mapping that claimed EXACT for every row would be the average-of-averages
-- mistake again, one level up: two things called the same name that are not the
-- same number.
--
-- Codes are SCOR 12.0 level-1/level-2 metric identifiers. Where we are not
-- certain of an identifier the code is left NULL and the SCOR metric is named
-- instead - an honest gap is better than a plausible-looking code. Verify against
-- your organisation's licensed SCOR reference before relying on a code externally.
--
-- Kept in its own table rather than as columns on METRIC_DEFINITION: the registry
-- is the drift contract, and industry mapping is documentation about it, not part
-- of it. Nothing here can change a metric's value.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE OR REPLACE TABLE METRIC_SCOR_ALIGNMENT (
  metric_id        STRING NOT NULL,
  scor_attribute   STRING NOT NULL COMMENT 'Reliability, Responsiveness, Agility, Cost or Asset Management Efficiency.',
  scor_process     STRING NOT NULL COMMENT 'Plan, Source, Make, Deliver, Return or Enable.',
  scor_code        STRING          COMMENT 'SCOR 12.0 metric id. NULL when not certain - see scor_metric.',
  scor_metric      STRING NOT NULL COMMENT 'The SCOR metric name this maps to.',
  alignment        STRING NOT NULL COMMENT 'EXACT, VARIANT, COMPONENT or NOT_IN_SCOR.',
  note             STRING NOT NULL COMMENT 'How our definition differs, or why it is exact.',
  CONSTRAINT pk_metric_scor PRIMARY KEY (metric_id)
) COMMENT = 'Governed metrics mapped to the SCOR model, each with an honest alignment grade. Documentation of the registry, never an input to it.';

INSERT INTO METRIC_SCOR_ALIGNMENT
SELECT * FROM VALUES
 ('perfect_order_pct', 'Reliability', 'Deliver', 'RL.1.1', 'Perfect Order Fulfillment', 'EXACT',
  'An order line counts only when on time, in full, and free of a recorded defect - the SCOR conjunction of its level-2 components.'),
 ('otd_pct', 'Reliability', 'Deliver', 'RL.2.2', 'Delivery Performance to Customer Commit Date', 'EXACT',
  'Delivered on or before the date committed to the customer, per order line, future-dated commitments excluded.'),
 ('fill_rate_pct', 'Reliability', 'Deliver', 'RL.2.1', '% of Orders Delivered in Full', 'VARIANT',
  'SCOR counts orders delivered complete; ours is a unit fill rate (units shipped / units ordered), which credits partial lines.'),
 ('otif_pct', 'Reliability', 'Deliver', NULL, 'Composite of RL.2.1 (in full) and RL.2.2 (on time)', 'VARIANT',
  'OTIF is an industry convention rather than a SCOR metric: RL.1.1 without the documentation and condition tests.'),
 ('temp_excursion_rate', 'Reliability', 'Deliver', 'RL.2.4', 'Perfect Condition', 'VARIANT',
  'The inverse, for cold chain only: share of shipments whose telemetry breached the temperature threshold.'),
 ('supplier_otd_pct', 'Reliability', 'Source', NULL, '% Orders Received On-Time to Demand Requirement', 'VARIANT',
  'Measured against the date the supplier promised, not the date demand required - the supplier-accountable view.'),
 ('supplier_fill_rate', 'Reliability', 'Source', NULL, '% Orders Received Complete', 'VARIANT',
  'Unit-weighted received over ordered, rather than a count of complete receipts.'),
 ('days_of_inventory', 'Asset Management Efficiency', 'Plan', 'AM.2.2', 'Inventory Days of Supply', 'EXACT',
  'On-hand over average daily demand at one month-end snapshot; never aggregated across snapshots.'),
 ('inventory_value_usd', 'Asset Management Efficiency', 'Plan', NULL, 'Inventory value (input to Return on Working Capital)', 'COMPONENT',
  'On-hand at standard cost at one snapshot. SCOR uses it inside working-capital metrics, not as a metric of its own.'),
 ('landed_cost_per_unit', 'Cost', 'Deliver', NULL, 'Cost to Serve (component of Total Supply Chain Management Cost)', 'COMPONENT',
  'Product plus freight plus duty per unit shipped. A cost-to-serve input, not the SCOR total.'),
 ('landed_cost_usd', 'Cost', 'Deliver', 'CO.1.001', 'Total Supply Chain Management Cost', 'COMPONENT',
  'Covers product, freight and duty only; SCOR also includes planning, sourcing and returns overheads.'),
 ('freight_cost_usd', 'Cost', 'Deliver', NULL, 'Transportation cost (component of CO.1.001)', 'COMPONENT',
  'Accrued freight. The deliver-transportation slice of total supply chain cost.'),
 ('freight_invoiced_usd', 'Cost', 'Deliver', NULL, 'Transportation cost (component of CO.1.001)', 'COMPONENT',
  'Invoiced freight - what carriers billed, as opposed to what was accrued.'),
 ('freight_bill_variance_usd', 'Cost', 'Enable', NULL, 'No SCOR equivalent (freight audit control)', 'NOT_IN_SCOR',
  'A billing-control measure: invoiced minus accrued freight. Serves the Cost attribute.'),
 ('ppv', 'Cost', 'Source', NULL, 'No SCOR equivalent (procurement finance)', 'NOT_IN_SCOR',
  'Purchase price variance is a standard-costing measure used by procurement finance. Serves the Cost attribute.');

-- Every registered metric must be mapped, and nothing may be mapped that is not registered.
SELECT 'every registered metric has a SCOR alignment' AS check_name,
       (SELECT COUNT(*) FROM METRIC_DEFINITION d WHERE NOT EXISTS
          (SELECT 1 FROM METRIC_SCOR_ALIGNMENT a WHERE a.metric_id = d.metric_id)) AS unmapped,
       (SELECT COUNT(*) FROM METRIC_SCOR_ALIGNMENT a WHERE NOT EXISTS
          (SELECT 1 FROM METRIC_DEFINITION d WHERE d.metric_id = a.metric_id)) AS orphaned,
       IFF(unmapped = 0 AND orphaned = 0, 'PASS', 'FAIL') AS status;

GRANT SELECT ON TABLE METRIC_SCOR_ALIGNMENT TO ROLE SC_PLANNER;
GRANT SELECT ON TABLE METRIC_SCOR_ALIGNMENT TO ROLE SC_PROCUREMENT;
GRANT SELECT ON TABLE METRIC_SCOR_ALIGNMENT TO ROLE SC_LOGISTICS;
GRANT SELECT ON TABLE METRIC_SCOR_ALIGNMENT TO ROLE SC_LOGISTICS_EU;
GRANT SELECT ON TABLE METRIC_SCOR_ALIGNMENT TO ROLE SC_ONTOLOGY_STEWARD;

SELECT alignment, COUNT(*) FROM METRIC_SCOR_ALIGNMENT GROUP BY 1 ORDER BY 1;


-- ============================================================================
-- FILE: 19_trust_signals.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 19 - Trust signals: certification, data quality, and one badge per answer.
--
-- Consistency proves that every team gets the same number. It does not prove
-- the number is built on data anyone should trust. This file adds the two
-- signals a consumer actually looks for, and folds them into one row per
-- semantic view that the conversational layer shows beside every answer:
--
--   CERTIFIED   SNOWFLAKE.CORE.CERTIFICATION_STATUS on each governed semantic
--               view and canonical fact - the platform's own trusted-source tag,
--               so the same signal appears in Snowsight search and the catalog.
--   CHECKED     Data Metric Functions on every canonical fact (nulls in keys and
--               measures, duplicate keys), each with an expectation of zero.
--   DRIFT-FREE  the latest METRIC_DRIFT_TEST result for the view's bindings.
--
-- THE NEGATIVE CONTROL IS NEVER CERTIFIED. SC_SUPPLIER_LEGACY_DEFECT is the
-- knowingly wrong view kept deployed so the drift test can fail. Certifying it
-- would put a trusted-source badge on the one number we know to be wrong, so
-- the tag is explicitly removed and the build asserts it stays removed.
--
-- WHY THE CHECKS ARE LISTED IN A TABLE. DQ_CHECK drives both halves: the
-- native DMF associations (scheduled daily, visible in Horizon and in
-- SNOWFLAKE.LOCAL.DATA_QUALITY_MONITORING_*), and RUN_DQ_CHECKS, which
-- evaluates the same checks on demand so the badge has a value from the first
-- minute rather than after the first scheduled tick. One list, two consumers,
-- no chance of them disagreeing about what is checked.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE WAREHOUSE COMPUTE_WH;

-- ---------------------------------------------------------------------------
-- 1. Certification.
-- ---------------------------------------------------------------------------
ALTER SEMANTIC VIEW SEMANTIC.SC_ONTOLOGY_360  SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_SUPPLIER      SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_FULFILLMENT   SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_INVENTORY     SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_LANDED_COST   SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_DEMAND        SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_MANUFACTURING SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_OUTLOOK       SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_TELEMETRY     SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_CONTRACT      SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER SEMANTIC VIEW SEMANTIC.SC_SUPPLIER_LEGACY_DEFECT UNSET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS;

ALTER TABLE CANONICAL.FCT_SUPPLIER_DELIVERY_LINE SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER TABLE CANONICAL.FCT_ORDER_LINE_FULFILLMENT SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER TABLE CANONICAL.FCT_INVENTORY_SNAPSHOT     SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER TABLE CANONICAL.FCT_LANDED_COST_SHIPMENT   SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER TABLE CANONICAL.FCT_SHIPMENT_TELEMETRY     SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';
ALTER TABLE CANONICAL.DIM_SUPPLIER_CONTRACT      SET TAG SNOWFLAKE.CORE.CERTIFICATION_STATUS = 'CERTIFIED';

-- ---------------------------------------------------------------------------
-- 2. The checks. Nulls where a null would silently drop a row from a ratio;
--    duplicates where a duplicate key would double-count it.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE TABLE GOVERNANCE.DQ_CHECK (
  check_id     STRING NOT NULL,
  fact_table   STRING NOT NULL COMMENT 'Unqualified table name in CANONICAL.',
  column_name  STRING NOT NULL,
  dmf          STRING NOT NULL COMMENT 'NULL_COUNT or DUPLICATE_COUNT (SNOWFLAKE.CORE).',
  why          STRING NOT NULL,
  CONSTRAINT pk_dq_check PRIMARY KEY (check_id)
) COMMENT = 'The data quality checks on every canonical fact. Drives both the native DMF associations and RUN_DQ_CHECKS; expectation is always VALUE = 0.';

INSERT INTO GOVERNANCE.DQ_CHECK
SELECT * FROM VALUES
 ('sup_supplier_nn',  'FCT_SUPPLIER_DELIVERY_LINE', 'SUPPLIER_ID',      'NULL_COUNT',      'A receipt with no supplier cannot be attributed and silently leaves supplier OTD.'),
 ('sup_on_time_nn',   'FCT_SUPPLIER_DELIVERY_LINE', 'IS_ON_TIME',       'NULL_COUNT',      'AVG ignores NULL, so a null flag shrinks the denominator of supplier OTD.'),
 ('sup_receipt_nn',   'FCT_SUPPLIER_DELIVERY_LINE', 'RECEIPT_DATE',     'NULL_COUNT',      'Undated receipts escape both the reporting period and the as-of rule.'),
 ('ful_order_nn',     'FCT_ORDER_LINE_FULFILLMENT', 'ORDER_ID',         'NULL_COUNT',      'Order lines without an order cannot be drilled to or reconciled.'),
 ('ful_on_time_nn',   'FCT_ORDER_LINE_FULFILLMENT', 'IS_ON_TIME',       'NULL_COUNT',      'Same denominator risk as supplier OTD, on the customer side.'),
 ('ful_customer_nn',  'FCT_ORDER_LINE_FULFILLMENT', 'CUSTOMER_ID',      'NULL_COUNT',      'Unattributed lines drop out of every customer-grain breakdown.'),
 ('ful_ship_region_nn','FCT_ORDER_LINE_FULFILLMENT','SHIP_REGION',      'NULL_COUNT',      'The row access policy keys on SHIP_REGION; a null region is invisible to every scoped persona.'),
 ('inv_on_hand_nn',   'FCT_INVENTORY_SNAPSHOT',     'ON_HAND_QTY',      'NULL_COUNT',      'Days of inventory is SUM(on hand) / SUM(demand); a null numerator understates cover.'),
 ('inv_demand_nn',    'FCT_INVENTORY_SNAPSHOT',     'AVG_DAILY_DEMAND', 'NULL_COUNT',      'A null denominator row overstates days of inventory.'),
 ('lc_shipment_uq',   'FCT_LANDED_COST_SHIPMENT',   'SHIPMENT_ID',      'DUPLICATE_COUNT', 'A duplicated shipment double-counts its landed cost.'),
 ('lc_total_nn',      'FCT_LANDED_COST_SHIPMENT',   'TOTAL_LANDED_COST','NULL_COUNT',      'Null cost rows understate total landed cost and distort cost per unit.'),
 ('tel_shipment_uq',  'FCT_SHIPMENT_TELEMETRY',     'SHIPMENT_ID',      'DUPLICATE_COUNT', 'One telemetry summary per shipment; a duplicate double-counts an excursion.'),
 ('tel_peak_nn',      'FCT_SHIPMENT_TELEMETRY',     'PEAK_TEMP_C',      'NULL_COUNT',      'A shipment with no reading cannot be classified as an excursion or not.'),
 ('ctr_supplier_uq',  'DIM_SUPPLIER_CONTRACT',      'SUPPLIER_ID',      'DUPLICATE_COUNT', 'One governing agreement per supplier; two would make the verdict ambiguous.'),
 ('ctr_commit_nn',    'DIM_SUPPLIER_CONTRACT',      'OTD_COMMITMENT',   'NULL_COUNT',      'A contract with no extracted commitment cannot be scored - it must be in NEEDS_REVIEW instead.');

-- ---------------------------------------------------------------------------
-- 3. Native DMF associations - scheduled, visible to Horizon, one expectation
--    each. Idempotent: an association that already exists is skipped.
--    Identifiers come from DQ_CHECK, a table this file owns, and are validated
--    against INFORMATION_SCHEMA before use, so nothing user-supplied is
--    concatenated into DDL.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE GOVERNANCE.ATTACH_DQ_MONITORS()
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Attaches every DQ_CHECK as a native DMF with a VALUE = 0 expectation, scheduled daily before the drift test. Skips associations that already exist.'
  EXECUTE AS OWNER
AS
$$
DECLARE
  attached NUMBER DEFAULT 0;
  skipped NUMBER DEFAULT 0;
  c CURSOR FOR
    SELECT k.check_id, k.fact_table, k.column_name, k.dmf
      FROM GOVERNANCE.DQ_CHECK k
      JOIN SUPPLY_CHAIN.INFORMATION_SCHEMA.COLUMNS col
        ON col.table_schema = 'CANONICAL' AND col.table_name = k.fact_table AND col.column_name = k.column_name
     WHERE k.dmf IN ('NULL_COUNT', 'DUPLICATE_COUNT');
  facts CURSOR FOR SELECT DISTINCT fact_table FROM GOVERNANCE.DQ_CHECK;
  tbl STRING;
BEGIN
  FOR t IN facts DO
    tbl := 'SUPPLY_CHAIN.CANONICAL.' || t.fact_table;
    -- 05:30 UTC daily: finishes before METRIC_DRIFT_TEST at 06:00, so a bad load is
    -- flagged as a data problem before it can surface as a definition problem.
    EXECUTE IMMEDIATE 'ALTER TABLE ' || tbl || ' SET DATA_METRIC_SCHEDULE = ''USING CRON 30 5 * * * UTC''';
  END FOR;
  FOR r IN c DO
    BEGIN
      EXECUTE IMMEDIATE 'ALTER TABLE SUPPLY_CHAIN.CANONICAL.' || r.fact_table
        || ' ADD DATA METRIC FUNCTION SNOWFLAKE.CORE.' || r.dmf || ' ON (' || r.column_name || ')'
        || ' EXPECTATION ' || r.check_id || ' (VALUE = 0)';
      attached := attached + 1;
    EXCEPTION
      WHEN OTHER THEN skipped := skipped + 1;
    END;
  END FOR;
  RETURN OBJECT_CONSTRUCT('attached', attached, 'already_present_or_skipped', skipped);
END;
$$;

CALL GOVERNANCE.ATTACH_DQ_MONITORS();

-- ---------------------------------------------------------------------------
-- 4. On-demand evaluation, recorded. The badge reads the latest run.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS GOVERNANCE.DQ_CHECK_RESULT (
  run_id     STRING NOT NULL,
  run_at     TIMESTAMP_LTZ NOT NULL,
  check_id   STRING NOT NULL,
  fact_table STRING NOT NULL,
  value      NUMBER,
  passed     BOOLEAN NOT NULL
) COMMENT = 'Recorded evaluations of DQ_CHECK. The same checks the native DMFs run, evaluated on demand so the trust badge never waits for a scheduled tick.';

CREATE TABLE IF NOT EXISTS GOVERNANCE.CERTIFICATION_SNAPSHOT (
  run_id        STRING NOT NULL,
  run_at        TIMESTAMP_LTZ NOT NULL,
  semantic_view STRING NOT NULL,
  certification STRING
) COMMENT = 'SNOWFLAKE.CORE.CERTIFICATION_STATUS per semantic view, captured by RUN_DQ_CHECKS (GET_TAG needs constant arguments, so it cannot run per row in a view).';

CREATE OR REPLACE PROCEDURE GOVERNANCE.RUN_DQ_CHECKS()
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Evaluates every DQ_CHECK now with the SNOWFLAKE.CORE system DMFs and records the result in DQ_CHECK_RESULT.'
  EXECUTE AS OWNER
AS
$$
DECLARE
  rid STRING DEFAULT UUID_STRING();
  started TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP();
  v NUMBER;
  failed NUMBER DEFAULT 0;
  total NUMBER DEFAULT 0;
  c CURSOR FOR
    SELECT k.check_id, k.fact_table, k.column_name, k.dmf
      FROM GOVERNANCE.DQ_CHECK k
      JOIN SUPPLY_CHAIN.INFORMATION_SCHEMA.COLUMNS col
        ON col.table_schema = 'CANONICAL' AND col.table_name = k.fact_table AND col.column_name = k.column_name
     WHERE k.dmf IN ('NULL_COUNT', 'DUPLICATE_COUNT');
  rs RESULTSET;
  cid STRING;
  ftab STRING;
  svname STRING;
  tagval STRING;
  views CURSOR FOR SELECT name FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_VIEWS WHERE schema = 'SEMANTIC';
BEGIN
  FOR r IN c DO
    -- Cursor-record fields cannot be bound as :r.field, so copy them first.
    cid := r.check_id;
    ftab := r.fact_table;
    rs := (EXECUTE IMMEDIATE 'SELECT SNOWFLAKE.CORE.' || r.dmf || '(SELECT ' || r.column_name
           || ' FROM SUPPLY_CHAIN.CANONICAL.' || r.fact_table || ') AS V');
    LET cur CURSOR FOR rs;
    FOR row_v IN cur DO
      v := row_v.V;
    END FOR;
    INSERT INTO GOVERNANCE.DQ_CHECK_RESULT (run_id, run_at, check_id, fact_table, value, passed)
      VALUES (:rid, :started, :cid, :ftab, :v, :v = 0);
    total := total + 1;
    IF (v <> 0) THEN failed := failed + 1; END IF;
  END FOR;

  -- Certification, snapshotted in the same run. SYSTEM$GET_TAG only accepts constant
  -- arguments, so it cannot be evaluated per row inside V_TRUST_SIGNALS; one literal call
  -- per semantic view, recorded here, is the reliable read. Names come from
  -- INFORMATION_SCHEMA and are validated as plain identifiers before being inlined.
  FOR sv IN views DO
    svname := sv.name;
    IF (REGEXP_LIKE(svname, '^[A-Z_][A-Z0-9_$]*$')) THEN
      rs := (EXECUTE IMMEDIATE 'SELECT SYSTEM$GET_TAG(''SNOWFLAKE.CORE.CERTIFICATION_STATUS'', ''SUPPLY_CHAIN.SEMANTIC.'
             || svname || ''', ''SEMANTIC VIEW'') AS T');
      LET cur2 CURSOR FOR rs;
      tagval := NULL;
      FOR row_t IN cur2 DO
        tagval := row_t.T;
      END FOR;
      INSERT INTO GOVERNANCE.CERTIFICATION_SNAPSHOT (run_id, run_at, semantic_view, certification)
        VALUES (:rid, :started, :svname, :tagval);
    END IF;
  END FOR;
  RETURN OBJECT_CONSTRUCT('run_id', rid, 'checks', total, 'failed', failed);
END;
$$;

CALL GOVERNANCE.RUN_DQ_CHECKS();

-- Daily, alongside the native schedule, so the badge's evidence is never stale.
CREATE OR REPLACE TASK GOVERNANCE.DQ_CHECK_DAILY
  WAREHOUSE = COMPUTE_WH
  SCHEDULE = 'USING CRON 35 5 * * * UTC'
  COMMENT = 'Records RUN_DQ_CHECKS daily, just before the 06:00 drift test.'
AS
  CALL GOVERNANCE.RUN_DQ_CHECKS();
ALTER TASK GOVERNANCE.DQ_CHECK_DAILY RESUME;

-- ---------------------------------------------------------------------------
-- 5. One trust row per semantic view.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW GOVERNANCE.V_TRUST_SIGNALS
  COMMENT = 'Per semantic view: certification tag, data quality checks on the facts it reads, and the latest drift status of its metric bindings. The badge beside every conversational answer.'
AS
WITH latest_dq AS (
  SELECT * FROM GOVERNANCE.DQ_CHECK_RESULT
   WHERE run_id = (SELECT run_id FROM GOVERNANCE.DQ_CHECK_RESULT ORDER BY run_at DESC LIMIT 1)
),
latest_cert AS (
  SELECT semantic_view, certification FROM GOVERNANCE.CERTIFICATION_SNAPSHOT
   WHERE run_id = (SELECT run_id FROM GOVERNANCE.CERTIFICATION_SNAPSHOT ORDER BY run_at DESC LIMIT 1)
),
view_facts AS (
  SELECT DISTINCT semantic_view_name AS semantic_view, base_table_name AS fact_table
    FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_TABLES
   WHERE base_table_schema IN ('CANONICAL', 'GOVERNANCE')
),
dq AS (
  SELECT vf.semantic_view, COUNT(d.check_id) AS checks, COUNT_IF(d.passed) AS passed, MAX(d.run_at) AS checked_at
    FROM view_facts vf
    LEFT JOIN latest_dq d
      ON d.fact_table = vf.fact_table
      -- SC_CONTRACT reads the compliance view, which is built on DIM_SUPPLIER_CONTRACT.
      OR (vf.fact_table = 'V_SUPPLIER_CONTRACT_COMPLIANCE' AND d.fact_table = 'DIM_SUPPLIER_CONTRACT')
   GROUP BY vf.semantic_view
),
drift AS (
  SELECT b.semantic_view,
         COUNT(*) AS bindings,
         COUNT_IF(l.status = 'PASS') AS bindings_pass,
         MAX(l.run_at) AS drift_at
    FROM GOVERNANCE.METRIC_BINDING b
    LEFT JOIN (
      SELECT metric_id, status, run_at,
             ROW_NUMBER() OVER (PARTITION BY metric_id ORDER BY run_at DESC) AS rn
        FROM GOVERNANCE.METRIC_DRIFT_RESULT
    ) l ON l.metric_id = b.metric_id AND l.rn = 1
   GROUP BY b.semantic_view
)
SELECT
  v.name                                                                              AS semantic_view,
  cert.certification,
  COALESCE(dq.checks, 0)                                                              AS dq_checks,
  COALESCE(dq.passed, 0)                                                              AS dq_passed,
  dq.checked_at,
  COALESCE(drift.bindings, 0)                                                         AS metric_bindings,
  COALESCE(drift.bindings_pass, 0)                                                    AS bindings_drift_pass,
  drift.drift_at,
  -- Three states, not a boolean: "no checks exist" is different from "checks failed",
  -- and a badge that folded them together would under-report the gap it is meant to show.
  CASE
    WHEN COALESCE(cert.certification, '') <> 'CERTIFIED'                      THEN 'NOT_CERTIFIED'
    WHEN COALESCE(dq.checks, 0) = 0                                          THEN 'CERTIFIED_UNCHECKED'
    WHEN dq.passed < dq.checks                                               THEN 'DQ_FAILING'
    WHEN COALESCE(drift.bindings, 0) > 0 AND drift.bindings_pass < drift.bindings THEN 'DRIFTING'
    ELSE 'TRUSTED'
  END                                                                                 AS trust_level
FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_VIEWS v
LEFT JOIN latest_cert cert ON cert.semantic_view = v.name
LEFT JOIN dq    ON dq.semantic_view = v.name
LEFT JOIN drift ON drift.semantic_view = v.name
WHERE v.schema = 'SEMANTIC';

GRANT SELECT ON VIEW  GOVERNANCE.V_TRUST_SIGNALS TO ROLE SC_PLANNER;
GRANT SELECT ON VIEW  GOVERNANCE.V_TRUST_SIGNALS TO ROLE SC_PROCUREMENT;
GRANT SELECT ON VIEW  GOVERNANCE.V_TRUST_SIGNALS TO ROLE SC_LOGISTICS;
GRANT SELECT ON VIEW  GOVERNANCE.V_TRUST_SIGNALS TO ROLE SC_LOGISTICS_EU;
GRANT SELECT ON VIEW  GOVERNANCE.V_TRUST_SIGNALS TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON TABLE GOVERNANCE.DQ_CHECK        TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON TABLE GOVERNANCE.DQ_CHECK_RESULT TO ROLE SC_ONTOLOGY_STEWARD;

-- Assertions.
SELECT 'negative control is not certified' AS check_name, certification AS found,
       IFF(certification IS NULL OR certification <> 'CERTIFIED', 'PASS', 'FAIL') AS status
  FROM GOVERNANCE.V_TRUST_SIGNALS WHERE semantic_view = 'SC_SUPPLIER_LEGACY_DEFECT';

SELECT semantic_view, certification, dq_passed || '/' || dq_checks AS dq, bindings_drift_pass || '/' || metric_bindings AS drift, trust_level
  FROM GOVERNANCE.V_TRUST_SIGNALS ORDER BY semantic_view;


-- ============================================================================
-- FILE: 20_mcp_server.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 20 - One answer in every tool: a Snowflake-managed MCP server.
--
-- The brief asks that "any team" gets one consistent answer. Teams do not all
-- live in this app: analysts ask Claude or Copilot, engineers ask Cursor, and a
-- planner has a spreadsheet open. The Model Context Protocol lets all of those
-- call Snowflake directly, so this file exposes the governed layer - not the raw
-- tables - as an MCP server. Whatever assistant a team uses, the number it gets
-- is the registry's number.
--
-- THREE TOOLS, EACH A DIFFERENT KIND OF GUARANTEE
--   governed_metric    deterministic. Registry metric id in, the governed value
--                      out, with its definition, SCOR alignment, drift status and
--                      trust level. No model writes SQL. This is the tool that
--                      makes "0.875824 in Claude" provably the same number as
--                      "0.875824 in the app".
--   supply_chain_agent the Cortex Agent, for open questions across domains.
--   contract_search    clause text from supplier agreements, as evidence.
--
-- NO SYSTEM_EXECUTE_SQL, DELIBERATELY. Snowflake's own guidance: exposing raw SQL
-- on the server a business user talks to lets the client bypass the semantic
-- views, the verified queries and the drift contract. The whole point is that it
-- cannot.
--
-- CALLER'S RIGHTS, DELIBERATELY. MCP sessions run as the connecting user's role.
-- GOVERNED_METRIC is EXECUTE AS CALLER and queries through SC_ONTOLOGY_360, so
-- the caller's grants and the RAP_SHIP_REGION row access policy apply exactly as
-- they do in the app. An owner's-rights version would have been simpler and would
-- have handed an EU-scoped user all-region numbers through a side door - the
-- precise defect the persona model exists to prevent.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;
USE WAREHOUSE COMPUTE_WH;

CREATE OR REPLACE PROCEDURE GOVERNANCE.GOVERNED_METRIC(METRIC_ID STRING)
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Deterministic governed metric lookup for MCP clients. Pass a registry metric_id (or NULL / "list" for the catalogue). Runs as the caller, through SC_ONTOLOGY_360, so grants and row access policies apply.'
  EXECUTE AS CALLER
AS
$$
DECLARE
  ref STRING;
  meta VARIANT;
  catalogue VARIANT;
  rs RESULTSET;
  val FLOAT;
BEGIN
  IF (METRIC_ID IS NULL OR LOWER(TRIM(METRIC_ID)) IN ('', 'list', 'catalog', 'catalogue')) THEN
    SELECT ARRAY_AGG(OBJECT_CONSTRUCT('metric_id', d.metric_id, 'business_name', d.business_name,
                                      'unit', d.unit, 'domain', d.domain, 'scor', s.scor_code))
             WITHIN GROUP (ORDER BY d.domain, d.metric_id)
      INTO :catalogue
      FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION d
      LEFT JOIN SUPPLY_CHAIN.GOVERNANCE.METRIC_SCOR_ALIGNMENT s ON s.metric_id = d.metric_id;
    RETURN OBJECT_CONSTRUCT('governed_metrics', catalogue,
                            'usage', 'Call again with one metric_id to get its governed value.');
  END IF;

  -- The id is looked up by bind, never concatenated. Only a reference found in the
  -- registry, and shaped like entity.metric, ever reaches EXECUTE IMMEDIATE.
  SELECT MAX(b.metric_reference) INTO :ref
    FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_BINDING b
   WHERE b.metric_id = LOWER(TRIM(:METRIC_ID)) AND b.semantic_view = 'SC_ONTOLOGY_360';

  IF (ref IS NULL OR NOT REGEXP_LIKE(ref, '^[a-z_][a-z0-9_]*\\.[a-z_][a-z0-9_]*$')) THEN
    RETURN OBJECT_CONSTRUCT('error', 'Not a governed metric: ' || :METRIC_ID
                            || '. Call with "list" for the catalogue. This server never derives a metric the registry does not define.');
  END IF;

  -- Aliased to V: a cursor record cannot be read by position, and the metric's own
  -- column name varies by metric.
  rs := (EXECUTE IMMEDIATE 'SELECT $1::FLOAT AS V FROM (SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 METRICS ' || ref || '))');
  LET cur CURSOR FOR rs;
  FOR r IN cur DO
    val := r.V;
  END FOR;

  SELECT OBJECT_CONSTRUCT(
           'metric_id', d.metric_id,
           'business_name', d.business_name,
           'definition', d.definition,
           'unit', d.unit,
           'owner', d.owner_role,
           'scope', 'All history, the same scope METRIC_DRIFT_TEST evaluates.',
           'scor', OBJECT_CONSTRUCT('code', s.scor_code, 'metric', s.scor_metric, 'alignment', s.alignment),
           'drift', OBJECT_CONSTRUCT('status', l.status, 'spread', l.value_spread, 'tested_at', l.run_at),
           'trust', t.trust_level,
           'target', d.target_value)
    INTO :meta
    FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION d
    LEFT JOIN SUPPLY_CHAIN.GOVERNANCE.METRIC_SCOR_ALIGNMENT s ON s.metric_id = d.metric_id
    LEFT JOIN (SELECT metric_id, status, value_spread, run_at,
                      ROW_NUMBER() OVER (PARTITION BY metric_id ORDER BY run_at DESC) AS rn
                 FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT) l
           ON l.metric_id = d.metric_id AND l.rn = 1
    LEFT JOIN SUPPLY_CHAIN.GOVERNANCE.V_TRUST_SIGNALS t ON t.semantic_view = 'SC_ONTOLOGY_360'
   WHERE d.metric_id = LOWER(TRIM(:METRIC_ID));

  RETURN OBJECT_INSERT(OBJECT_INSERT(meta, 'value', ROUND(val, 6)), 'executed_as', CURRENT_ROLE());
END;
$$;

CREATE OR REPLACE MCP SERVER GOVERNANCE.SC_ONTOLOGY_MCP
  FROM SPECIFICATION $$
  tools:
    - title: "Governed supply chain metric"
      name: "governed_metric"
      type: "GENERIC"
      identifier: "SUPPLY_CHAIN.GOVERNANCE.GOVERNED_METRIC"
      description: "Returns the single governed value of a supply chain metric (supplier_otd_pct, otd_pct, fill_rate_pct, days_of_inventory, landed_cost_per_unit, and others) with its definition, SCOR alignment, drift status and trust level. Pass metric_id='list' for the catalogue. Use this whenever a number is needed: it is deterministic and identical to every other governed surface."
      config:
        type: "procedure"
        warehouse: "COMPUTE_WH"
        query_timeout: 60
        input_schema:
          type: "object"
          properties:
            metric_id:
              type: "string"
              description: "A registry metric id, or 'list' for the catalogue."
    - title: "Supply chain ontology agent"
      name: "supply_chain_agent"
      type: "CORTEX_AGENT_RUN"
      identifier: "SNOWFLAKE_INTELLIGENCE.AGENTS.SC_ONTOLOGIST_AGENT"
      description: "Governed agent for open supply chain questions across suppliers, fulfilment, inventory, landed cost, manufacturing, demand, predictions and supplier contracts. Answers only from certified semantic views and verified queries."
    - title: "Supplier contract search"
      name: "contract_search"
      type: "CORTEX_SEARCH_SERVICE_QUERY"
      identifier: "SUPPLY_CHAIN.SEMANTIC.SUPPLIER_CONTRACT_SEARCH"
      description: "Full text of supplier agreements. Use it to quote clauses - service levels, remedies, payment and delivery terms. It returns evidence, never metric values."
  $$;

-- Access mirrors the app: every persona may ask for governed metrics (row scope
-- still applies to them), procurement and the steward may also search contracts
-- (search enforces its own USAGE grant from sql/16).
GRANT USAGE ON PROCEDURE GOVERNANCE.GOVERNED_METRIC(STRING) TO ROLE SC_PLANNER;
GRANT USAGE ON PROCEDURE GOVERNANCE.GOVERNED_METRIC(STRING) TO ROLE SC_PROCUREMENT;
GRANT USAGE ON PROCEDURE GOVERNANCE.GOVERNED_METRIC(STRING) TO ROLE SC_LOGISTICS;
GRANT USAGE ON PROCEDURE GOVERNANCE.GOVERNED_METRIC(STRING) TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON PROCEDURE GOVERNANCE.GOVERNED_METRIC(STRING) TO ROLE SC_ONTOLOGY_STEWARD;
GRANT USAGE ON MCP SERVER GOVERNANCE.SC_ONTOLOGY_MCP TO ROLE SC_PLANNER;
GRANT USAGE ON MCP SERVER GOVERNANCE.SC_ONTOLOGY_MCP TO ROLE SC_PROCUREMENT;
GRANT USAGE ON MCP SERVER GOVERNANCE.SC_ONTOLOGY_MCP TO ROLE SC_LOGISTICS;
GRANT USAGE ON MCP SERVER GOVERNANCE.SC_ONTOLOGY_MCP TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON MCP SERVER GOVERNANCE.SC_ONTOLOGY_MCP TO ROLE SC_ONTOLOGY_STEWARD;

-- Evidence: the MCP tool returns the registry's canonical number.
CALL GOVERNANCE.GOVERNED_METRIC('supplier_otd_pct');


-- ============================================================================
-- FILE: 21_ontology_demand.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 21 - Demand-driven ontology: what teams asked for, and could not have.
--
-- Every question the conversational layer declines is logged in
-- AGENT_QUESTION_LOG with its refusal reason. Read one at a time, a refusal is a
-- dead end. Read together they are the ontology's roadmap: the questions people
-- actually ask, ranked, with the metric that would answer each one.
--
-- NOT EVERY REFUSAL IS A GAP. Four kinds, and only two are work items:
--   ACCESS_DENIED        the metric exists, the persona is not granted it.
--                        Correct behaviour - the grant model working.
--   GUARDRAIL            the question is unsafe as asked (a balance summed over
--                        time, future-dated activity, an ambiguous "on-time").
--                        Correct behaviour - the ontology's rules working.
--   UNREGISTERED_METRIC  the measure already exists in a semantic view but is
--                        not in the governed registry, so it has no drift test,
--                        no target and cannot be answered. Cheap to close:
--                        one registry row and its bindings.
--   OUT_OF_SCOPE         the data is not in the ontology (margin, carbon, HR).
--                        A sourcing decision, not a modelling one.
--
-- AI_CLASSIFY does the reading; nothing here is a hand-labelled demo list. The
-- candidate list for UNREGISTERED_METRIC is built from INFORMATION_SCHEMA every
-- run - measures declared in a semantic view with no METRIC_BINDING - so the
-- moment one is promoted into the registry it stops being proposed.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;
USE WAREHOUSE COMPUTE_WH;

-- Measures that exist in a semantic view but are not governed metrics.
CREATE OR REPLACE VIEW V_UNREGISTERED_MEASURE
  COMMENT = 'Metrics declared in a semantic view with no METRIC_BINDING: answerable in principle, ungoverned in practice (no drift test, no target, not offered to the conversational layer).'
AS
SELECT
  LOWER(m.table_name) || '.' || LOWER(m.name) AS metric_reference,
  ARRAY_AGG(DISTINCT m.semantic_view_name) WITHIN GROUP (ORDER BY m.semantic_view_name) AS semantic_views,
  ANY_VALUE(m.comment) AS description
FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_METRICS m
WHERE m.semantic_view_name NOT IN ('SC_SUPPLIER_LEGACY_DEFECT', 'SC_OUTLOOK')   -- negative control; predictions have their own registry
  AND NOT EXISTS (
    SELECT 1 FROM METRIC_BINDING b
     WHERE LOWER(b.metric_reference) = LOWER(m.table_name) || '.' || LOWER(m.name))
GROUP BY 1;

CREATE TABLE IF NOT EXISTS QUESTION_DEMAND (
  question_key      STRING NOT NULL COMMENT 'Normalised question text.',
  sample_question   STRING NOT NULL,
  refusal_reason    STRING,
  times_asked       NUMBER NOT NULL,
  personas          ARRAY,
  refusal_class     STRING,
  candidate_metric  STRING COMMENT 'metric_reference from V_UNREGISTERED_MEASURE, or NULL.',
  classified_at     TIMESTAMP_LTZ NOT NULL
) COMMENT = 'Refused conversational questions, deduplicated and classified by AI_CLASSIFY into why they were refused and which unregistered measure would answer them.';

CREATE OR REPLACE PROCEDURE CLASSIFY_QUESTION_DEMAND()
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Re-classifies every distinct refused question in AGENT_QUESTION_LOG. Candidate metrics are read from V_UNREGISTERED_MEASURE at run time.'
  EXECUTE AS OWNER
AS
$$
DECLARE
  candidates STRING;
  n NUMBER;
BEGIN
  -- AI_CLASSIFY wants its category list as a constant, so the current set of
  -- unregistered measures is rendered into the statement. Every reference is
  -- validated as entity.metric before it is inlined.
  SELECT '[' || LISTAGG('{''label'': ''' || metric_reference || ''', ''description'': '''
               || REPLACE(LEFT(REGEXP_REPLACE(COALESCE(description, ''), '[^A-Za-z0-9 ,.()-]', ''), 140), '''', '') || '''}', ', ')
         || ', {''label'': ''none'', ''description'': ''No listed measure answers this question.''}]'
    INTO :candidates
    FROM V_UNREGISTERED_MEASURE
   WHERE REGEXP_LIKE(metric_reference, '^[a-z_][a-z0-9_]*\\.[a-z_][a-z0-9_]*$');

  CREATE OR REPLACE TEMPORARY TABLE _refused AS
  SELECT LOWER(TRIM(REGEXP_REPLACE(question, '[[:space:]]+', ' '))) AS question_key,
         ANY_VALUE(question)                                        AS sample_question,
         ANY_VALUE(refusal_reason)                                  AS refusal_reason,
         COUNT(*)                                                   AS times_asked,
         ARRAY_AGG(DISTINCT persona_role)                           AS personas
    FROM SUPPLY_CHAIN.GOVERNANCE.AGENT_QUESTION_LOG
   WHERE refused
   GROUP BY 1;

  CREATE OR REPLACE TEMPORARY TABLE _classified AS
  SELECT r.*,
         AI_CLASSIFY(
           'Question: ' || r.sample_question || ' | Refusal reason: ' || COALESCE(r.refusal_reason, ''),
           [
             {'label': 'ACCESS_DENIED', 'description': 'The metric exists but the asking persona is not granted the view that serves it.'},
             {'label': 'GUARDRAIL', 'description': 'Refused on purpose: ambiguous side, snapshot summed over time, future-dated activity, forecast beyond data, raw table access.'},
             {'label': 'UNREGISTERED_METRIC', 'description': 'Asks for an operational measure such as scrap, schedule adherence, forecast accuracy, stockouts or transit delay that the catalogue lacks.'},
             {'label': 'OUT_OF_SCOPE', 'description': 'Needs data the supply chain ontology does not hold: revenue, margin, emissions, headcount, customer satisfaction.'}
           ],
           {'task_description': 'Classify why a governed supply chain analytics assistant refused this question.'}
         ):labels[0]::STRING AS refusal_class
    FROM _refused r;

  -- The only dynamic step: the candidate list changes as measures are promoted.
  EXECUTE IMMEDIATE '
    CREATE OR REPLACE TEMPORARY TABLE _candidates AS
    SELECT c.question_key,
           AI_CLASSIFY(c.sample_question, ' || candidates || ',
             {''task_description'': ''Which supply chain measure would answer this question? Choose none if no listed measure fits.''}
           ):labels[0]::STRING AS candidate_metric
      FROM _classified c
     WHERE c.refusal_class = ''UNREGISTERED_METRIC''';

  DELETE FROM QUESTION_DEMAND;
  INSERT INTO QUESTION_DEMAND
  SELECT c.question_key, c.sample_question, c.refusal_reason, c.times_asked, c.personas, c.refusal_class,
         NULLIF(k.candidate_metric, 'none'), CURRENT_TIMESTAMP()
    FROM _classified c
    LEFT JOIN _candidates k USING (question_key);
  n := SQLROWCOUNT;
  RETURN OBJECT_CONSTRUCT('questions_classified', n);
END;
$$;

CALL CLASSIFY_QUESTION_DEMAND();

-- Refresh weekly: demand moves slowly, and classification is the only cost here.
CREATE OR REPLACE TASK CLASSIFY_QUESTION_DEMAND_WEEKLY
  WAREHOUSE = COMPUTE_WH
  SCHEDULE = 'USING CRON 0 7 * * 1 UTC'
  COMMENT = 'Monday 07:00 UTC: re-read the refused-question log into QUESTION_DEMAND.'
AS
  CALL SUPPLY_CHAIN.GOVERNANCE.CLASSIFY_QUESTION_DEMAND();
ALTER TASK CLASSIFY_QUESTION_DEMAND_WEEKLY RESUME;

-- The roadmap: each unregistered measure ranked by the demand it would satisfy.
CREATE OR REPLACE VIEW V_ONTOLOGY_DEMAND
  COMMENT = 'Unregistered measures ranked by how many refused questions they would answer, and for which personas. The next metrics to promote into the registry.'
AS
SELECT
  u.metric_reference,
  u.semantic_views,
  u.description,
  COUNT(q.question_key)                          AS refused_questions,
  COALESCE(SUM(q.times_asked), 0)                AS times_asked,
  ARRAY_UNION_AGG(q.personas)                    AS personas,
  ARRAY_AGG(q.sample_question) WITHIN GROUP (ORDER BY q.times_asked DESC) AS sample_questions
FROM V_UNREGISTERED_MEASURE u
LEFT JOIN QUESTION_DEMAND q ON q.candidate_metric = u.metric_reference
GROUP BY 1, 2, 3;

CREATE OR REPLACE VIEW V_REFUSAL_MIX
  COMMENT = 'Why questions were refused. ACCESS_DENIED and GUARDRAIL are the governance working; UNREGISTERED_METRIC and OUT_OF_SCOPE are the roadmap.'
AS
SELECT refusal_class,
       COUNT(*)          AS distinct_questions,
       SUM(times_asked)  AS times_asked,
       refusal_class IN ('ACCESS_DENIED', 'GUARDRAIL') AS governance_working
  FROM QUESTION_DEMAND
 GROUP BY refusal_class;

GRANT SELECT ON VIEW V_ONTOLOGY_DEMAND TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON VIEW V_REFUSAL_MIX     TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON TABLE QUESTION_DEMAND  TO ROLE SC_ONTOLOGY_STEWARD;

SELECT * FROM V_REFUSAL_MIX ORDER BY times_asked DESC;
SELECT metric_reference, refused_questions, times_asked FROM V_ONTOLOGY_DEMAND WHERE refused_questions > 0 ORDER BY times_asked DESC;


-- ============================================================================
-- FILE: 22_ci_gate.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 22 - The governance gate, for CI.
--
-- Every other control in this project runs on a schedule. A schedule finds a
-- broken definition the morning after it merged. This procedure lets the same
-- controls run on a pull request, so a change that would make two teams get two
-- answers is blocked before it merges instead of reported after.
--
-- It RAISES on failure. `snow sql -q "CALL ..."` then exits non-zero, GitHub
-- marks the check red, and branch protection blocks the merge. A gate that
-- returned 'FAIL' as a string would be green in CI while saying red in its output.
--
-- What it asserts (each already exists elsewhere; the gate only composes them):
--   1. METRIC_DRIFT_TEST: every binding resolves to its canonical value.
--   2. RUN_DQ_CHECKS: every data quality check on every canonical fact passes.
--   3. The negative control is still wrong AND still uncertified - a gate that
--      only ever passes is indistinguishable from one that is not running, so
--      the deliberately defective view must keep drifting, and must never carry
--      the trusted-source tag.
--   4. Contract extraction accuracy has not regressed below 98%.
--   5. Every registered metric has a SCOR alignment.
--
-- The CI principal gets USAGE on this procedure and nothing else. The procedure
-- runs as its owner, so CI needs no grants on the data it checks.
-- The service user itself is created separately, after review:
-- sql/ci/create_ci_user.sql.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE OR REPLACE PROCEDURE CI_GOVERNANCE_GATE()
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'CI governance gate: drift, data quality, negative control, extraction accuracy, SCOR coverage. Raises on any failure so the CI job fails.'
  EXECUTE AS OWNER
AS
$$
DECLARE
  drift_fail NUMBER;
  drift_total NUMBER;
  control_spread FLOAT;
  control_cert STRING;
  dq_fail NUMBER;
  dq_total NUMBER;
  extraction FLOAT;
  unmapped NUMBER;
  failures ARRAY DEFAULT ARRAY_CONSTRUCT();
  gate_failed EXCEPTION (-20001, 'Governance gate failed - see the failures list in the procedure output.');
BEGIN
  CALL SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST();
  SELECT COUNT_IF(status <> 'PASS'), COUNT(*) INTO :drift_fail, :drift_total
    FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
   WHERE run_id = (SELECT run_id FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT ORDER BY run_at DESC LIMIT 1);
  IF (drift_fail > 0 OR drift_total = 0) THEN
    failures := ARRAY_APPEND(failures, drift_fail || ' of ' || drift_total || ' metric bindings drifted from their canonical value');
  END IF;

  -- The negative control must still be caught: it is the proof the drift test can fail.
  SELECT MAX(ABS(legacy_otd - governed_otd)) INTO :control_spread FROM SUPPLY_CHAIN.GOVERNANCE.V_SUPPLIER_OTD_VERDICT;
  IF (control_spread IS NULL OR control_spread = 0) THEN
    failures := ARRAY_APPEND(failures, 'negative control no longer diverges - the drift test has lost its proof that it can fail');
  END IF;

  CALL SUPPLY_CHAIN.GOVERNANCE.RUN_DQ_CHECKS();
  SELECT COUNT_IF(NOT passed), COUNT(*) INTO :dq_fail, :dq_total
    FROM SUPPLY_CHAIN.GOVERNANCE.DQ_CHECK_RESULT
   WHERE run_id = (SELECT run_id FROM SUPPLY_CHAIN.GOVERNANCE.DQ_CHECK_RESULT ORDER BY run_at DESC LIMIT 1);
  IF (dq_fail > 0 OR dq_total = 0) THEN
    failures := ARRAY_APPEND(failures, dq_fail || ' of ' || dq_total || ' data quality checks failed');
  END IF;

  SELECT MAX(certification) INTO :control_cert
    FROM SUPPLY_CHAIN.GOVERNANCE.V_TRUST_SIGNALS WHERE semantic_view = 'SC_SUPPLIER_LEGACY_DEFECT';
  IF (control_cert = 'CERTIFIED') THEN
    failures := ARRAY_APPEND(failures, 'the deliberately defective view carries the CERTIFIED tag');
  END IF;

  SELECT extraction_accuracy INTO :extraction FROM SUPPLY_CHAIN.GOVERNANCE.V_CONTRACT_IMPACT;
  IF (extraction IS NULL OR extraction < 0.98) THEN
    failures := ARRAY_APPEND(failures, 'contract extraction accuracy ' || COALESCE(extraction::STRING, 'unknown') || ' is below 0.98');
  END IF;

  SELECT COUNT(*) INTO :unmapped FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION d
   WHERE NOT EXISTS (SELECT 1 FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_SCOR_ALIGNMENT a WHERE a.metric_id = d.metric_id);
  IF (unmapped > 0) THEN
    failures := ARRAY_APPEND(failures, unmapped || ' registered metric(s) have no SCOR alignment');
  END IF;

  IF (ARRAY_SIZE(failures) > 0) THEN
    -- Recorded before raising, so the failed run is inspectable after CI has gone red.
    INSERT INTO SUPPLY_CHAIN.GOVERNANCE.CI_GATE_RUN (run_at, passed, failures)
      SELECT CURRENT_TIMESTAMP(), FALSE, :failures;
    RAISE gate_failed;
  END IF;

  INSERT INTO SUPPLY_CHAIN.GOVERNANCE.CI_GATE_RUN (run_at, passed, failures)
    SELECT CURRENT_TIMESTAMP(), TRUE, ARRAY_CONSTRUCT();
  RETURN OBJECT_CONSTRUCT('passed', TRUE,
    'drift', (drift_total - drift_fail) || '/' || drift_total,
    'data_quality', (dq_total - dq_fail) || '/' || dq_total,
    'negative_control_spread', control_spread,
    'extraction_accuracy', extraction);
END;
$$;

CREATE TABLE IF NOT EXISTS CI_GATE_RUN (
  run_at   TIMESTAMP_LTZ NOT NULL,
  passed   BOOLEAN NOT NULL,
  failures ARRAY
) COMMENT = 'Every CI_GOVERNANCE_GATE run, including the failures of a red run.';

-- The CI role: may run the gate, nothing more.
CREATE ROLE IF NOT EXISTS SC_CI_GATE COMMENT = 'CI principal role. USAGE on the governance gate only.';
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE SC_CI_GATE;
GRANT USAGE ON DATABASE SUPPLY_CHAIN TO ROLE SC_CI_GATE;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_CI_GATE;
GRANT USAGE ON PROCEDURE CI_GOVERNANCE_GATE() TO ROLE SC_CI_GATE;
GRANT SELECT ON TABLE CI_GATE_RUN TO ROLE SC_ONTOLOGY_STEWARD;

CALL CI_GOVERNANCE_GATE();


-- ============================================================================
-- FILE: 23_contract_digest.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 23 - The weekly contract-breach digest: the finding, delivered to a person.
--
-- A dashboard waits to be opened. The penalty a legacy definition hides is only
-- recovered if someone in procurement reads about it, so every Monday this sends
-- the steward the same figures /impact shows: breaches, claimable penalties, the
-- share hidden by the legacy definition, the suppliers behind them, the
-- definition conflicts to renegotiate, and any extraction waiting for review.
--
-- Uses SC_GOVERNANCE_EMAIL from sql/06 (Snowflake only delivers to verified
-- users' addresses in the account). CONTRACT_BREACH_DIGEST(FALSE) previews the
-- email without sending it; the task sends.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;
USE WAREHOUSE COMPUTE_WH;

CREATE OR REPLACE PROCEDURE CONTRACT_BREACH_DIGEST(P_SEND BOOLEAN)
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Composes the weekly contract-breach digest from V_CONTRACT_IMPACT and V_SUPPLIER_CONTRACT_COMPLIANCE. P_SEND = FALSE returns a preview; TRUE also emails it via SC_GOVERNANCE_EMAIL.'
  EXECUTE AS OWNER
AS
$$
DECLARE
  subject STRING;
  body STRING;
  top_lines STRING;
  conflict_lines STRING;
  recipient STRING;
BEGIN
  SELECT LISTAGG('  - ' || supplier_name || ' (' || supplier_region || '): governed OTD '
                 || TRIM(TO_VARCHAR(governed_otd, '0.0000')) || ' vs contracted ' || TRIM(TO_VARCHAR(otd_commitment, '0.00'))
                 || IFF(compliance_status = 'HIDDEN_BREACH', ' [HIDDEN - legacy dashboard shows compliant]', '')
                 || ', claimable $' || TRIM(TO_VARCHAR(penalty_exposure_usd, '999,999')), '\n')
           WITHIN GROUP (ORDER BY IFF(compliance_status = 'HIDDEN_BREACH', 0, 1), penalty_exposure_usd DESC)
    INTO :top_lines
    FROM (SELECT * FROM V_SUPPLIER_CONTRACT_COMPLIANCE WHERE breach_governed
          ORDER BY IFF(compliance_status = 'HIDDEN_BREACH', 0, 1), penalty_exposure_usd DESC LIMIT 10);

  SELECT LISTAGG('  - ' || supplier_name || ' (' || contract_number || ')', '\n') WITHIN GROUP (ORDER BY supplier_name)
    INTO :conflict_lines
    FROM (SELECT * FROM V_SUPPLIER_CONTRACT_COMPLIANCE WHERE definition_conflict ORDER BY supplier_name LIMIT 5);

  SELECT 'Supply chain contracts: ' || hidden_breaches || ' hidden breaches, $'
           || TRIM(TO_VARCHAR(penalty_missed_by_legacy_usd, '999,999,999')) || ' unclaimed',
         'Weekly contract-breach digest - governed supplier OTD vs signed commitments.\n\n'
         || 'Claimable penalties:     $' || TRIM(TO_VARCHAR(penalty_exposure_usd, '999,999,999')) || ' across ' || breaches_governed || ' suppliers\n'
         || 'Hidden by legacy metric: $' || TRIM(TO_VARCHAR(penalty_missed_by_legacy_usd, '999,999,999')) || ' across ' || hidden_breaches || ' suppliers\n'
         || 'Definition conflicts:    ' || definition_conflicts || ' contracts measure OTD as a monthly average\n'
         || 'Awaiting human review:   ' || needs_review || ' extraction(s)\n'
         || 'Extraction accuracy:     ' || TRIM(TO_VARCHAR(extraction_accuracy * 100, '990.0')) || '% of fields vs ground truth\n\n'
         || 'Top breaches (hidden first):\n' || COALESCE(:top_lines, '  none') || '\n\n'
         || 'Contracts to renegotiate onto the governed definition (first 5 of ' || definition_conflicts || '):\n'
         || COALESCE(:conflict_lines, '  none') || '\n\n'
         || 'Source: SUPPLY_CHAIN.GOVERNANCE.V_SUPPLIER_CONTRACT_COMPLIANCE. OTD is read from the governed '
         || 'V_SUPPLIER_OTD_VERDICT, never recomputed. Targets and penalty terms are illustrative; the arithmetic is not.'
    INTO :subject, :body
    FROM V_CONTRACT_IMPACT;

  -- The recipient is account-specific and set by sql/06 (NOTIFICATION_SETTING).
  SELECT MAX(setting_value) INTO :recipient
    FROM NOTIFICATION_SETTING WHERE setting_key = 'STEWARD_EMAIL';
  IF (P_SEND AND recipient IS NOT NULL) THEN
    CALL SYSTEM$SEND_EMAIL('SC_GOVERNANCE_EMAIL', :recipient, :subject, :body);
  END IF;
  RETURN OBJECT_CONSTRUCT('sent', P_SEND AND recipient IS NOT NULL, 'recipient', recipient, 'subject', subject, 'body', body);
END;
$$;

CREATE OR REPLACE TASK CONTRACT_BREACH_DIGEST_WEEKLY
  WAREHOUSE = COMPUTE_WH
  SCHEDULE = 'USING CRON 30 7 * * 1 UTC'
  COMMENT = 'Monday 07:30 UTC: email the contract-breach digest to the ontology steward.'
AS
  CALL SUPPLY_CHAIN.GOVERNANCE.CONTRACT_BREACH_DIGEST(TRUE);
-- Created SUSPENDED on purpose: resuming it sends real email every Monday. Turn it on deliberately:
--   ALTER TASK SUPPLY_CHAIN.GOVERNANCE.CONTRACT_BREACH_DIGEST_WEEKLY RESUME;
ALTER TASK CONTRACT_BREACH_DIGEST_WEEKLY SUSPEND;

-- Preview only - nothing is sent by the build.
CALL CONTRACT_BREACH_DIGEST(FALSE);


-- ============================================================================
-- FILE: 24_value_chain.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 24 — SC_VALUE_CHAIN: the brief's chain, literally.
--
--   Supplier ──supplies──▶ Part ──made at──▶ Plant
--                                              │ ships from
--                                              ▼
--   Customer ◀──placed by── Customer Order ◀── Shipment
--
-- SC_ONTOLOGY_360 already covers every domain, but it names entities after the
-- facts they come from (PURCHASE_ORDER, ORDER_FULFILLMENT, LANDED_COST, NODE).
-- This view exposes the same data under the business chain a planner, buyer or
-- logistics lead draws on a whiteboard, with Shipment and Customer Order as
-- first-class entities and Plant as the ship-from / make-at location.
--
-- SAME DEFINITIONS, NOT NEW ONES. Every metric below is the exact expression
-- from SC_ONTOLOGY_360 over the exact same canonical fact. The drift test
-- (04_drift_schedule) and the parity block at the bottom of this file assert the
-- values are identical, so adding a view cannot create a second answer.
--
-- GOVERNANCE. V_SHIPMENT is a plain view over FCT_LANDED_COST_SHIPMENT, so the
-- RAP_SHIP_REGION row access policy on that table still applies; SC_LOGISTICS_EU
-- sees only EU shipments here exactly as it does in the 360 view.
--
-- Idempotent: CREATE OR REPLACE throughout, safe to re-run.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE WAREHOUSE COMPUTE_WH;

CREATE OR REPLACE VIEW CANONICAL.V_SHIPMENT
  COMMENT = 'One row per shipment with its ship-from node resolved through the transport lane. Inherits RAP_SHIP_REGION from FCT_LANDED_COST_SHIPMENT.'
AS
SELECT s.*, l.origin_node AS ship_from_node_id
  FROM CANONICAL.FCT_LANDED_COST_SHIPMENT s
  JOIN RAW.LANE l ON l.lane_id = s.lane_id;

CREATE OR REPLACE SEMANTIC VIEW SEMANTIC.SC_VALUE_CHAIN
  TABLES (
    SUPPLIER as SUPPLY_CHAIN.RAW.SUPPLIER primary key (SUPPLIER_ID)
      with synonyms=('supplier','vendor')
      comment='sco:Supplier - first link of the chain. Conformed dimension.',
    PART as SUPPLY_CHAIN.RAW.PART primary key (MATERIAL_ID)
      with synonyms=('part','material','sku','item')
      comment='sco:Material - what suppliers supply, plants make and customers order. Conformed dimension.',
    PLANT as SUPPLY_CHAIN.RAW.NODE primary key (NODE_ID)
      with synonyms=('plant','site','ship-from','origin','factory','dc','warehouse')
      comment='sco:Location - where parts are made (PLANT) and where shipments leave from (PLANT or DC). Conformed dimension.',
    CUSTOMER as SUPPLY_CHAIN.RAW.CUSTOMER primary key (CUSTOMER_ID)
      with synonyms=('customer','account','client')
      comment='sco:Customer - last link of the chain. Conformed dimension.',
    SUPPLY as SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE primary key (PO_ID, LINE)
      with synonyms=('supply','purchase order','po','receipt','inbound')
      comment='sco:InboundReceipt - Supplier supplies Part. Fact, receipt-line grain.',
    PRODUCTION as SUPPLY_CHAIN.RAW.PRODUCTION_ORDER primary key (PRODUCTION_ORDER_ID)
      with synonyms=('production','production order','work order','build')
      comment='sco:ProductionOrder - Part made at Plant. Fact, order grain.',
    CUSTOMER_ORDER as SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT primary key (ORDER_ID, ORDER_LINE)
      with synonyms=('customer order','sales order','order','order line')
      comment='sco:CustomerOrder - Customer orders Part. Fact, order-line grain.',
    SHIPMENT as SUPPLY_CHAIN.CANONICAL.V_SHIPMENT primary key (SHIPMENT_ID)
      with synonyms=('shipment','delivery','consignment','freight')
      comment='sco:Shipment - fulfils one Customer Order line, ships from a Plant or DC. Fact, shipment grain.'
  )
  RELATIONSHIPS (
    SUPPLY_TO_SUPPLIER as SUPPLY(SUPPLIER_ID) references SUPPLIER(SUPPLIER_ID),
    SUPPLY_TO_PART as SUPPLY(MATERIAL_ID) references PART(MATERIAL_ID),
    PRODUCTION_TO_PART as PRODUCTION(MATERIAL_ID) references PART(MATERIAL_ID),
    PRODUCTION_TO_PLANT as PRODUCTION(NODE_ID) references PLANT(NODE_ID),
    SHIPMENT_TO_PLANT as SHIPMENT(SHIP_FROM_NODE_ID) references PLANT(NODE_ID),
    SHIPMENT_TO_ORDER as SHIPMENT(ORDER_ID, ORDER_LINE) references CUSTOMER_ORDER(ORDER_ID, ORDER_LINE),
    ORDER_TO_PART as CUSTOMER_ORDER(MATERIAL_ID) references PART(MATERIAL_ID),
    ORDER_TO_CUSTOMER as CUSTOMER_ORDER(CUSTOMER_ID) references CUSTOMER(CUSTOMER_ID)
  )
  FACTS (
    SUPPLY.ON_TIME as supply.is_on_time comment='1 when the receipt met the promised date.',
    SUPPLY.IN_FULL as supply.is_in_full comment='1 when the full ordered quantity was received.',
    PRODUCTION.COMPLETED as production.completed_qty comment='Good quantity completed.',
    PRODUCTION.SCRAP as production.scrap_qty comment='Quantity scrapped.',
    PRODUCTION.PLANNED as production.planned_qty comment='Quantity planned.',
    CUSTOMER_ORDER.ON_TIME as customer_order.is_on_time comment='1 when delivered by the promise date.',
    CUSTOMER_ORDER.IN_FULL as customer_order.is_in_full comment='1 when the full ordered quantity shipped.',
    CUSTOMER_ORDER.OTIF as customer_order.is_otif comment='1 when on time and in full.',
    SHIPMENT.TOTAL_COST as shipment.total_landed_cost comment='Material + freight + duty + handling.',
    SHIPMENT.UNITS as shipment.shipped_qty comment='Units shipped.'
  )
  DIMENSIONS (
    SUPPLIER.SUPPLIER_NAME as supplier.supplier_name with synonyms=('vendor name') comment='Vendor name.',
    SUPPLIER.SUPPLIER_REGION as supplier.supplier_region with synonyms=('sourcing region','inbound region') comment='Region goods are sourced from.',
    SUPPLIER.SUPPLIER_TIER as supplier.supplier_tier with synonyms=('tier') comment='Strategic tier.',
    PART.PRODUCT_FAMILY as part.product_family with synonyms=('family','product line') comment='Product family.',
    PART.BUSINESS_SEGMENT as part.business_segment with synonyms=('segment','division') comment='Reporting segment.',
    PLANT.PLANT_NAME as plant.node_name with synonyms=('plant name','site name','ship-from name') comment='Plant or DC name.',
    PLANT.PLANT_REGION as plant.node_region with synonyms=('plant region','origin region') comment='Region the plant or DC sits in.',
    PLANT.PLANT_TYPE as plant.node_type with synonyms=('site type') comment='PLANT for manufacturing, DC for distribution.',
    CUSTOMER.CUSTOMER_NAME as customer.customer_name with synonyms=('account name') comment='Customer name.',
    CUSTOMER.CUSTOMER_REGION as customer.customer_region with synonyms=('account region') comment='Region the account is managed in.',
    CUSTOMER_ORDER.SHIP_REGION as customer_order.ship_region with synonyms=('destination region','outbound region') comment='Region goods were delivered to.',
    CUSTOMER_ORDER.DELIVERY_DATE as customer_order.delivery_date with synonyms=('delivered on') comment='Outbound event date.',
    SHIPMENT.CARRIER as shipment.carrier with synonyms=('carrier') comment='Carrier that moved the shipment.',
    SHIPMENT.LANE as shipment.lane_id with synonyms=('lane','route') comment='Transport lane.',
    SUPPLY.RECEIPT_DATE as supply.receipt_date with synonyms=('received on') comment='Inbound event date.'
  )
  METRICS (
    SUPPLY.SUPPLIER_OTD_PCT as AVG(supply.on_time)
      with synonyms=('supplier on-time delivery','inbound otd','vendor otd')
      comment='Identical definition to SC_ONTOLOGY_360.PURCHASE_ORDER.SUPPLIER_OTD_PCT.',
    SUPPLY.SUPPLIER_FILL_RATE as AVG(supply.in_full)
      with synonyms=('supplier fill rate','inbound fill rate')
      comment='Identical definition to SC_ONTOLOGY_360.PURCHASE_ORDER.SUPPLIER_FILL_RATE.',
    PRODUCTION.SCRAP_RATE as SUM(production.scrap) / NULLIF(SUM(production.planned), 0)
      with synonyms=('scrap rate','yield loss')
      comment='Identical definition to SC_ONTOLOGY_360.PRODUCTION_ORDER.SCRAP_RATE.',
    CUSTOMER_ORDER.OTD_PCT as AVG(customer_order.on_time)
      with synonyms=('on-time delivery','customer otd','otd')
      comment='Identical definition to SC_ONTOLOGY_360.ORDER_FULFILLMENT.OTD_PCT.',
    CUSTOMER_ORDER.FILL_RATE_PCT as AVG(customer_order.in_full)
      with synonyms=('fill rate','order fill rate')
      comment='Identical definition to SC_ONTOLOGY_360.ORDER_FULFILLMENT.FILL_RATE_PCT.',
    CUSTOMER_ORDER.OTIF_PCT as AVG(customer_order.otif)
      with synonyms=('otif','on time in full')
      comment='Identical definition to SC_ONTOLOGY_360.ORDER_FULFILLMENT.OTIF_PCT.',
    SHIPMENT.LANDED_COST_PER_UNIT as SUM(shipment.total_cost) / NULLIF(SUM(shipment.units), 0)
      with synonyms=('landed cost per unit','unit landed cost')
      comment='Identical definition to SC_ONTOLOGY_360.LANDED_COST.LANDED_COST_PER_UNIT. Ratio of sums.',
    SHIPMENT.SHIPMENT_COUNT as COUNT(shipment.shipment_id)
      with synonyms=('shipments','number of shipments')
      comment='Number of shipments.'
  )
  COMMENT = 'The supply chain value chain as the business draws it: Supplier -> Part -> Plant -> Shipment -> Customer Order -> Customer. Same canonical facts and metric expressions as SC_ONTOLOGY_360, so it cannot produce a different answer.'
  AI_VERIFIED_QUERIES (
    LANDED_COST_BY_SHIP_FROM_PLANT AS (
      QUESTION 'What is landed cost per unit by ship-from plant?'
      VERIFIED_AT 1791100800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_VALUE_CHAIN DIMENSIONS plant.plant_name METRICS shipment.landed_cost_per_unit) ORDER BY landed_cost_per_unit DESC'
    ),
    SHIPMENTS_BY_PLANT_TYPE AS (
      QUESTION 'How many shipments leave from plants versus DCs, and at what landed cost per unit?'
      VERIFIED_AT 1791100800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_VALUE_CHAIN DIMENSIONS plant.plant_type METRICS shipment.shipment_count, shipment.landed_cost_per_unit)'
    ),
    END_TO_END_CHAIN AS (
      QUESTION 'Show supplier on-time delivery, customer on-time delivery and landed cost per unit by product family'
      VERIFIED_AT 1791100800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_VALUE_CHAIN DIMENSIONS part.product_family METRICS supply.supplier_otd_pct, customer_order.otd_pct, shipment.landed_cost_per_unit)'
    )
  );

-- Grants: the same personas that can read the facts behind each entity.
GRANT SELECT ON VIEW CANONICAL.V_SHIPMENT TO ROLE SC_LOGISTICS;
GRANT SELECT ON VIEW CANONICAL.V_SHIPMENT TO ROLE SC_LOGISTICS_EU;
GRANT SELECT ON VIEW CANONICAL.V_SHIPMENT TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW SEMANTIC.SC_VALUE_CHAIN TO ROLE SC_PLANNER;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW SEMANTIC.SC_VALUE_CHAIN TO ROLE SC_PROCUREMENT;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW SEMANTIC.SC_VALUE_CHAIN TO ROLE SC_LOGISTICS;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW SEMANTIC.SC_VALUE_CHAIN TO ROLE SC_LOGISTICS_EU;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW SEMANTIC.SC_VALUE_CHAIN TO ROLE SC_ONTOLOGY_STEWARD;

-- Parity: the chain view must agree exactly with SC_ONTOLOGY_360 on every shared metric.
SELECT
  v.supplier_otd_pct   = o.supplier_otd_pct   AS supplier_otd_match,
  v.otd_pct            = o.otd_pct            AS otd_match,
  v.fill_rate_pct      = o.fill_rate_pct      AS fill_rate_match,
  v.landed_cost_per_unit = o.landed_cost_per_unit AS landed_cost_match
FROM SEMANTIC_VIEW(SEMANTIC.SC_VALUE_CHAIN
       METRICS supply.supplier_otd_pct, customer_order.otd_pct, customer_order.fill_rate_pct, shipment.landed_cost_per_unit) v,
     SEMANTIC_VIEW(SEMANTIC.SC_ONTOLOGY_360
       METRICS purchase_order.supplier_otd_pct, order_fulfillment.otd_pct, order_fulfillment.fill_rate_pct, landed_cost.landed_cost_per_unit) o;


-- ============================================================================
-- FILE: 25_cortex_analyst_bridge.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 25 — Cortex Analyst bridge: generate with owner's rights, execute with caller's.
--
-- Cortex Analyst validates a semantic view against its base tables before it will
-- generate SQL. The persona roles are deliberately denied RAW (00a), so a
-- persona cannot call Analyst on SC_ONTOLOGY_360 directly — Analyst returns
-- 392705 "tables ... do not exist or are not authorized".
--
-- Rather than widening the personas, generation and execution are split:
--
--   1. ASK_CORTEX_ANALYST runs EXECUTE AS OWNER under SC_ANALYST_SQLGEN, a role
--      no user holds, which can read the views' base tables. It returns Analyst's
--      SQL TEXT and metadata — never a data row.
--   2. The app (app/api/ask/analyst) checks the SQL is one read-only
--      SEMANTIC_VIEW(...) query (lib/sql-guard.ts governedStatement) and runs it
--      on a connection that has assumed the persona role with secondary roles
--      off. Grants and RAP_SHIP_REGION therefore decide what the persona sees,
--      exactly as for the registry engine.
--
-- The procedure allow-lists the semantic views it will describe, so it cannot be
-- used to probe arbitrary objects.
-- Idempotent.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;

CREATE ROLE IF NOT EXISTS SC_ANALYST_SQLGEN
  COMMENT = 'Owns ASK_CORTEX_ANALYST only. Can read the semantic views and their base tables so Cortex Analyst can validate them; never granted to a user. The procedure it owns returns SQL text, never rows.';
GRANT ROLE SC_ANALYST_SQLGEN TO ROLE SYSADMIN;
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE SC_ANALYST_SQLGEN;
GRANT USAGE ON DATABASE SUPPLY_CHAIN TO ROLE SC_ANALYST_SQLGEN;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.RAW TO ROLE SC_ANALYST_SQLGEN;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_ANALYST_SQLGEN;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.SEMANTIC TO ROLE SC_ANALYST_SQLGEN;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.RAW TO ROLE SC_ANALYST_SQLGEN;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_ANALYST_SQLGEN;
GRANT SELECT ON ALL VIEWS IN SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_ANALYST_SQLGEN;
GRANT SELECT, REFERENCES ON ALL SEMANTIC VIEWS IN SCHEMA SUPPLY_CHAIN.SEMANTIC TO ROLE SC_ANALYST_SQLGEN;
GRANT CREATE PROCEDURE ON SCHEMA SUPPLY_CHAIN.SEMANTIC TO ROLE SC_ANALYST_SQLGEN;
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_USER TO ROLE SC_ANALYST_SQLGEN;

USE ROLE SC_ANALYST_SQLGEN;
USE SECONDARY ROLES NONE;

CREATE OR REPLACE PROCEDURE SUPPLY_CHAIN.SEMANTIC.ASK_CORTEX_ANALYST(QUESTION STRING, SEMANTIC_VIEW STRING)
RETURNS VARIANT
LANGUAGE PYTHON
RUNTIME_VERSION = '3.11'
PACKAGES = ('snowflake-snowpark-python')
HANDLER = 'run'
COMMENT = 'Cortex Analyst SQL generator. Owner''s rights (SC_ANALYST_SQLGEN) so Analyst can validate the semantic view against its base tables. Returns SQL text and metadata only, never data rows; the caller executes the SQL under its own persona role.'
EXECUTE AS OWNER
AS
$$
import json
import _snowflake

ALLOWED = {
    "SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360",
    "SUPPLY_CHAIN.SEMANTIC.SC_VALUE_CHAIN",
}

def run(session, question, semantic_view):
    if semantic_view.upper() not in ALLOWED:
        return {"status": 400, "response": {"message": "semantic view not allowed"}}
    body = {
        "messages": [{"role": "user", "content": [{"type": "text", "text": question[:500]}]}],
        "semantic_view": semantic_view,
    }
    resp = _snowflake.send_snow_api_request(
        "POST", "/api/v2/cortex/analyst/message", {}, {}, body, None, 50000
    )
    content = resp.get("content")
    try:
        parsed = json.loads(content) if isinstance(content, str) else content
    except Exception:
        parsed = {"raw": str(content)[:2000]}
    return {"status": resp.get("status"), "response": parsed}
$$;

USE ROLE ACCOUNTADMIN;
GRANT USAGE ON PROCEDURE SUPPLY_CHAIN.SEMANTIC.ASK_CORTEX_ANALYST(STRING, STRING) TO ROLE SC_PLANNER;
GRANT USAGE ON PROCEDURE SUPPLY_CHAIN.SEMANTIC.ASK_CORTEX_ANALYST(STRING, STRING) TO ROLE SC_PROCUREMENT;
GRANT USAGE ON PROCEDURE SUPPLY_CHAIN.SEMANTIC.ASK_CORTEX_ANALYST(STRING, STRING) TO ROLE SC_LOGISTICS;
GRANT USAGE ON PROCEDURE SUPPLY_CHAIN.SEMANTIC.ASK_CORTEX_ANALYST(STRING, STRING) TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON PROCEDURE SUPPLY_CHAIN.SEMANTIC.ASK_CORTEX_ANALYST(STRING, STRING) TO ROLE SC_ONTOLOGY_STEWARD;


-- ============================================================================
-- FILE: 26_masking.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 26 — Column masking: material cost is commercially sensitive.
--
-- MATERIAL_COST on a shipment is standard cost times quantity — it exposes the
-- negotiated cost of goods per lane and customer, which procurement owns and
-- logistics has no need to see. Logistics still sees every freight, duty and
-- handling component and the total, so its cost-to-serve analysis is intact.
--
-- WHY THIS CANNOT CHANGE A GOVERNED NUMBER. No semantic-view fact or metric
-- references MATERIAL_COST (grep sql/ for "\.material_cost": only 00d), and
-- TOTAL_LANDED_COST is materialised at build time in 00d, so landed cost per
-- unit is identical for every persona. Masking changes what a persona can SEE in
-- the drill-down, never what a metric SAYS — which is the line between
-- governance and inconsistency.
--
-- The policy is tag-based: SC_SENSITIVITY = 'CONFIDENTIAL' carries the policy,
-- so any future column tagged CONFIDENTIAL is masked without another ALTER.
-- Idempotent.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE TAG IF NOT EXISTS SC_SENSITIVITY
  ALLOWED_VALUES 'PUBLIC', 'INTERNAL', 'CONFIDENTIAL'
  COMMENT = 'Data sensitivity. CONFIDENTIAL columns are masked by MP_CONFIDENTIAL_NUMBER for roles without a commercial need.';

CREATE MASKING POLICY IF NOT EXISTS MP_CONFIDENTIAL_NUMBER AS (val NUMBER) RETURNS NUMBER ->
  CASE
    WHEN IS_ROLE_IN_SESSION('SC_PROCUREMENT')
      OR IS_ROLE_IN_SESSION('SC_ONTOLOGY_STEWARD')
      OR IS_ROLE_IN_SESSION('SC_ANALYST_SQLGEN')
      OR IS_ROLE_IN_SESSION('ACCOUNTADMIN')
      THEN val
    ELSE NULL
  END
  COMMENT = 'Commercial cost data: visible to procurement and the steward, NULL for every other persona.';

-- Re-runnable: unset first so the SET below never fails on "already attached".
ALTER TAG SC_SENSITIVITY UNSET MASKING POLICY MP_CONFIDENTIAL_NUMBER;
ALTER TAG SC_SENSITIVITY SET MASKING POLICY MP_CONFIDENTIAL_NUMBER;

ALTER TABLE CANONICAL.FCT_LANDED_COST_SHIPMENT
  MODIFY COLUMN MATERIAL_COST SET TAG GOVERNANCE.SC_SENSITIVITY = 'CONFIDENTIAL';

-- Verification: logistics sees NULL, procurement/steward see the value, the metric is unchanged.
SELECT policy_name, policy_kind, ref_column_name, tag_name
  FROM TABLE(INFORMATION_SCHEMA.POLICY_REFERENCES(
         REF_ENTITY_NAME => 'SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT', REF_ENTITY_DOMAIN => 'table'));


-- ============================================================================
-- FILE: 27_source_systems.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 27 — Source systems: the problem the ontology exists to fix, made measurable.
--
-- The brief: "supply chain data is scattered across ERP, logistics, supplier and
-- IoT systems with inconsistent definitions, so the same question yields
-- different answers across teams."
--
-- This file models four source systems as they actually present data — their
-- own column names, date encodings and units — over the same underlying events,
-- and encodes each system's NATIVE definition of on-time delivery, as found in
-- real deployments:
--
--   ERP (SAP MM style)    EKPO/EKBE-like columns, YYYYMMDD strings.
--                         "On time" = goods receipt within the 2-day GR grace window.
--   SUPPLIER PORTAL       Supplier-reported scorecard, average of monthly rates
--                         per supplier, then averaged again (the legacy defect).
--   TMS                   Carrier events, timestamps in UTC.
--                         "On time" = delivered within 1 day of promise.
--   CRM / ORDER MGMT      Order-header grain: an order is on time only if every
--                         line is.
--   IOT                   Sensor temperature in Fahrenheit (canonical is Celsius).
--
-- GOVERNANCE.V_SOURCE_DEFINITION_SPREAD then asks "what is our OTD?" of every
-- source and of the governed semantic view. The sources disagree with each other;
-- the governed metric gives one answer for every persona. The spread is computed
-- live, never typed into a slide.
--
-- Synthetic data, real arithmetic: every source view reads the same canonical
-- facts the governed metric is defined over, so the disagreement is purely
-- definitional — which is exactly the failure mode the brief describes.
-- Idempotent.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;

CREATE SCHEMA IF NOT EXISTS SOURCE_SYSTEMS
  COMMENT = 'Source-system presentations of the same events (ERP, supplier portal, TMS, CRM, IoT), each with native names, encodings, units and its own metric definition. Not read by the app or any persona; exists to measure the divergence the ontology removes.';

-- ERP: SAP MM-style purchase order history.
CREATE OR REPLACE VIEW SOURCE_SYSTEMS.ERP_EKBE_GOODS_RECEIPT
  COMMENT = 'ERP goods receipts. EBELN/EBELP = PO/line, LIFNR = vendor, MATNR = material, EINDT = delivery date due, BUDAT = posting date (YYYYMMDD strings), MENGE = quantity.'
AS
SELECT po_id                              AS EBELN,
       line                               AS EBELP,
       supplier_id                        AS LIFNR,
       material_id                        AS MATNR,
       TO_CHAR(promised_date, 'YYYYMMDD') AS EINDT,
       TO_CHAR(receipt_date,  'YYYYMMDD') AS BUDAT,
       ordered_qty                        AS MENGE_BESTELLT,
       received_qty                       AS MENGE
  FROM CANONICAL.FCT_SUPPLIER_DELIVERY_LINE;

-- TMS: carrier delivery events.
CREATE OR REPLACE VIEW SOURCE_SYSTEMS.TMS_DELIVERY_EVENT
  COMMENT = 'TMS delivery events. SHPMT_REF = order/line, CARRIER_SCAC, PROMISE_TS_UTC and POD_TS_UTC (proof of delivery) as timestamps.'
AS
SELECT order_id || '-' || order_line             AS SHPMT_REF,
       carrier                                   AS CARRIER_SCAC,
       promise_date::TIMESTAMP_NTZ               AS PROMISE_TS_UTC,
       delivery_date::TIMESTAMP_NTZ              AS POD_TS_UTC,
       ship_region                               AS DEST_ZONE
  FROM CANONICAL.FCT_ORDER_LINE_FULFILLMENT;

-- CRM / order management: order headers.
CREATE OR REPLACE VIEW SOURCE_SYSTEMS.CRM_ORDER_HEADER
  COMMENT = 'Order-management header status. One row per customer order; LATE_FLAG is set if any line missed its promise date.'
AS
SELECT order_id                         AS SALES_DOC,
       MAX(customer_id)                 AS SOLD_TO,
       MAX(IFF(is_on_time = 0, 1, 0))   AS LATE_FLAG
  FROM CANONICAL.FCT_ORDER_LINE_FULFILLMENT
 GROUP BY order_id;

-- IoT: sensor readings in Fahrenheit.
CREATE OR REPLACE VIEW SOURCE_SYSTEMS.IOT_SENSOR_PEAK
  COMMENT = 'IoT gateway peak temperature per shipment in Fahrenheit. Canonical stores Celsius.'
AS
SELECT shipment_id                       AS DEVICE_SHIPMENT,
       ROUND(peak_temp_c * 9 / 5 + 32, 1) AS PEAK_TEMP_F,
       event_date                        AS READING_DATE
  FROM CANONICAL.FCT_SHIPMENT_TELEMETRY;

-- Where each canonical concept comes from, per source. Rendered on /ontology.
CREATE OR REPLACE TABLE GOVERNANCE.SOURCE_ATTRIBUTE_MAP (
  source_system     STRING,
  source_object     STRING,
  source_attribute  STRING,
  source_encoding   STRING,
  ontology_ref      STRING,
  transformation    STRING
) COMMENT = 'Source-to-ontology attribute mapping. One canonical attribute, many native representations.';

INSERT INTO GOVERNANCE.SOURCE_ATTRIBUTE_MAP VALUES
  ('ERP',  'ERP_EKBE_GOODS_RECEIPT', 'LIFNR',          'vendor number',        'supplier.supplier_id',          'identity'),
  ('ERP',  'ERP_EKBE_GOODS_RECEIPT', 'MATNR',          'material number',      'part.material_id',              'identity'),
  ('ERP',  'ERP_EKBE_GOODS_RECEIPT', 'EINDT',          'YYYYMMDD string',      'purchase_order.promised_date',  'TO_DATE(EINDT, ''YYYYMMDD'')'),
  ('ERP',  'ERP_EKBE_GOODS_RECEIPT', 'BUDAT',          'YYYYMMDD string',      'purchase_order.receipt_date',   'TO_DATE(BUDAT, ''YYYYMMDD'')'),
  ('ERP',  'ERP_EKBE_GOODS_RECEIPT', 'MENGE',          'units',                'purchase_order.received_qty',   'identity'),
  ('TMS',  'TMS_DELIVERY_EVENT',     'SHPMT_REF',      'order-line string',    'order_fulfillment.(order_id, order_line)', 'SPLIT_PART(SHPMT_REF, ''-'', n)'),
  ('TMS',  'TMS_DELIVERY_EVENT',     'POD_TS_UTC',     'UTC timestamp',        'order_fulfillment.delivery_date', 'POD_TS_UTC::DATE'),
  ('TMS',  'TMS_DELIVERY_EVENT',     'CARRIER_SCAC',   'carrier code',         'order_fulfillment.carrier',     'identity'),
  ('CRM',  'CRM_ORDER_HEADER',       'SOLD_TO',        'customer number',      'customer.customer_id',          'identity'),
  ('CRM',  'CRM_ORDER_HEADER',       'LATE_FLAG',      'order-header flag',    'order_fulfillment.on_time',     'NOT used: header grain cannot be re-expanded to lines'),
  ('IOT',  'IOT_SENSOR_PEAK',        'PEAK_TEMP_F',    'degrees Fahrenheit',   'shipment_telemetry.peak_temp_c', '(PEAK_TEMP_F - 32) * 5 / 9'),
  ('IOT',  'IOT_SENSOR_PEAK',        'DEVICE_SHIPMENT','shipment id',          'landed_cost.shipment_id',       'identity');

-- The same question asked of every source and of the governed layer.
CREATE OR REPLACE VIEW GOVERNANCE.V_SOURCE_DEFINITION_SPREAD
  COMMENT = 'Answer to "what is our on-time delivery?" from each source system''s native definition versus the governed metric. Computed live from the same canonical events.'
AS
WITH erp AS (
  SELECT AVG(IFF(DATEDIFF('day', TO_DATE(EINDT, 'YYYYMMDD'), TO_DATE(BUDAT, 'YYYYMMDD')) <= 2, 1, 0)) AS v
    FROM SOURCE_SYSTEMS.ERP_EKBE_GOODS_RECEIPT
),
portal AS (
  SELECT AVG(supplier_rate) AS v
    FROM (SELECT supplier_id, AVG(otd_rate) AS supplier_rate
            FROM CANONICAL.V_SUPPLIER_OTD_BY_MONTH GROUP BY supplier_id)
),
gov_in AS (
  SELECT supplier_otd_pct AS v
    FROM SEMANTIC_VIEW(SEMANTIC.SC_ONTOLOGY_360 METRICS purchase_order.supplier_otd_pct)
),
tms AS (
  SELECT AVG(IFF(DATEDIFF('day', PROMISE_TS_UTC, POD_TS_UTC) <= 1, 1, 0)) AS v
    FROM SOURCE_SYSTEMS.TMS_DELIVERY_EVENT
),
crm AS (
  SELECT 1 - AVG(LATE_FLAG) AS v FROM SOURCE_SYSTEMS.CRM_ORDER_HEADER
),
gov_out AS (
  SELECT otd_pct AS v
    FROM SEMANTIC_VIEW(SEMANTIC.SC_ONTOLOGY_360 METRICS order_fulfillment.otd_pct)
)
SELECT 'INBOUND'  AS direction, 'ERP (SAP MM)'     AS source_system, 'Receipt within 2-day GR grace window'          AS native_definition, (SELECT v FROM erp)     AS otd_value, FALSE AS is_governed
UNION ALL SELECT 'INBOUND',  'Supplier portal',    'Average of monthly supplier averages',           (SELECT v FROM portal),  FALSE
UNION ALL SELECT 'INBOUND',  'Governed ontology',  'purchase_order.supplier_otd_pct (line-weighted, no grace)', (SELECT v FROM gov_in), TRUE
UNION ALL SELECT 'OUTBOUND', 'TMS',                'Proof of delivery within 1 day of promise',      (SELECT v FROM tms),     FALSE
UNION ALL SELECT 'OUTBOUND', 'CRM / order mgmt',   'Order header on time only if every line is',     (SELECT v FROM crm),     FALSE
UNION ALL SELECT 'OUTBOUND', 'Governed ontology',  'order_fulfillment.otd_pct (line-weighted)',     (SELECT v FROM gov_out), TRUE;

GRANT USAGE ON SCHEMA SOURCE_SYSTEMS TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON ALL VIEWS IN SCHEMA SOURCE_SYSTEMS TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON TABLE GOVERNANCE.SOURCE_ATTRIBUTE_MAP TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON VIEW GOVERNANCE.V_SOURCE_DEFINITION_SPREAD TO ROLE SC_ONTOLOGY_STEWARD;

SELECT * FROM GOVERNANCE.V_SOURCE_DEFINITION_SPREAD;


-- ============================================================================
-- FILE: 28_persona_user_map.sql
-- ============================================================================

-- =============================================================================
-- 28  SPCS caller -> persona mapping
--
-- Inside Snowflake App Runtime there is no demo sign-in: ingress authenticates the
-- caller and injects their user name (Sf-Context-Current-User). lib/session.ts maps
-- that user to exactly one persona role here, and every data route then executes
-- under that role, so row access and masking apply to the person asking.
--
-- AN UNMAPPED CALLER IS REFUSED (HTTP 403), never served under the application's own
-- identity. That fallback is what previously made the hosted persona proof void.
--
-- Idempotent: MERGE, safe to re-run.
-- =============================================================================

USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE TABLE IF NOT EXISTS PERSONA_USER_MAP (
  user_name    STRING NOT NULL COMMENT 'Snowflake LOGIN/user name as injected by SPCS ingress. Matched case-insensitively.',
  persona_role STRING NOT NULL COMMENT 'Exactly one persona role from PERSONA_CATALOG. The caller is served only under this role.',
  granted_by   STRING DEFAULT CURRENT_USER(),
  granted_at   TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  CONSTRAINT pk_persona_user_map PRIMARY KEY (user_name)
)
COMMENT = 'Maps an SPCS-authenticated Snowflake user to one persona role. Unmapped users get no data.';

-- Seed: the account owner acts as the steward. Map real users with the same MERGE.
MERGE INTO PERSONA_USER_MAP t
USING (SELECT * FROM VALUES ('MONTY', 'SC_ONTOLOGY_STEWARD') AS v(user_name, persona_role)) s
   ON UPPER(t.user_name) = UPPER(s.user_name)
 WHEN MATCHED THEN UPDATE SET persona_role = s.persona_role
 WHEN NOT MATCHED THEN INSERT (user_name, persona_role) VALUES (s.user_name, s.persona_role);

-- A mapping to a role that is not a registered persona would be refused at request
-- time anyway; this makes the mistake visible at deploy time instead.
SELECT m.user_name, m.persona_role, IFF(p.role_name IS NULL, 'NOT A PERSONA', 'OK') AS status
  FROM PERSONA_USER_MAP m
  LEFT JOIN PERSONA_CATALOG p ON p.role_name = m.persona_role;
